The effect on vectors and linear transformations due to a change of tensor product operator is given by the following lemma and its proof.
%
Additionally, we prove a corollary that exhibits an equivalence between (1) change of tensor product operators and (2) unitary similarity of linear operators on the target space of the tensor product operators. 
%provides the relationship explicit and provides the easy means of converting one tensor product operator into another as well as converting between the corresponding Kronecker products.  We will first state and prove the lemma and show that $U_{\otimes_1,\otimes_2}$ is given in terms of the action of the two tensor product operators on the bases of $\otimes_1$ and $\otimes_2$.   Then, as an application of the lemma, for each tensor product operator $\otimes_1$, the 
%problem of finding a unitary operator $L'$ similar to $L$ that factors with respect to $\otimes_1$ is equivalent to the problem of finding a tensor product operator $\otimes_2$ with respect to which $L$ factors.

\begin{Lemma}\follows\label{le:lem1} {\em 
For $i = a,b$, let $\otimes_{i}\!: \mathcal{H}_1 \cross \mathcal{H}_2 \longrightarrow \mathcal{H}$ be two tensor product operators, and for $j = 1,2$, let $\bm{B}(\mathcal{H}_j)$ be any orthonormal basis of $\mathcal{H}_j$.  Then

[Vectors] for a uniquely determined unitary operator $W$ on $\mathcal{H}$,
\begin{equation}\label{lem1.1}
\otimes_b = W\circ \otimes_a\,,
\end{equation}
[Vectors] $W,$ the unitary operator in~(\ref{lem1.1}), is uniquely determined by satisfying:
\begin{equation}\label{lem1.2}
W(\ket{e_i}\otimes_a\ket{f_j}) = \ket{e_i}\otimes_b\ket{f_j},\ \ \mbox{for all}\ (\ket{e_i},\ket{f_j}) \in \bm{B}(\mathcal{H}_1) \cross \bm{B}(\mathcal{H}_2),
\end{equation}
[Operators] If $L_i$, $i = 1,2,$ are any two linear operators on $\mathcal{H}_i$, $i=1,2$, respectively, and $W$ is the operator in ~(\ref{lem1.1}), then $L_1 \otimes_a L_2$ and $L_1 \otimes_b L_2$ are unitarily equivalent via $W$:
\begin{equation}\label{lem1.3}
L_1 \otimes_b L_2 = W(L_1 \otimes_a L_2)W^\dagger.
\end{equation}
}
\end{Lemma} 
\textit{Proof:} The existence and uniqueness of a unitary operator $W$ satisfying~(\ref{lem1.1}) has been proved in the argument of subsection~(\ref{sse:bia2tpos}).   
Equation~(\ref{lem1.2}), explicitly useful for matrix calculations, is a trivial consequence of~(\ref{lem1.1}).  For~(\ref{lem1.3}) we have,
\[
\begin{array}{l}
(L_1 \otimes_b L_2)(\ket{x}\otimes_b \ket{y})
= L_1\ket{x} \otimes_b L_2\ket{y}
= W(L_1\ket{x} \otimes_a L_2\ket{y})\\
\rule{0pt}{3ex} \!
= W(L_1\otimes_a L_2)(\ket{x}\otimes_a \ket{y})
= W(L_1\otimes_a L_2)W^\dagger(\ket{x}\otimes_b \ket{y}).
\end{array}
\]
\hspace*{\fill}\QED

For any bipartite quantum circuit \textbf{\sf C} using $\otimes$, consider the circuit \textbf{\sf C}$^\prime$ that results from 
\textbf{\sf C} obtained by replacing $\otimes$ by $\otimes^\prime$ and every gate and observable by the result of the similarity transform $W\rule{1.5ex}{0.7pt}\,W^\dagger$.   The corollary below shows that
$\textbf{\sf C}^\prime$ is equivalent to \textbf{\sf C} in the sense that the evolution of any state $W\ket{\psi_1}$ through \textbf{\sf C}$^\prime$ to a state $W\ket{\psi_2}$ corresponds to the evolution of $\ket{\psi_1}$ through \textbf{\sf C} to $\ket{\psi_2}$.   This is shown by~(\ref{cor.2}) below.  

\begin{Corollary}\follows\label{cor:lem1} {\em
Suppose $\otimes,\,\otimes^\prime\!: \mathcal{H}_1 \cross \mathcal{H}_2 \longrightarrow \mathcal{H}$ are tensor product operators with $\otimes^\prime = W\circ \otimes$, 
$L$ is a linear operator on $\mathcal{H}$,  
and $L_1$ and $L_2$ are linear operators on $\mathcal{H}_1$ and $\mathcal{H}_2$, respectively.  Then
\begin{equation}\label{cor.1}
W^\dagger L W = L_1 \otimes L_2\ \ \mbox{if, and only if,}\ \ L = L_1 \otimes^\prime L_2\,.
\end{equation}
and for any vector $\ket{x} \in \mathcal{H}$
\begin{equation}\label{cor.2}
(WLW^\dagger)W\ket{x} = WL\ket{x}.
\end{equation}
}
\end{Corollary}
\textit{Proof}: % 
For~(\ref{cor.1}) we have,
\begin{equation}
W^\dagger L W = L_1 \otimes L_2\ \ \mbox{iff}\ \ L = W(L_1 \otimes L_2)W^\dagger = L_1 \otimes^\prime L_2\,.
\end{equation}
where the second equality follows from~(\ref{lem1.3}) in the lemma.   (\ref{cor.2}) is trivial, but nevertheless important as remarked upon above.  
\hspace*{\fill}\QED

