\section{\large Coordination of gates, measurements and tensor product operators}\label{coord}

%\begin{quote}
%Postulate 3: Quantum measurements are described by a collection $A\{M_m\}$ of
%measurement operators $\ldots$ The measurement operators satisfy the completeness equation,
%\[\sum_m M_m^\dagger M_m = I\,.\]
