for (...) { // for every row
  A->ptr_to_vals[currow] = new double[max_nnz];
  int vals_adj = 0;
  A->ptr_to_inds[currow] = new int[max_nnz];
  int inds_adj = 0;
  for (...) { // for every value
    A->ptr_to_vals[currow][vals_adj] = 27.0;
    A->ptr_to_inds[currow][inds_adj] = curcol;

