\section{Background}
\label{sec:backgrd}

To describe the coordinated motion of a pair of CCS robots between their initial and goal configurations, we first make precise several terms that have intuitive meaning. 

\begin{defn}
A region $\mathbb S \subset \Re^2$ is called \emph{centrally-symmetric} if 
$(x,y) \in \mathbb S  \implies (-x, -y) \in \mathbb S$.
\end{defn}

\begin{defn}
The \emph{Minkowski sum} of two regions $R_1, R_2 \subset \Re^2$ is the region $R_1\!+\!R_2 := \{p_1 + p_2 \,\mid \, p_1 \in R_1, p_2 \in R_2\}$ (Figure~\ref{fig:Minkowski0} and \ref{fig:Minkowski1}).
Similarly, the \emph{Minkowski difference} of $R_1, R_2 \subset \Re^2$ is the region $R_1\!-\!R_2 := \{p_1 - p_2 \,\mid \, p_1 \in R_1, p_2 \in R_2\}$. Note that if $R_1$ and $R_2$ are centrally-symmetric, then 
$R_1\!+\!R_2 = R_1\!-\!R_2$.
\end{defn}

\begin{defn}
The \emph{reach} of a set of points $\mathbb S$ in direction $\theta$, is given by 
\[r_{\mathbb S}(\theta) := \sup \{ x \cos \theta + y \sin \theta : (x,y) \in \mathbb S \}.\] 
For an angle $\theta$, the set of points that realize the supremum are called \emph{support points}, and the line oriented at angle $\frac{\pi}{2}+\theta$ passing through the support points is called the \emph{support line} (see Figure~\ref{fig:reach}). When the set $\mathbb S$ consists of a single point $S$, we write $r_S$ instead of $r_{\mathbb S}$ for ease of notation.
\end{defn}

\begin{obs}\label{obs:oppositereach}
Note that $r_{\mathbb S}(\pi +\theta) = r_{-\mathbb S}(\theta)$.
Furthermore, $r_{\mathbb S}(\theta) = r_{\widearc{\mathbb S}}(\theta)$, where 
$\widearc{\mathbb S}$ denotes the boundary of the convex hull of $\mathbb S$.
\end{obs} 

\begin{figure}[ht]
\centering
\includegraphics[ scale=0.75]{reach.pdf}
\caption{Support line $L$ and support point $p$ defining the reach of $S$ in direction $\theta$. 
}. \label{fig:reach}
\end{figure}

\begin{figure}[h!]
\centering
\includegraphics[ scale=0.75]{separation.pdf}
\caption{The separation of $\bA[A]$ from $\bB[B]$ in direction $\theta$. 
} \label{fig:separation}
\end{figure}

\begin{defn}
A generic \emph{CCS robot}, hereafter simply \emph{robot}, is a convex and centrally-symmetric region in the plane.
The \emph{placement} of robot $\bZ$ at position $Z$ in $\Re^2$, denoted $\bZ[Z]$, is formed by translating $\bZ$ so that its centre coincides with $Z$.  
Accordingly, $r_{\bZ[Z]}(\theta)= r_Z(\theta) + r_{\bZ}(\theta)$. 
We refer to $\bZ[O]$, the placement at the origin $O$, as the \emph{standard} placement of $\bZ$.
\end{defn}


\begin{defn}
An \emph{(instantaneous) configuration} of a pair of robots $(\bA, \bB)$ is just a pair of placements
$(\bA[A], \bB[B])$. 
In configuration
$(\bA[A], \bB[B])$, the \emph{separation} of $\bA[A]$ from $\bB[B]$
in direction $\theta$ is
given by 
$r_{\bA[A]}(\theta) 
- r_{\bB[B]}(\theta)
-2 r_{\bA}(\theta)$;
cf. Figure~\ref{fig:separation}.
\end{defn}

\begin{defn}
A configuration $(\bA[A], \bB[B])$ is \emph{viable} if 
$ \bA[A] \cap \bB[B] = \emptyset$;
equivalently if the separation of
$\bA[A]$ from $\bB[B]$ is non-negative for some direction $\theta$. 
For any given viable configuration $(\bA[A], \bB[B])$, 
we refer to the direction $\theta$ that maximizes the separation  
of $\bA[A]$ from $\bB[B]$ 
as its \emph{orientation}.
\end{defn}

\begin{obs}\label{obs:Minkowski}
 %Observe that t
 The Minkowski sum of two CCS robots $\bA$ and $\bB$,
 denoted $\bA\!+\!\bB$, is another CCS robot, whose reach $r_{\bA\!+\!\bB}(\theta)$ satisfies $r_{\bA\!+\!\bB}(\theta) = r_{\bA}(\theta) + r_{\bB}(\theta)$. 
 By symmetry, $\bA[A]$ intersects $\bB[B]$ if and only if point $A$ lies in $(\bA\!+\!\bB)[B]$ 
 (equivalently, point $A-B$ lies in $(\bA\!+\!\bB)[O]$);
 see Figure~\ref{fig:Minkowski1}.

 If point $\bA[A]$ does not intersect $\bB[B]$,
 then 
 (i) the separation of $\bA[A]$ from $\bB[B]$ is just the distance from $A$ to the boundary of $(\bA\!+\!\bB)[B]$, and
 (ii) the orientation of the
 configuration $(\bA[A], \bB[B])$ is just the angle, with respect to the $x$-axis, formed by the  outward normal to $(\bA\!+\!\bB)[B]$ through point $A$ 
 (equivalently, the outward normal to $(\bA\!+\!\bB)[O]$ through point $A-B$).
 Note that if $\bA$ and $\bB$ are discs, then the orientation of the
 configuration $(\bA[A], \bB[B])$ is the angle 
 $\phi_{\overrightarrow{BA}}$ formed by the vector 
 $\overrightarrow{BA}$ with the $x$-axis,
but this is not true in general. 
(For example, in Figure~\ref{fig:Minkowski1} the orientation of contact configurations changes only when the contact on $\bA$ is a corner point.)
 \end{obs}

A pair of robots can move from configuration to configuration through a coordinated motion, which we can now define:

\begin{defn}
A (translational)
\emph{motion} 
$\xi_{\bZ}$ of a robot ${\bZ}$ from placement $\bZ[Z_0]$ (i.e. position $Z_0$) to
placement $\bZ[Z_1]$ (i.e. position $Z_1$) 
is a continuous, rectifiable curve of the form $\xi_{\bZ} : [0,1] \rightarrow \Re^2$, where $\xi_{\bZ}(0) = Z_0$, and $\xi_{\bZ}(1) = Z_1$.
The set of points 
$tr(\{\xi_{\bZ}(t) \;|\; 0\le t\le 1 \})$
is called the \emph{trace} of robot $\bZ$ under motion $\xi_{\bZ}$. 
\end{defn}

\begin{defn}
The \emph{length} of motion $\xi_{\bZ}$, denoted $\ell(\xi_{\bZ})$, is simply the Euclidean arc-length of its trace, that is,
\[
	\ell(\xi_{\bZ}) = \sup_{T} \sum_{i=1}^k ||\xi_{\bZ}(t_{i-1})- \xi_{\bZ}(t_i)||
\]
where the supremum is taken over all subdivisions $T=\{t_0,t_1,\ldots,t_k\}$ of $[0,1]$ where $0 = t_0 < t_1 < \cdots < t_k = 1$. 
\end{defn}

\begin{obs}\label{obs:convex}
Denote by $\widearc{\xi_{\bZ}}$ the closed curve defining the boundary of the convex hull of the trace of $\xi_{\bZ}$. 
Since
the trace of $\xi_{\bZ}$, together with the segment $\overline{Z_0Z_1}$, forms a closed curve whose convex hull has boundary  $\widearc{\xi_{\bZ}}$, it follows from convexity that:
\begin{equation}
\label{eq:inequal}
\ell(\xi_{\bZ})\geq \ell(\widearc{\xi_{\bZ}}) - |\overline{Z_0Z_1}|
\end{equation}
\end{obs}

\begin{defn}
A motion $\xi_{\bZ}$ 
is said to be \emph{convex} if, 
equation~(\ref{eq:inequal}) is an equality; i.e. 
$\ell(\widearc{\xi_{\bZ}}) = \ell(\xi_{\bZ}) + |\overline{Z_0Z_1}|$.
\end{defn}

\begin{obs}
It follows from Observation~\ref{obs:Minkowski} that a motion of robot $\bA$ from placement $\bA[A]$ to
placement $\bA[A']$ avoiding robot $\bB$ at placement $\bB[B]$ can be viewed as the motion of a point (the centre of $\bA$), from $A$ to $A'$ avoiding $(\bA\!+\!\bB)[B]$.
\end{obs}


\begin{defn}
A \emph{coordinated motion} (hereafter \emph{co-motion}) $m$ of a robot pair $({\bA},{\bB})$ from an initial configuration  
$(\bA[A_0], \bB[B_0])$ to a goal configuration 
$(\bA[A_1], \bB[B_1])$
is a pair $(\xi_{\bA}, \xi_{\bB})$, where $\xi_{\bA}$ (resp. $\xi_{\bB}$) is a motion of $\bA$ (resp. $\bB$) from placement $\bA[A_0]$ to placement $\bA[A_1]$ (resp. placement $\bB[B_0]$ to placement $\bB[B_1]$). 
The co-motion $m$ is said to be 
\emph{collision-free}
if 
the configuration 
$(\bA[\xi_{\bA}(t)], \bB[\xi_{\bB}(t)])$ is
viable, for all $t \in [0,1]$.
Co-motion $m=(\xi_{\bA}, \xi_{\bB})$ is said to be \emph{convex} if both $\xi_{\bA}$ and $\xi_{\bB}$ are convex. Its length, denoted $\ell(m)$, 
is the sum of the lengths of its associated motions, i.e. $\ell(m) = \ell(\xi_{\bA}) + \ell(\xi_{\bB})$. 
\end{defn}

\begin{rem}
   Co-motions $m'=(\xi'_{\bA}, \xi'_{\bB})$ and $m=(\xi_{\bA}, \xi_{\bB})$ are said to be \emph{trace-equivalent} if the trace of $\xi'_{\bA}$ is the same as the trace of $\xi_{\bA}$ and the trace of
   $\xi'_{\bB}$ is the same as the trace of $\xi_{\bB}$. 
   Note that, for trace-equivalent co-motions $m$ and $m'$, $m'$ is convex if and only if $m$ is convex, and $\ell(m') = \ell(m)$. However, if $m$ is collision-free it does not necessarily follow that $m'$ is collision-free.
\end{rem}

\begin{figure}[h!]
\centering
\includegraphics[width=0.9\textwidth]
{NewExample0.pdf}
\caption{The trace of a co-motion from initial configuration (green) to target configuration (red), with intermediate configurations (yellow)}. \label{fig:introexample}
\end{figure}

Figure~\ref{fig:introexample} illustrates a co-motion (blue) of two robots from their initial configuration (green) to a goal configuration (red). 
The diamond robot first moves (straight) to its intermediate placement (orange). Then the disc robot moves around the diamond robot to its goal placement, passing through intermediate placements with boundary contact. 
Finally, the diamond robot moves (straight) to its goal placement.


\begin{defn}
The \emph{(collision-free) distance} between two configurations $\bA\bB_0=(\bA[A_0], \bB[B_0])$ and $\bA\bB_1=(\bA[A_1], \bB[B_1])$,
denoted $d(\bA\bB_0,\bA\bB_1)$, is the minimum possible length over all collision-free co-motions $m$ from $\bA\bB_0$ to $\bA\bB_1$. 
We refer to any collision-free co-motion $m$ between $\bA\bB_0$ and $\bA\bB_1$ satisfying $\ell(m) = d(\bA\bB_0,\bA\bB_1)$ as an \emph{optimal} co-motion between $\bA\bB_0$ and $\bA\bB_1$. 
\end{defn}

The fact that $d$ is a metric on the set of configurations is easy to check. Nevertheless, one may be concerned about the existence of  a shortest co-motion under this notion of distance.  The fact that a shortest co-motion exists is a consequence of the Hopf-Rinow theorem, for which details can be found in \cite{gromov}.



