\section{The general approach}
\label{sec:overview}

For the remainder of the paper, we will assume a fixed CCS robot pair 
$(\bA, \bB)$. 
We denote by $\bA\bB_0$ the initial configuration
$(\bA[A_0], \bB[B_0])$, and by $\bA\bB_1$ the goal configuration
$(\bA[A_1], \bB[B_1])$.
We denote by $[\theta_0, \theta_1]$ the range of angles counter-clockwise between the orientation $\theta_0$ of $\bA\bB_0$ and the orientation $\theta_1$ of $\bA\bB_1$.
Finally, we use $I_m$ to denote the range of orientations realized by the set of all configurations associated with a given co-motion $m$.
%
The following observation allows us to categorize co-motions into two types: 
\emph{net counter-clockwise}
co-motions satisfy $[\theta_0,\theta_1]\subseteq I_m$, and
\emph{net clockwise} co-motions satisfy
$S^1-[\theta_0,\theta_1]\subseteq I_m$, where $S^1 = [0,2\pi]$.
Co-motions satisfying $[\theta_0,\theta_1] = I_m$ (resp., 
$S^1-[\theta_0,\theta_1]= I_m$) are said to be \emph{strictly counter-clockwise}
(resp., \emph{strictly clockwise}) co-motions.

\begin{obs}
\label{monotone} Let $m = (\xi_{\bA}, \xi_{\bB})$ be any co-motion 
taking $(\bA, \bB)$ from 
initial configuration $\bA\bB_0$ and goal configuration 
$\bA\bB_1$.
By the continuity of $\xi_{\bA}$ and $\xi_{\bB}$, 
it follows that $[\theta_0,\theta_1]\subseteq I_m$ or $S^1-[\theta_0,\theta_1]\subseteq I_m$.
That is, any co-motion is either net clockwise or net counter-clockwise (or both).
\end{obs}

\begin{obs}\label{obs:flip}
If $S$ is any planar point set, denote by $\flip(S)$, the reflection of $S$ across the $x$-axis, i.e. the set $\{ (x, -y) \;|\; (x, y) \in S \}$.
Note that if $m$ is a net clockwise co-motion from configuration $\bA\bB_0$ to configuration $\bA\bB_0$, then $\flip(m)$ is a net counter-clockwise co-motion of the robot pair $(\flip(\bA), \flip(\bB))$ from configuration %$\tilde{\bA}\tilde{\bB}_0$ 
$\flip(\bA\bB_0)$ to $\flip(\bA\bB_1)$.
Thus, by the preceding Observation, in order to characterize optimal co-motions it will suffice to focus on net counter-clockwise co-motions.
In fact, as we will see, every minimum-length collision-free co-motion has a trace-equivalent collision-free co-motion whose associated configurations have orientations that change monotonically. So we can focus attention on strictly counter-clockwise co-motions.
\end{obs}

It follows directly from Observation~\ref{obs:convex} that
to determine the length of a convex co-motion $(\xi_{\bA}, \xi_{\bB})$ it suffices to be able to determine the length of the pair of closed convex curves 
$(\widearc{\xi_{\bA}}, \widearc{\xi_{\bB}})$.  
For this we follow an approach, first described by Icking et al.~\cite{icking}, that allows us to express the the length of two convex curves in terms of the reach of those curves in all directions. 
This expression is a direct application of Cauchy's surface area formula:

\begin{lem}
\label{lem:cauchyorig}
(Cauchy's surface area formula \cite[Section 5.3]{egg}) Let $C$ be a closed convex curve in the plane and $r_C(\theta)$ be the reach of $C$ in direction $\theta$. Then 
\begin{equation}
\ell(C) = \int_{S^1} r_C(\theta)d\theta.
\end{equation}
\end{lem}

As noted in \cite{icking}, it follows directly from Lemma~\ref{lem:cauchyorig} that we can find a similarly simple expression for the sum of the lengths of two convex curves in the plane:
\begin{corr}
\label{cor:cauchyorig}
Let $C_{1}$ and $C_{2}$ be closed convex curves in the plane. 
Then the
sum of their lengths can be expressed as: \label{thm:cauchy} 
%
\begin{equation}
\ell(C_{1})+\ell(C_{2}) = \int_{S^1}\left(r_{C_1}(\theta)+r_{C_2}(\pi+\theta)\right)d\theta. \label{eq:cauchy}
\end{equation}
\end{corr}

\begin{obs}\label{obs:Cauchy2}
It follows from Observation~\ref{obs:oppositereach} that (i) $r_{C_1}(\theta)+r_{C_2}(\pi+\theta) = 
r_{C_1\!-\!C_2}(\theta)$, and
(ii) $r_{C_1\!-\!C_2}(\theta) = r_{\widearc{C_1\!-\!C_2}}(\theta)$, where $\widearc{C_1\!-\!C_2}$ denotes the boundary of the convex hull of $C_1\!-\!C_2$. Thus, by another application of 
Lemma~\ref{lem:cauchyorig},
\begin{equation}
\ell(C_1) + \ell(C_2) = \ell(\widearc{C_1\!-\!C_2}). \label{eq:cauchy2}
\end{equation}
\end{obs}

The following observations show how basic properties of the co-motion $(\xi_{\bA}, \xi_{\bB})$ are reflected in the reach functions associated with the pair of convex curves $(\widearc{\xi_{\bA}}, \widearc{\xi_{\bB}})$.

\begin{obs}
\label{obs:point-wise}
If $m = (\xi_{\bA}, \xi_{\bB})$ is an arbitrary collision-free co-motion then
$r_{\widearc{\xi_{\bA}}}(\theta)
+r_{\widearc{\xi_{\bB}}}(\pi+\theta)$ 
describes the maximum separation, in direction $\theta$, realized by a point on $\widearc{\xi_{\bA}}$ and a point on   $\widearc{\xi_{\bB}}$.
If $\theta$ lies in $I_m$,
the range of orientations realized by the set of all configurations associated with $m$,
then for some $t \in [0,1]$, 
the configuration 
$(\bA[\xi_{\bA}(t)], \bB[\xi_{\bB}(t)]) $ has orientation $\theta$, and hence by the viability property and central-symmetry, 
$r_{\widearc{\xi_{\bA}}}(\theta)
+r_{\widearc{\xi_{\bB}}}(\pi+\theta) 
\ge r_{\xi_{\bA}(t)}(\theta)
+r_{\xi_{\bB}(t)}(\pi+\theta) 
\ge r_{\bA}(\theta) + r_{\bB}(\pi +\theta)
= r_{\bA\!-\!\bB}(\theta)
= r_{\bA\!+\!\bB}(\theta).$
\end{obs}

\begin{obs} Suppose that $m$ is any co-motion from 
configuration $\bA\bB_0$ to configuration $\bA\bB_1$.
Since the reach of $\widearc{\xi_{\bA}}$ is at least the reach of the segment $\overline{A_0A_1}$ and 
the reach of $\widearc{\xi_{\bB}}$ is at least the reach of the segment $\overline{B_0B_1}$
it follows that
$r_{\widearc{\xi_{\bA}}}(\theta)
+r_{\widearc{\xi_{\bB}}}(\pi+\theta) \ge r_{\overline{A_0A_1}}(\theta) + r_{\overline{B_0B_1}}(\pi +\theta)$.
Note that if 
$r_{\widearc{\xi_{\bA}}}(\theta)
+r_{\widearc{\xi_{\bB}}}(\pi+\theta) > 
r_{\overline{A_0A_1}}(\theta) + r_{\overline{B_0B_1}}(\pi +\theta)$, 
it must be the case that either 
$r_{\widearc{\xi_{\bA}}}(\theta)$
is determined by a point other than $A_0$ or $A_1$,
or
$r_{\widearc{\xi_{\bB}}}(\pi+\theta)$ is determined by a point other than $B_0$ or $B_1$.
\end{obs}

The observations above allow us to give a lower bound on the length of optimal co-motions.

\begin{lem}
\label{lem:integral}
Suppose that $m$ is any collision-free net counter-clockwise co-motion from 
configuration $\bA\bB_0$ to configuration $\bA\bB_1$.
Then 
\begin{equation*}
\ell(m) \ge  \int_{S^1} \max\left(r_{\overline{A_0A_1}}(\theta) + r_{\overline{B_0B_1}}(\pi +\theta), 
%(r_{\bA}(\theta) + r_{\bB}(\pi +\theta))
r_{\bA\!+\!\bB}(\theta)
\cdot\mathds{1}_{[\theta_0, \theta_1]}(\theta) \right) \textrm{d} \theta - |\overline{A_0A_1}| - |\overline{B_0B_1}|,
\end{equation*}
where 
$\mathds{1}_{[\theta_0, \theta_1]}$ is the 
indicator function of the range $[\theta_0, \theta_1]$. \\
