\begin{equation*}
\ell(m) \ge  \int_{S^1} \max\left(r_{\overline{A_0A_1}}(\theta) + r_{\overline{B_0B_1}}(\pi +\theta), 
r_{\bA\!+\!\bB}(\theta)
\cdot\mathds{1}_{S^1 - [\theta_0, \theta_1]}(\theta) \right) \textrm{d} \theta - |\overline{A_0A_1}| - |\overline{B_0B_1}|.
\end{equation*}
}
\end{lem}

\begin{defn}
Let $m = (\xi_{\bA}, \xi_{\bB})$ be any co-motion from 
configuration $\bA\bB_0$ to configuration $\bA\bB_1$.
The pair $(\widearc{\xi_{\bA}}, \widearc{\xi_{\bB}})$ 
is said to be \emph{counter-clockwise tight (with respect to the pair $(\bA\bB_0, \bA\bB_1)$)} 
if for all $\theta \in S^1$,
\begin{equation}\label{eqn:CCtight}
 r_{\widearc{\xi_{\bA}}}(\theta)
+r_{\widearc{\xi_{\bB}}}(\pi+\theta)=\max\left(r_{\overline{A_0A_1}}(\theta) + r_{\overline{B_0B_1}}(\pi +\theta), 
r_{\bA\!+\!\bB}(\theta)
\cdot\mathds{1}_{[\theta_0, \theta_1]}(\theta) \right), 
\end{equation}
\elide{ SKIP THIS: Similarly, 
%we say that 
$(\widearc{\xi_{\bA}}, \widearc{\xi_{\bB}})$
is said to be \emph{clockwise tight}
if for all $\theta \in S^1$,
\begin{equation}\label{eqn:Ctight}
 r_{\widearc{\xi_{\bA}}}(\theta)
+r_{\widearc{\xi_{\bB}}}(\pi+\theta)=\max\left(r_{\overline{A_0A_1}}(\theta) + r_{\overline{B_0B_1}}(\pi +\theta), 
%(r_{\bA}(\theta) + r_{\bB}(\pi +\theta))
r_{\bA\!+\!\bB}(\theta)
\cdot\mathds{1}_{S^1-[\theta_0, \theta_1]}(\theta) \right), 
\end{equation}
}
\end{defn}

\begin{obs}\label{obs:tightness} 
Let $m = (\xi_{\bA}, \xi_{\bB})$ be any co-motion from 
configuration $\bA\bB_0$ to configuration $\bA\bB_1$.
Note that the 
pair $(\widearc{\xi_{\bA}}, \widearc{\xi_{\bB}})$ 
is counter-clockwise tight if and only if for all angles $\theta$ for which $r_{\widearc{\xi_{\bA}}}(\theta)
+r_{\widearc{\xi_{\bB}}}(\pi+\theta) > r_{\overline{A_0A_1}}(\theta) + r_{\overline{B_0B_1}}(\pi +\theta)$, 
$\theta \in [\theta_0, \theta_1]$ and
$r_{\widearc{\xi_{\bA}}}(\theta)
+r_{\widearc{\xi_{\bB}}}(\pi+\theta) = r_{\bA\!+\!\bB}(\theta)$
\end{obs}



We are now in a position to state our basic tool for establishing the optimality of co-motions:

\begin{lem}
\label{lem:optkey}
Let $m = (\xi_{\bA}, \xi_{\bB})$ be any 
collision-free co-motion from initial configuration $\bA\bB_0$ to goal configuration $\bA\bB_1$.
If $m$ is net counter-clockwise and convex, and
the pair $(\widearc{\xi_{\bA}}, \widearc{\xi_{\bB}})$ 
is counter-clockwise tight
then $m$ is counter-clockwise optimal. 
\end{lem}

\begin{proof}
Let $m' = ({\xi}'_{\bA}, {\xi}'_{\bB})$ be any collision-free net counter-clockwise co-motion from $\bA\bB_0$ to $\bA\bB_1$.
It follows that
\begin{align*}
\ell(m) 
&= \ell(\xi_{\bA}) + \ell(\xi_{\bB}) \\
&= \ell(\widearc{\xi_{\bA}}) + \ell(\widearc{\xi_{\bB}}) - |\overline{A_0A_1}| - |\overline{B_0B_1}|,  \mbox{   by (1)} \\
&= \int_{S^1} \left(r_{\widearc{\xi_{\bA}}}(\theta)
+r_{\widearc{\xi_{\bB}}}(\pi+\theta) \right) 
\textrm{d} \theta -
|\overline{A_0A_1}| - |\overline{B_0B_1}|,  
\mbox{  by Corollary~\ref{cor:cauchyorig}} \\
&= \int_{S^1} \max\left(r_{\overline{A_0A_1}}(\theta) + r_{\overline{B_0B_1}}(\pi +\theta), 
r_{\bA\!+\!\bB}(\theta)
\cdot\mathds{1}_{[\theta_0,\theta_1]}(\theta) \right) -
|\overline{A_0A_1}| - |\overline{B_0B_1}|,
\mbox{  by (\ref{eqn:CCtight})}\\
&\le \ell(m'), 
\mbox{    by Lemma~\ref{lem:integral}}.
\end{align*}

\end{proof}



