\subsection{An example of a counter-clockwise optimal co-motion}
\label{sec:special}

\begin{figure}[ht]
\centering
\includegraphics[width=0.9\textwidth]
{NewExample2.pdf}
\caption{The trace of an optimal counter-clockwise co-motion from the configuration $\bA\bB_0$ (green) to the configuration $\bA\bB_1$ (red).} \label{fig:introexample3}
\end{figure}

\begin{figure}[ht]
\centering
\includegraphics[width=0.9\textwidth]
%{NewFigures/MinkowskiExample3.pdf}
{NewExample3.pdf}
\caption{The trace of another optimal counter-clockwise  co-motion from the configuration $\bA\bB_0$ (green) to the configuration $\bA\bB_1$ (red)}. \label{fig:introexample4}
\end{figure}


Before proceeding to classify all optimal co-motions for the pair $(\bA, \bB)$, it will be instructive to examine a special case, illustrated in Figure~\ref{fig:introexample3}, one of the co-motions illustrated previously in Figure~\ref{fig:introexample2}. 
This case will provide the simplest non-trivial example of a counter-clockwise optimal (though not globally optimal) co-motion, as well as an illustration of the form of the proofs that support our claims of optimality.

We define some points useful to our construction of the optimal co-motion. 
Let $a_0$ and $a_1$ be the upper tangent points from $A_0$ to 
%$s\text{-circ}(B_0)$
$(\bA\!+\!\bB)[B_0]$, and $A_1$ to %$s\text{-circ}(B_1)$ 
$(\bA\!+\!\bB)[B_1]$ respectively. 
These two tangents intersect in a point $A_\text{int}$. 
Let $b_0$ and $b_1$ be the lower tangent points from $B_0$ and $B_1$ to 
$(\bA\!+\!\bB)[A_\text{int}]$ respectively.
Note that by construction, the tangent from $A_0$ to $a_0$ passes through $A_\text{int}$ and by symmetry is parallel to the tangent from $B_0$ to $b_0$
(Similarly, the tangent from $A_1$ to $a_1$ is parallel to the tangent from $B_1$ to $b_1$.)

\begin{clm}
\label{claim:special}
The following is a counter-clockwise optimal co-motion from initial configuration $\bA\bB_0$ to goal configuration $\bA\bB_1$ (see bolded outline in Figure~\ref{fig:introexample3}):

\begin{enumerate}
\item Translate $\bA$ from position $A_0$ to position $A_\text{int}$;
\item Move $\bB$ from position $B_0$ to $B_1$, avoiding $(\bA\!+\!\bB)[A_\text{int}]$. This involves (i) translating $\bB$ from position $B_0$ to $b_0$, (ii) moving $\bB$ around the boundary of $(\bA\!+\!\bB)[A_\text{int}]$ from position $b_0$ to $b_1$, and
(iii) translating $\bB$ from position $b_1$ to $B_1$.
Then
\item Translate $\bA$ from position $A_\text{int}$ to $A_1$.
\end{enumerate}
\end{clm}

\begin{proof}
Let $\xi_{\bA}$ (respectively $\xi_{\bB}$) denote the motion of $\bA$ (respectively $\bB$), and 
$m = (\xi_{\bA}, \xi_{\bB})$.
It is straightforward to confirm that $m$ is a collision-free, convex and 
strictly counter-clockwise co-motion.
By Lemma~\ref{lem:optkey}, it remains to show that 
the pair $(\widearc{\xi_{\bA}}, \widearc{\xi_{\bB}})$
is counter-clockwise tight.

Let $\widehat{I_m}$ 
denote the range of 
orientations realized by $m$ in step 2 (i.e. counter-clockwise between the orientation of configuration 
$(\bA[A_{\rm int}], \bB[b_0])$ and the
orientation of configuration 
$(\bA[A_{\rm int}], \bB[b_1])$).
For angles  $\theta$ in $S^1 - \widehat{I_m}$, $r_{\widearc{\xi_{\bA}}}(\theta)$
is determined by one of the points $A_0$ or $A_1$,
and
$r_{\widearc{\xi_{\bB}}}(\pi+\theta)$ is determined by one of the points $B_0$ or $B_1$, 
and hence
$r_{\widearc{\xi_{\bA}}}(\theta)
+r_{\widearc{\xi_{\bB}}}(\pi+\theta) = r_{\overline{A_0A_1}}(\theta) + r_{\overline{B_0B_1}}(\pi +\theta)$.

For angles $\theta \in \widehat{I_m}$, 
$r_{\widearc{\xi_{\bA}}}(\theta)
+r_{\widearc{\xi_{\bB}}}(\pi+\theta)$
is determined by $A_{\rm int}$ and a support point on $(\bA\!+\!\bB)[A_{\rm int}]$ and hence
$r_{\widearc{\xi_{\bA}}}(\theta)
+r_{\widearc{\xi_{\bB}}}(\pi+\theta) = 
r_{\bA\!+\!\bB}(\theta)$.
Thus, for all $\theta \in S^1$, 
\begin{align*}
r_{\widearc{\xi_{\bA}}}(\theta)
+r_{\widearc{\xi_{\bB}}}(\pi+\theta) 
&= \max\left(r_{\overline{A_0A_1}}(\theta) + r_{\overline{B_0B_1}}(\pi +\theta), 
r_{\bA\!+\!\bB}(\theta)
\cdot\mathds{1}_{\widehat{I_m}}(\theta) \right)\\
&= \max\left(r_{\overline{A_0A_1}}(\theta) + r_{\overline{B_0B_1}}(\pi +\theta), 
r_{\bA\!+\!\bB}(\theta)
\cdot\mathds{1}_{I_m}(\theta) \right).
\end{align*}

\end{proof}


\begin{rem}
\label{rem:strategy}
The proof that 
the pair $(\widearc{\xi_{\bA}}, \widearc{\xi_{\bB}})$
associated with the
co-motion $m = (\xi_{\bA}, \xi_{\bB})$ in the example above 
is counter-clockwise tight, 
follows a pattern, 
supported by Observation~\ref{obs:tightness},
that we will 
use throughout
in our consideration of  convex and net counter-clockwise co-motions $m$, taking 
initial configuration
$\bA\bB_0$ to goal configuration $\bA\bB_1$.
Specifically, observe that, 
$r_{\widearc{\xi_{\bA}}}(\theta)$
is determined by either $A_0$ or $A_1$,
and $r_{\widearc{\xi_{\bB}}}(\pi+\theta)$ is determined by either $B_0$ or $B_1$ 
(and hence $r_{\widearc{\xi_{\bA}}}(\theta)
+r_{\widearc{\xi_{\bB}}}(\pi+\theta) = 
r_{\overline{A_0A_1}}(\theta) + r_{\overline{B_0B_1}}(\pi +\theta)$)
except for angles $\theta$ (all of which lie in the range $[\theta_0, \theta_1]$),
where $r_{\widearc{\xi_{\bA}}}(\theta)
+r_{\widearc{\xi_{\bB}}}(\pi+\theta) = r_{\bA\!+\!\bB}(\theta)$.
\end{rem}

\begin{obs}
\label{rem:reversal}
If the positions of $A_0$ and $A_1$ are interchanged in the co-motion $m$ of Figure~\ref{fig:introexample3}, 
there is a co-motion $m'$, specified using exactly the same steps as described in Claim~\ref{claim:special}, that has the identical  counter-clockwise tight trace (see Figure~\ref{fig:introexample4}). 
In general, this interchange of endpoints could result in a motion that is not collision-free, but whose trace is nevertheless counter-clockwise tight.
Fortunately, in such situations we can show that the globally optimal co-motion is net clockwise.
\end{obs}


