	\section{Practically Implemented FedNL Extensions}
	\label{app:extra-pesudo-code-for-fednl}



	{
		%\scriptsize
		\begin{algorithm}[H]
			%\captionsetup{font=scriptsize} 
			\caption{\algname{FedNL-LS} ({\color{blue}Baseline}. Federated Newton Learn with Line Search \cite{safaryan2021fednl} \clrshort{\textbf{[EXISTENT]}})}
			\label{alg:FedNL-LS}
			\begin{algorithmic}[1]
				\STATE \textbf{Parameters:} Hessian learning rate $\alpha\ge0$; compression operators $\{\cC_1^k, \dots,\cC_n^k\}$; {line search parameters $c \in (0,\nicefrac{1}{2}]$ and $\gamma \in (0,1)$}
				\STATE \textbf{Initialization:} $x^0\in\R^d$; $\mH_1^0, \dots, \mH_n^0 \in \R^{d\times d}$ and $\mH^0 \eqdef \frac{1}{n}\sum_{i=1}^n \mH_i^0$
				\FOR{each device $i = 1, \dots, n$ in parallel} 
				\STATE Get $x^k$ from the server; compute $f_i(x^k)$,\; $\nabla f_i(x^k)$ and $\nabla^2 f_i(x^k)$
				\STATE Send $f_i(x^k)$,\; $\nabla f_i(x^k)$ and $\mS_i^k \eqdef \cC_i^k(\nabla^2 f_i(x^k) - \mH_i^k)$ to the server
				\STATE Update local Hessian shifts $\mH_i^{k+1} = \mH_i^k + \alpha\mS_i^k$
				\ENDFOR
				\STATE On Server
				\STATE \quad Get $f_i(x^k)$,\; $\nabla f_i(x^k)$ and $\mS_i^k$ from all devices $i\in[n]$
				\STATE \quad $f(x^k) = \frac{1}{n}\sum_{i=1}^n f_i(x^k), \; \nabla f(x^k) = \frac{1}{n}\sum_{i=1}^n \nabla f_i(x^k), \; \mS^k = \frac{1}{n}\sum_{i=1}^n \mS_i^k$
				\STATE \quad {Compute search direction $d^k = [\mH^k]_\mu^{-1}\nabla f(x^k)$}
				\STATE \quad {Find the smallest integer $s\ge0$ satisfying $f(x^k+\gamma^sd^k) \le f(x^k) + c\gamma^s \langle \nabla f(x^k), d^k\rangle$}
				\STATE \quad Update global model to $x^{k+1} = x^k + \gamma^sd^k$
				\STATE \quad Update global Hessian shift to $\mH^{k+1} = \mH^k + \alpha\mS^k$
			\end{algorithmic}
		\end{algorithm}
	}

	\subsection{FedNL-LS Extension: Globalization via Line Search}
	\label{app:fednl-ls-descr}


	The first extension of \algname{FedNL} that we implemented is \algname{FedNL-LS}. We selected an algorithm in which the globalization technique remains independent of any problem-specific parameters. The pseudocode for this algorithm, presented as Algorithm \ref{alg:FedNL-LS}, has been sourced from \cite{safaryan2021fednl}. 


	The \algname{FedNL} family includes an extension incorporating a globalization strategy through cubic regularization \algname{FedNL-CR}. However, its practical implementation requires knowledge of problem-dependent $L_*$.

	\clearpage

		{
		%\scriptsize
		\begin{algorithm}[h!]
			%\captionsetup{font=scriptsize}
			\caption{\algname{FedNL-PP} ({\color{blue}Baseline}. Federated Newton Learn with Partial Participation \cite{safaryan2021fednl} \clrshort{\textbf{[EXISTENT]}})}
			\label{alg:FedNL-PP}
			\begin{algorithmic}[1]
				\STATE {\bfseries Parameters:} Hessian learning rate $\alpha>0$; compression operators $\{\cC_1^k, \dots,\cC_n^k\}$; {number of participating devices $\tau \in \{1,2,\dots,n\}$}
				\STATE {\bfseries Initialization:}
				For all $i\in [n]$: $w^0_i = x^0 \in \R^d$; $\mH_i^0 \in \R^{d\times d}$; $l_i^0 = \|\mH_i^{0} - \nabla^2 f_i(w_i^{0})\|_{\rm F}$; $g_i^0 = (\mH_i^{0} + l_i^{0} \mI)w_i^{0} - \nabla f_i(w_i^{0})$; Moreover: $\mH^0 = \frac{1}{n} \sum_{i=1}^n \mH_i^0$; $l^0 = \frac{1}{n} \sum_{i=1}^n l_i^0$; $g^0 = \frac{1}{n} \sum_{i=1}^n g_i^0$
				\STATE \textbf{on} server
				\STATE ~~~ $x^{k+1} = \left(  \mH^k + l^k\mI  \right)^{-1} g^k$ \hfill { \scriptsize Main step: Update the global model}
				\STATE ~~~ {Choose a subset $S^{k} \subseteq \{1,\dots, n\}$ of devices of cardinality $\tau$, uniformly at random}
				\STATE ~~~ Send $x^{k+1}$ to {the selected devices $i\in S^k$} \hfill { \scriptsize Communicate to selected clients}
				\FOR{each device $i = 1, \dots, n$ in parallel}
				\STATE {{\bf for participating devices} $i \in S^k$ {\bf do} }
				\STATE $w_i^{k+1} = x^{k+1}$ \hfill { \scriptsize Update local model}
				\STATE $\mH_i^{k+1} = \mH_i^k + \alpha \cC_i^k(\nabla^2 f_i(w_i^{k+1}) - \mH_i^k)$ \hfill { \scriptsize Update local Hessian estimate}
				\STATE $l_i^{k+1} = \|\mH_i^{k+1} - \nabla^2 f_i(w_i^{k+1})\|_{\rm F}$ \hfill { \scriptsize Compute local Hessian error}
				\STATE $g_i^{k+1} = (\mH_i^{k+1} + l_i^{k+1} \mI)w_i^{k+1} - \nabla f_i(w_i^{k+1})$ \hfill { \scriptsize Compute Hessian-corrected local gradient}
				\STATE Send $\cC_i^k(\nabla^2 f_i(w_i^{k+1}) - \mH_i^k)$,\; $l_i^{k+1} - l_i^k$ and $g_i^{k+1} - g_i^k$ to server \hfill { \scriptsize Communicate to server}
				\STATE { {\bf for non-participating devices} $i \notin S^k$ {\bf do} }
				\STATE $w_i^{k+1} = w_i^k$, $\mH_i^{k+1} = \mH_i^k$, $l_i^{k+1} = l_i^k$, $g_i^{k+1} = g_i^k$  \hfill { \scriptsize Do nothing}
				\ENDFOR

				\STATE On Server
				\STATE ~~~ $g^{k+1} = g^k + \frac{1}{n}\sum_{i\in S^k} \left(  g_i^{k+1} - g_i^k  \right)$  \hfill { \scriptsize Maintain the relationship $g^k = \frac{1}{n} \sum_{i=1}^n g_i^k$}
				\STATE ~~~ $\mH^{k+1} = \mH^k + \frac{\alpha}{n}\sum_{i\in S^k} \cC_i^k(\nabla^2 f_i(w_i^{k+1}) - \mH_i^k)$   \hfill { \scriptsize Update  the Hessian estimate on the server}

				\STATE ~~~ $l^{k+1} = l^k + \frac{1}{n}\sum_{i\in S^k} \left(  l_i^{k+1} - l_i^k  \right)$ \hfill { \scriptsize Maintain the relationship $l^k = \frac{1}{n} \sum_{i=1}^n l_i^k$}
			\end{algorithmic}
		\end{algorithm}
	}


