%# check satisfiability of asserted expressions
%status, assignment = sat!(isolver)
%if status == :SAT
%    # set the values of exprs
%    map( (e) -> assign!(e, assignment), exprs)
%end
%
%# Check whether some additional expressions are satisfiable.
%# Equivalent to (check-sat-assuming more_exprs)
%status, assignment = sat!(isolver, more_exprs...)
%
%# Push and pop
%push!(isolver) # push and pop default to 1
%assert!(isolver, expr1)
%status, assignment = sat!(isolver)
%if status == :UNSAT
%    pop!(isolver)
%end
%close(isolver) # clean up processes when done
%\end{minted}

% This example exposes a limitation of interactive solving; because the asserted expressions are not passed in \verb|sat!|, their values are not automatically set if a satisfying assignment is found. Instead, a dictionary containing the assignment is returned. Users can propagate these values using \verb|assign!|.
%
Additionally, \verb|Satisfiability.jl| exposes a low-level interface, allowing advanced users to send SMT commands and receive solver responses. (Users are responsible for ensuring the correctness of these commands and interpreting the results.) Thus, \verb|Satisfiability.jl| can aid advanced SMT users by generating lengthy SMT-LIB statements and programmatically interacting with solvers.

\vspace{-0.5em}
\section{Examples}
\vspace{-0.5em}
To demonstrate the compact syntax of Satisfiability.jl,
% and evaluate its performance on large problems,
we selected the ``Pigeonhole'' benchmark problem from the SMT-LIB benchmark library \cite{pigeon_benchmark}. Given an $(n+1)\times n$ integer matrix $P$, the problem is to find a satisfying assignment such that each element $P_{ij}$ is in $\{0,1\}$; for each row $i$, $\sum_{j=1}^{n+1} P_{ij} \geq 1$; and for each column $j$, $\sum_{i=1}^n P_{i,j} \leq 1$. (There are more rows than columns, so the problem is always unsatisfiable.) % Results are presented in Figure \ref{fig:pigeons}.
The benchmark is defined using the following code.
\vspace{-0.5em}
\begin{minted}[fontsize=\small]{julia1}
function pigeonhole(n::Int)
    @satvariable(P[1:n+1, 1:n], Int)
    rows = BoolExpr[sum(P[i,:]) ≥ 1 for i=1:n+1]
    cols = BoolExpr[sum(P[:,j]) ≤ 1 for j=1:n]
    status = sat!(rows, cols, P .≥ 0, P .≤ 1, solver=Z3())
    return status # should always return :UNSAT
end
\end{minted}

We also tested a graph coloring task in which \verb|Satisfiability.jl| attempts to find up to 5 colorings for each graph of size $n$, progressively adding assertions to exclude previously-found solutions. 
% We then generate an SMT-LIB script containing the same commands. This script provides a baseline for timing Z3 on the same task, although the scripted performance could not be practically achieved without prior knowledge of the results (Figure \ref{fig:graph}).
The following code defines the graph coloring task given $n$ (the number of nodes), a list of edges as $(i,j)$ pairs, a maximum number of colorings to find, and the number of available colors.
\vspace{-0.5em}
\begin{minted}[fontsize=\small]{julia1}
function graph_coloring(n::Int, edges, to_find::Int, colors::Int)
    @satvariable(nodes[1:n], Int)
    limits = and.(nodes .≥ 1, nodes .≤ colors)
    conns = cat([nodes[i] != nodes[j] for (i,j) in edges], dims=1)
    open(Z3()) do solver
    assert!(solver, limits, conns)
    i = 1
    while i ≤ to_find
        status, assignment = sat!(solver)
        if status == :SAT
            assign!(nodes, assignment)
            assert!(solver, not(and(nodes .== value(nodes))))
        else
            break
        end
        i += 1
    end
end
\end{minted}

