% \begin{align}
%     A \otimes W = A \otimes \left(\sum_{i =0} ^ {n-1} 2^iW_{i}\right) = \left(\sum_{i =0} ^ {n-1} 2^i A \otimes W_{i}\right)
% \end{align}
% Because we are considering the ternary matmul with $W$ consist (-1, 0, 1), the above equation can be simplified as,

% \begin{align}
%     A \otimes W = A \otimes W_{0} ,W_{0} \in \{-1, 0 ,1\}
