% where simple summation and subtraction can substitute the multiplication process. However, the method of selection of -1, 0, 1 to decide the summation and substraction may not be wise enough because we only have finite combinations of -1, 0, 1, and the corresponding $A$ entries' computations are repeated. Moreover, when increasing the computation parrellsim by copying the selection unit, the lut resource consumption may be larger than the Look up tables themselves, because the multiple reading port (NR) traits can support multiple access of the look-up tables with only the extra buffers for addressing. The corresponding ablation study will be presented in Sec. \ref{expr}.  

In general, the bitwise operation for mixed-precision matrix multiplication can be expressed as follows:
\begin{align}
    {\bf A} \otimes {\bf W} = {\bf A} \otimes \left(\sum_{i = 0}^{n-1} 2^i {\bf W}_{i}\right) = \left(\sum_{i = 0}^{n-1} 2^i {\bf A} \otimes {\bf W}_{i}\right)
\end{align}

Considering the ternary matrix multiplication with \( W \in \{-1, 0, 1\} \), the above equation can be simplified to:

\begin{align}
    {\bf A} \otimes {\bf W} = {\bf A} \otimes {\bf W}_{0}, \quad {\bf W_{0}} \in \{-1, 0, 1\}
\end{align}
In this case, simple summation and subtraction can replace the multiplication process. However, the method of selecting -1, 0, and 1 to determine the summation and subtraction may not be optimal, as there are only a limited number of combinations of -1, 0, and 1, leading to repetitive computations for the corresponding \( \bf A \) entries. Furthermore, when increasing computation parallelism by duplicating the selection unit of adding and subtracting path, the resource consumption of the selection may exceed that of the TL tables themselves. This is because the multiple reading ports of the on-chip distributed RAM unit can support multiple accesses to the TL tables, requiring only additional buffers for addressing. The supportive ablation study will be presented in Sec. \ref{expr}.
\begin{algorithm}
\tiny

\caption{TL-based Tenary Matmul}
\label{alg:tmac_stream}
\SetKwInOut{Input}{Input}
\SetKwInOut{Output}{Output}

\Input{
    $\bf \bf A$: Input activation stream (shape $[M][N]$)\;
    ${\bf W}_{idx}$ = Offline\_preprocess(${\bf W}$): Offline-preprocessed weight indices  (shape $[N/(T*G)][K]$)\;
}
\Output{
    $\bf O$: Output activation stream (shape $[M][K]$)\;
}
\BlankLine
Initialize:\;
\Indp
    $\mathit{TL\_TABLE}[N][3^{G}] \gets 0$ \tcp*[r]{Table for all signed combinations}
    $\mathit{A\_BLOCK}[T \times G ] \gets 0$ \tcp*[r]{Activation buffer}
    $\mathit{O\_BLOCK}[K] \gets 0$ \tcp*[r]{Output vector accumulator}
\Indm

\For{$i \gets 0$ \KwTo $M - 1$}{
    \For{$j \gets 0$ \KwTo $N - 1$ \textbf{step} $T \times G$}{
        \tcp{Load activation block}
        \For{$p \gets 0$ \KwTo $T \times G - 1$}{
            $\mathit{ A\_BLOCK}[p] \gets \text{A.read()}$\;
        }

        \tcp{Set up values of TL\_TABLE}
        \For{$t \gets 0$ \KwTo $T - 1$}{
            $\mathit{val}_{1\dots G} \gets \mathit{A\_BLOCK}[t \times G : (t + 1)\times G  -1]$\;
         \text{TL\_TABLE\_set\_up}$(\mathit{val}_{1\dots G})$\;
        }

        \tcp{Process hidden dimension}
        \For{$m \gets 0$ \KwTo K \textbf{step} $Q$}{
            \For{$n \gets 0$ \KwTo $Q - 1$}{
                $\mathit{idx\_vec} \gets B\left[\left\lfloor\frac{j}{T \times G}\right\rfloor\right][m + n]$\;
                \For{$t \gets 0$ \KwTo $N - 1$}{
                    $\mathit{TL\_TABLE\_idx} \gets \mathit{idx\_vec}[t]$\;
                    $\mathit{O\_BLOCK}[m + n] \gets \mathit{O\_BLOCK}[m + n] + \mathit{TL\_TABLE}[t][\mathit{TL\_TABLE\_idx}]$\;
                }
            }
        }
    }

    \tcp{Write output}
    \For{$p \gets 0$ \KwTo $K - 1$}{
        $\text{{\bf O}.write}(\mathit{C\_BLOCK}[p])$\;
        $\mathit{O\_BLOCK}[p] \gets 0$\;
    }
}

\BlankLine
\SetKwProg{Fn}{Function}{:}{}
\Fn{\text{Offline\_preprocess}($\bf W$)}{
    \Return Encode every $G$ value as an index in the matrix and pack every $T$ values as a index\_vector $idx\_vec$\;
}
\BlankLine
\SetKwProg{Fn}{Function}{:}{}
\Fn{\text{TL\_TABLE\_set\_up}($\mathit{val}_{1\dots G}$)}{
    \Return return all $3^G$ add and subtract combination\;
}
\end{algorithm}




