  \caption{Detect Loss Tolerance }
  \begin{algorithmic}[1]
  \Require $\overrightarrow{l}$, $\overrightarrow{\delta''}$, significance level
  \Ensure low decision impact areas
  \ForAll {$(l, \delta'')$ pairs }
    \State Set input parameters of Algorithm \ref{a:simulation1} by $l_{trt} = l_{ctrl} = l$ and $\beta_{int} = \delta''$  
    \State Run Algorithm \ref{a:simulation1} to generate $\frac{\delta}{se(\delta)}$ 
