\title{\LARGE \bf
Lightweight Multi-Frame Integration for 

Robust YOLO Object Detection in Videos
}


\author{Yitong Quan$^{1}$, Benjamin Kiefer$^{1}$, Martin Messmer$^{1}$ and Andreas Zell$^{1}$% <-this % stops a space
