\subsection{Competitive Reward Learning Model}\label{section2-1}

\begin{figure}[t]
    \centering
    % \captionsetup{font={footnotesize}}
    \includegraphics[width=0.45\textwidth]{competitive_model.pdf}
    \caption{The process of arm pulling and reward observations when $|\mathbb{N}_k(t)|$ players simultaneously choose arm $k$. In this case, only one player is randomly selected with probability $\frac{1}{|\mathbb{N}_k(t)|}$ to pull arm $k$ (e.g., player~$n$ with $\sigma_n(t)=0$ in Fig.~\ref{fig:competitive_reward}) and receive a reward of $r_k^n(t)=r_k(t)$, where $r_k(t)$ is given in \cref{r_k(t)}.
    As in \cite{boursier2019sic,wang2020optimal}, the remaining $|\mathbb{N}_k(t)|-1$ players observe collisions involving $|\mathbb{N}_k(t)|$ players there and receive zero rewards (with $\sigma_{n'}(t)=1$). In other words, these $|\mathbb{N}_k(t)|-1$ players have no effective reward observation of this arm.}
    \label{fig:competitive_reward}
\end{figure}

In each time slot $t\in\mathbb{T}$, all competitive players in $\mathbb{N}$ make their arm decisions independently without any communication. 
Let $\pi_n(t)\in\mathbb{K}$ denote the arm decision of player~$n$ at time $t$, where $n\in\mathbb{N}$. Define $\sigma_n(t)\in\{0,1\}$ as the collision indicator for player $n$:
\begin{align*}
    \sigma_n(t)=\begin{cases}
        1, &\text{if player $n$ experiences a collision at time $t$},\\
        0, &\text{otherwise}.
    \end{cases}
\end{align*} 

\textbf{Reward model.} Define $\mathbb{N}_k(t):=\{n|n\in\mathbb{N},\pi_n(t)=k\}$ as the set of player(s) choosing arm $k$ at time $t$, and the number of players in this set is:
\begin{align}
    |\mathbb{N}_k(t)|=\sum_{n=1}^N \mathds{1}\{\pi_n(t)=k\}.\label{|N_k|}
\end{align}
After deciding on arm $\pi_n(t)=k$, let $r_k^n(t)\in\{0,1\}$ denote the binary reward received by player~$n$. Given the number of competitive players $|\mathbb{N}_k(t)|$ choosing the same arm $k$, this actual reward $r_k^n(t)$ falls into two cases:

1) $|\mathbb{N}_k(t)|=1$ without collision at arm $k$: Player $n$ pulls arm $k$ and receives reward $r_k^n(t)=r_k(t)$. 

2) $|\mathbb{N}_k(t)|>1$ with collisions at arm $k$: As shown in Fig.~\ref{fig:competitive_reward}, only one player is randomly selected with probability $\frac{1}{|\mathbb{N}_k(t)|}$ to pull arm $k$ (e.g., player $n$ with $\sigma_n(t)=0$ in Fig.~\ref{fig:competitive_reward}) and receive $r_k^n(t)=r_k(t)$. As in \cite{boursier2019sic,wang2020optimal}, the remaining $|\mathbb{N}_k(t)|-1$ players observe collisions involving $|\mathbb{N}_k(t)|$ players there and receive zero rewards (with $\sigma_{n'}(t)=1$). In other words, these $|\mathbb{N}_k(t)|-1$ players have no reward observation of this arm.

In summary, the expected immediate reward $r_k^n(t)$ received by any player $n\in\mathbb{N}_k(t)$ choosing arm $\pi_n(t)=k$ is:
\begin{align}
    \mathbb{E}[r_k^n(t)]=(1-\sigma_n(t))\mu_k,\label{r_k^n}
\end{align}
Since $\mu_k$ is unknown to players, it necessitates them to explore this arm to learn it. 
% \begin{align}
%     r_k^n(t)=\begin{cases}
%         1,&\text{with probability } \frac{\mu_k}{|\mathbb{N}_k(t)|},\\
%         0,&\text{with probability } 1-\frac{\mu_k}{|\mathbb{N}_k(t)|}.
%     \end{cases}\label{r_k^n}
% \end{align}

Next, we introduce how each player $n$ updates its empirical mean reward of arm $k$, denoted by $\Tilde{\mu}_k^n(t)$, based on its past arm decisions and corresponding reward observations.
Here we assume that players can observe collisions on the arm they pull at the current time.

\textbf{Diverse empirical mean rewards.} Initially, each player $n$ has a private preference for each arm $k$ with $\Tilde{\mu}_k^n(0)=\theta_k^n$. Then for any $t\in\mathbb{T}$, the update of empirical mean reward $\Tilde{\mu}_k^n(t)$ depends on player $n$'s past observed rewards and the number of times it has pulled arm~$k$. 

We define $c_k^n(t)$ as the number of times player~$n$ has pulled arm $k$ before time $t$. Then, following Fig.~\ref{fig:competitive_reward}, the update of $c_k^n(t+1)$ contains two possibilities. 
\begin{itemize}
    \item If player~$n$ chooses another arm $\pi_n(t)\neq k$, $c_k^n(t+1)$ remains unchanged.
    \item If player~$n$ chooses arm $\pi_n(t)=k$ and it is selected to pull this arm during time $t$, $c_k^n(t+1)$ increases by $1$ and it observes $r_k(t)$ of arm $k$ in \cref{r_k^n}). If it is not selected, $c_k^n(t+1)$ remains the same as $c_k^n(t)$ as there is no effective reward observation. 
\end{itemize}
According to the above two cases, we summarize the dynamics of $c_k^n(t+1)$ below:
\begin{align}
    c_k^n(t+1)=\begin{cases}
        c_k^n(t)+1, &\text{if $\pi_n(t)=k$ and $\sigma_n(t)=0$},\\
        c_k^n(t), &\text{otherwise.}
    \end{cases}\label{c_k^n}
\end{align}

Given player $n$'s historical reward $r_n^k(t)$ in \cref{r_k^n}) and successful pulling times $c_k^n(t+1)$ in \cref{c_k^n}), it updates its empirical mean reward $\Tilde{\mu}_k^n(t+1)$ of arm $k$ to:
\begin{align}
    \Tilde{\mu}_k^n(t+1)=\frac{\sum_{\tau=1}^t r_k^n(\tau)\mathds{1}\{\pi_n(\tau)=k\}}{c_k^n(t+1)},\label{tilde_mu}
\end{align}
where $\mathds{1}\{\pi_n(\tau)=k\}=1$ if $\pi_n(\tau)=k$ and $\mathds{1}\{\pi_n(\tau)=k\}=0$ otherwise. Note that $\Tilde{\mu}_k^n(t)=\theta_k^n$ if $c_k^n(t)=0$ without effective exploration. 

For ease of exposition, we summarize empirical mean reward $\Tilde{\mu}_k^n(t)$ of player $n$ in \cref{tilde_mu} among all arms into vectors: 
\begin{align*}
    \Tilde{\bm{\mu}}^n(t)=\big\{\Tilde{\mu}_k^n(t)|k\in\mathbb{K}\big\}.
\end{align*}
Based on $\Tilde{\bm{\mu}}^n(t)$, non-myopic player $n$ follows the selfish policy to always choose the arm that maximizes its long-term expected reward. 
While the socially optimal policy aims to maximize the total long-term reward for all players. Then we formulate the optimization problems for the two policies in the next subsection.


\subsection{Problem Formulations}
\textbf{Selfish policy.} First, we formulate the optimization problem for non-myopic players following the selfish arm-decision policy for its own benefit. The selfish policy is defined below.
\begin{definition}[Selfish policy]\label{def:selfish_policy}
Under selfish policy, each non-myopic player $n$ aims to maximize its own long-term $\rho$-discounted reward, where $\rho\in(0,1)$ is the discount factor.
\end{definition}

\begin{algorithm}[t]
% \captionsetup{font={small}}
\caption{Decision-making under the selfish policy}
\small
\label{algo:selfish}
\begin{algorithmic}[1]
\STATE \textbf{Input:} $\mathbb{T},\mathbb{K}$;\
\STATE Initialize $\Tilde{\mu}^n_k(0)=\theta_k^n,c_k^n(0)=0$, $\forall k\in\mathbb{K}$;\
\FOR{$t\in\mathbb{T}$}
\STATE Solve \cref{pi_n_s(t)} to obtain $\pi^{(s)}_n(t)$;\
\IF{$\sigma_{\pi^{(s)}_n(t)}(t)=0$}
\STATE Observe ${r}_k(t)$ and update $c_k^n(t+1)=c_k^n(t)+1$ by \cref{c_k^n};\
\STATE Update $\Tilde{\mu}^n_k(t+1)$ by \cref{tilde_mu};\
\ENDIF
\ENDFOR
\end{algorithmic}
\end{algorithm}

According to \Cref{def:selfish_policy}, each player needs to estimate its long-term reward for decision making.
Let $\tilde{r}_k^n(t)$ denote player $n$'s expected immediate reward of choosing arm $k\in \mathbb{K}$ at time $t$, which is estimated by player $n$ based on \cref{r_k^n} and \cref{tilde_mu}:
\begin{align}\label{E[r_k^n]}
    \tilde{r}_k^n(t)=\textbf{Pr}(\sigma_n(t)=0|\tilde{\bm{\mu}}^n(t))\cdot \tilde{\mu}_k^n(t),
\end{align}
where $\textbf{Pr}(\sigma_n(t)=0|\tilde{\bm{\mu}}^n(t))=\frac{1}{|\mathbb{N}_k(t)|}$ according to Fig.~\ref{fig:competitive_reward} and \cref{|N_k|}.
To simplify notations, we use $\textbf{Pr}(\sigma_n(t)=0)$ to denote $\textbf{Pr}(\sigma_n(t)=0|\tilde{\bm{\mu}}^n(t))$ in the following.
Since player $n$ is unaware of the exact number of players $|\mathbb{N}_k(t)|$ selecting arm~$k$ in \cref{E[r_k^n]} before making its arm decision, it estimates the expected number of players choosing arm $k$ based on its own empirical mean reward $\Tilde{\mu}_k^n(t)$. Next, we establish the following lemma to better justify how players make decisions based on $\Tilde{\mu}_k^n(t)$.
\begin{lemma}\label{lemma:equal_expect}
For player $n$ with empirical mean reward set $\tilde{\bm{\mu}}^n(t)$ at $t$, we have $\mathbb{E}[\tilde{\bm{\mu}}^n(t+1)]=\tilde{\bm{\mu}}^n(t)$.
\end{lemma}
The proof of Lemma~\ref{lemma:equal_expect} is given in Appendix~A.
The result implies that player $n$'s expected empirical mean reward remains unchanged in the next time slot $t+1$.
Consequently, player $n$ can reasonably believe that other players symmetrically have the same expected empirical mean reward $\tilde{\bm{\mu}}^n(t)$ from $t=0$, as this belief is the most statistically likely to hold. To support this assumption, we further validate it through simulations in Section~\ref{section_simulation}.
Based on this belief, players behave strategically, and their decisions collectively form a Nash equilibrium at time $t$. Consequently, player $n$ estimates $|\mathbb{N}_k(t)|$ at the current time $t$ by solving the Nash equilibrium under $\tilde{\bm{\mu}}^n(t)$, using established methods such as value iteration.


Let $\pi^{(s)}_n(t)\in\mathbb{K}$ denote the arm decision of player $n\in \mathbb{N}$ under the selfish policy, where the subscript $(s)$ tells the selfish arm-decision policy in Definition~\ref{def:selfish_policy}.
For ease of exposition, we summarize arm decisions of all players into vector $\bm{\pi}^{(s)}(t)=\{\pi^{(s)}_1(t),\cdots, \pi_N^{(s)}(t)\}$. 
Define $V^{(s)}_n(\tilde{\bm{\mu}}^n(t))$ as the long-term expected total reward of player $n$ under the selfish policy from \Cref{def:selfish_policy}.
At any time $t\in\mathbb{T}$, we leverage the Markov decision process (MDP) to formulate:
\begin{align}\label{pi_n_s(t)}
    V^{(s)}_n(\tilde{\bm{\mu}}^n(t))=\max_{\pi_n^{(s)}(t)\in\mathbb{K}} &\Big\{\tilde{r}_{\pi_n^{(s)}(t)}^n(t)\\&+\rho\mathbb{E}\Big[V^{(s)}_n(\tilde{\bm{\mu}}^n(t+1))\Big|r_{\pi_n^{(s)}(t)}^n(t)\Big]\Big\}\notag,
\end{align}
where $\tilde{r}_{\pi_n^{(s)}(t)}^n(t)$ is defined in \cref{E[r_k^n]}, and the cost-to-go term $\mathbb{E}[V^{(s)}_n(\tilde{\bm{\mu}}^n(t+1))|r_{\pi_n^{(s)}(t)}^n(t)]$ includes the following cases, based on the actual observed reward $r_k^n(t)$ to update $\tilde{\bm{\mu}}^n(t+1)$:
\begin{itemize}
    \item $\sigma_{\pi_n^{(s)}(t)|\tilde{\bm{\mu}}^n(t)}(t)=1$ with transition probability $\mathbf{Pr}(\sigma_{\pi_n^{(s)}(t)}(t)=1)$ in \cref{E[r_k^n]}: No observation occurs, so the state $\tilde{\bm{\mu}}^n(t+1)$ remains unchanged.
    \item $\sigma_{\pi_n^{(s)}(t)}(t)=0$ and $r_{\pi_n^{(s)}(t)}^n(t)=1$ with transition probability $\mathbf{Pr}(\sigma_{\pi_n^{(s)}(t)}(t)=0)\tilde{\mu}_{\pi_n^{(s)}(t)}^n(t)$: $\tilde{\mu}_{\pi_n^{(s)}(t)}^n(t+1)$ of arm $k$ increases via the update rule in \cref{tilde_mu}, while $\tilde{\mu}^n_k(t+1)$ for all other arms remain unchanged.
    \item $\sigma_{\pi_n^{(s)}(t)}(t)=0$ and $r_k^n(t)=0$ with transition probability $\mathbf{Pr}(\sigma_{\pi_n^{(s)}(t)}(t)=0)(1-\tilde{\mu}_{\pi_n^{(s)}(t)}^n(t))$: $\tilde{\mu}_{\pi_n^{(s)}(t)}^n(t+1)$ of arm $k$ decreases via the update rule in \cref{tilde_mu}, while $\tilde{\mu}^n_k(t+1)$ of all other arms remain unchanged.
\end{itemize}

For ease of exposition, in this paper we focus on the pure strategies instead of mixed strategies of selfish players, where each player deterministically selects one arm at any given time (\!\!\cite{rosenski2016multi,boursier2020selfish}), as they are simpler to compute and implement. 
Our main results, including the PoA analysis in \Cref{thm:PoA_selfish} and mechanism design in \Cref{section5}, are also applicable to mixed strategies, in which players choose an arm probabilistically according to a predefined probability distribution. 
This is because pure and mixed strategies eventually converge to the same equilibrium outcome, resulting in the same number of players on each arm after convergence.

By observing \cref{pi_n_s(t)}, we find that selfish players only care about their own long-term rewards, overlooking the possible collisions to reduce rewards for other players on the same arm. Although the state space of $V_n^{(s)}(\tilde{\bm{\mu}}^n(t))$ increases exponentially with time gap $i$ in \cref{pi_n_s(t)}, we still derive the structural characterization of $\pi_n^{(s)}(t)$ later in \Cref{section4}. 
% As the state space of $\tilde{\bm{\mu}}^n(i)$ increases exponentially with time gap $i$, it becomes more involved to analyze $\pi_n^{(s)}(t)$ in \cref{pi_n_s(t)}, as compared to the literature of myopic players' one-shot games in \cite{kremer2014implementing,papanastasiou2018crowdsourcing,mansour2022bayesian,li2023congestion}. Yet we still aim to derive its structural characterization in \Cref{section4}.


