\begin{algorithm}[t]
% \captionsetup{font={small}}
\caption{Decision-making for the social planner under the socially optimal policy}
\small
\label{algo:social_optimum}
\begin{algorithmic}[1]
\STATE \textbf{Input:} $\mathbb{T},\mathbb{N},\mathbb{K}$;\
\STATE Initialize $\Tilde{\mu}_k(0)=\theta_k,c_k^n(0)=0$, $\forall k\in\mathbb{K}$ and $n\in\mathbb{N}$;\
\FOR{$t\in\mathbb{T}$}
\STATE Solve \cref{pi^*(t)} to obtain $\bm{\pi}^*(t)$;\
\STATE Let each player $n$ choose arm $\pi^*_n(t)$ and observe $r_k(t)$;\ 
\STATE Update $c_k^n(t+1)=c_k^n(t)+1$ for any $n\in\mathbb{N}$;\
\STATE Update $\Tilde{\mu}_k(t+1)$ by \cref{tilde_mu_opt};\
\ENDFOR
\end{algorithmic}
\end{algorithm}

\textbf{Socially optimal policy.} To compare selfish policy \cref{pi_n_s(t)} with the performance upper bound of strategy profile, we then formulate the optimization problem for the socially optimal policy.
In this scenario, all players listen to a centralized social planner, who follows the socially optimal policy for maximizing the long-term total reward for all players.
In addition, the social planner has access to all arm information observed by players, including $c_k^n(t)$ in \cref{c_k^n} and $r_k^n(t)$ in \cref{r_k^n} for all arms. 
Therefore, the social planner can estimate the global empirical mean reward $\tilde{\mu}_k(t+1)$ of arm $k$ as:
\begin{align}
    \tilde{\mu}_k(t+1)=\frac{\sum_{\tau=1}^t\sum_{n=1}^N\mathds{1}\{\pi_n(\tau)=k\}r^n_k(\tau)}{\sum_{n=1}^Nc_k^n(t+1)},\label{tilde_mu_opt}
\end{align}
Let $\tilde{\bm{\mu}}(t)$ denote the set of empirical mean rewards, containing $\tilde{\mu}_k(t+1)$ for each arm $k\in\mathbb{K}$.


Let $\bm{\pi}^*(t)$ denote the decision vector of all players under the socially optimal policy. Define $V^*(\Tilde{\bm{\mu}}(t))$ to be the long-term expected total reward of all players under the socially optimal policy. Then we similarly formulate the optimal optimization problem for the social planner as:
\begin{align}\label{pi^*(t)}
    V^*(\tilde{\bm{\mu}}(t))= \max_{\bm{\pi}^*(t)\in\mathbb{K}}& \Big\{\sum_{n=1}^N \tilde{r}^n_{\pi_n^*(t)}(t)\\&+\rho\mathbb{E}\Big[V^*(\tilde{\bm{\mu}}(t+1))\Big|r_{\pi_n^*(t)}^n(t),\forall n\Big]\Big\}.\notag
\end{align}
% \begin{align}
%     \bm{\pi}^*(t)=\arg \max_{\pi_n(t)\in\mathbb{K},\forall n} \sum_{i=t}^\infty\rho^{i-t} \sum_{n=1}^N\mathbb{E}\Big[r^n_{\pi_n(t)}(i)\Big|\tilde{\bm{\mu}}(t)\Big].\label{pi^*(t)}
% \end{align}
Unlike the distributed decision-making under the selfish policy \cref{pi_n_s(t)}, the socially optimal policy \cref{pi^*(t)} decides the policy set $\bm{\pi}^*(t)$ in a centralized way to maximize the sum of all players' long-term discounted rewards. It not only promptly explores different arms but also avoids collisions among players. 

Note that $\bm{\pi}^*(t)$ in \cref{pi^*(t)} is not unique, as any two players can exchange their arm decisions $\pi^*_n(t)$ without changing the total reward. 
With this useful property, we can flexibly recommend players to choose their most preferred arms from $\bm{\pi}^*(t)$ in our new CISP mechanism design, as discussed later in \Cref{section5}. 

\section{ANALYSIS OF POLICIES AND POA FOR CMAB GAMES}\label{section4}
In this section, we first provide threshold-based structures and convergence analysis for both selfish policy and socially optimal policy to understand and compare. Subsequently, we demonstrate that, as compared to the socially optimal policy in \cref{pi^*(t)}, players' selfish policy in \cref{pi_n_s(t)} results in an infinite $\text{PoA}$. 

