\subsection{Analysis of Selfish Policy}
% First, for player $n\in\mathbb{N}$ with arm decision $\pi_n^{(s)}(t-1)=k$ in the previous time slot $t-1$, let $\mathcal{T}^n_{j,k}(t)$ denote its exploration threshold of arm $j$ at time $t$. Then if and only if player $n$'s expected reward of choosing arm $j$ satisfies $\mathbb{E}[r_j^n(t)|\pi_n^{(s)}(t)=j]>\mathcal{T}^n_{j,k}(t)$, it will switch from arm $k$ to arm $j$ at time $t$.
% \begin{align}
%     \mathbb{E}[r_j^n(t)|\pi_n^{(s)}(t)=j]>\mathcal{T}^n_{j,k}(t).\label{def:selfish_threshold}
% \end{align}

In the following proposition, we derive the threshold-based structure that determines when each player switches arm decisions under the selfish policy \cref{pi_n_s(t)}.

\begin{proposition}\label{prop:selfish_threshold}
Under selfish policy \cref{pi_n_s(t)}, consider player $n\in\mathbb{N}_k(t-1)$, who chose arm $\pi_n^{(s)}(t-1)=k$ in the previous time slot $t-1$.
At time $t$, there exists a unique exploration threshold that determines whether player $n$ should switch to another arm $j\neq k$. This threshold depends on the following case-by-case scenarios: 
\begin{align}
    \mathcal{T}_{j,k}^n(t)\in \begin{cases}
        \Big[\tilde{r}_k^n(t)-\Delta \mu_{j,k}(t), \tilde{r}_k^n(t) \Big], \text{ if } c_j^n(t)<c_k^n(t),\\
        \Big[\tilde{r}_k^n(t), \tilde{r}_k^n(t)-\Delta \mu_{j,k}(t) \Big], \text{ if } c_j^n(t)\geq c_k^n(t),
    \end{cases}\label{threshold_T}
\end{align}
where $c_k^n(t)$ and $c_j^n(t)$ are the up-to-now exploration counts for arms $k$ and $j$, respectively, as given in \cref{c_k^n}, and $\tilde{r}_k^n(t)$ is the expected reward given in \cref{E[r_k^n]}, and
\begin{align}
\textstyle
    \Delta \mu_{j,k}(t)=\frac{(c_k^n(t)-c_j^n(t))(1-\tilde{r}_k^n(t))}{(\mathbb{E}\big[|\mathbb{N}_j(t-1)|\big|\tilde{\bm{\mu}}^n(t-1)\big]+1)(c_k^n(t)c_j^n(t)+c_j^n(t))}.\label{delta_mu_selfish}
\end{align}
Player $n$ will switch to arm $j$ if the expected reward of arm $j$ satisfies $\tilde{r}_j^n(t)>\mathcal{T}^n_{j,k}(t)$.
In this case, choosing arm $j$ strictly dominates staying with arm $k$ under selfish policy \cref{pi_n_s(t)}. 
The threshold $\mathcal{T}_{j,k}^n(t)$ in \cref{threshold_T} increases with $c_j^n(t)$. If $c_j^n(t)<c_k^n(t)$, $\mathcal{T}_{j,k}^n(t)$ decreases with discount factor $\rho$. Otherwise, $\mathcal{T}_{j,k}^n(t)$ increases with $\rho$.
\end{proposition}

The proof of \Cref{prop:selfish_threshold} is given in Appendix~B. \Cref{prop:selfish_threshold} provides a structural characterization of how non-myopic players behave dynamically under selfish policy \cref{pi_n_s(t)} in CMAB games. Note that such explicit policy analysis is not provided in the literature \cite{boursier2019sic,branzei2021multiplayer,sentenac2021decentralized,huang2023near,xu2023competing}.

If discount factor $\rho=0$, players become myopic and simply compare the one-shot expected rewards of arms $k$ and $j$ to make their current arm decisions in \cref{threshold_T}. In this case, we have $\mathcal{T}_{j,k}^n(t)=\tilde{r}_k^n(t)$.
While if $\rho>0$, players are non-myopic and focus on their own long-term rewards.
According to \cref{threshold_T}, there are two cases for player $n$ to decide its exploration threshold $\mathcal{T}^n_{j,k}(t)$, depending on its number of explorations of arm $k$ and arm $j$:
\begin{itemize}
    \item If player~$n$ has explored arm $k$ more than arm~$j$ (i.e., $c_j^n(t)<c_k^n(t)$), it is more inclined to switch from arm~$k$ to arm $j$, even if arm $j$ offers a lower immediate expected reward compared to the reward of sticking with arm $k$, i.e., $\tilde{r}_j^n(t)<\tilde{r}_k^n(t)$. 
    This preference arises because arm $j$, with less exploration than arm $k$, offers a positive exploration benefit for player $n$'s long-term reward, which is at most $\Delta \mu_{j,k}(t)$ in \cref{delta_mu_selfish}.
    \item If player~$n$ has explored arm $k$ less than arm~$j$ (i.e., $c_j^n(t)>c_k^n(t)$), it becomes less inclined to explore arm $j$ due to the negative exploration benefit ($\Delta \mu_{j,k}(t)<0$) compared to sticking with arm $k$ for its long-term reward. 
\end{itemize}

% In \cref{delta_mu_selfish}, if there is no exploration of arm $j$ for player $n$, i.e., $c_j^n(t)=0$, the maximum exploration benefit $\Delta \mu_{j,k}$ in \cref{delta_mu_selfish} approaches infinity, indicating 
The maximum exploration benefit $\Delta \mu_{j,k}(t)$ in \cref{delta_mu_selfish} is achieved at $\rho=1$. Note that if $c_j^n(t)=0$ and $c_k^n(t)\neq 0$, the maximum exploration benefit $\Delta \mu_{j,k}(t)$ is arbitrarily large, implying that player $n$ will switch to arm $j$ without any exploration after exploring arm $n$ under $\rho=1$. 
As the exploration counts $c_k^n(t)$ and $c_j^n(t)$ for arms $k$ and $j$ increase, the maximum exploration benefit $\Delta \mu_{j,k}(t)$ in \cref{delta_mu_selfish} approaches zero, leading to $\mathcal{T}_{j,k}^n(t)=\tilde{r}_k^n(t)$. This indicates that player $n$ becomes myopic, focusing on maximizing its one-shot reward. 

% Based on the above analysis, we derive the following corollary for \Cref{prop:selfish_threshold}.

% \begin{corollary}
% The actual exploration threshold $\mathcal{T}_{j,k}^n(t)$ in \cref{threshold_T} under the selfish policy increases with exploration number $c_j^n(t)$ of arm $j$. Additionally, if $c_j^n(t)<c_k^n(t)$, $\mathcal{T}_{j,k}^n(t)$ decreases with the discount factor $\rho$. Otherwise, $\mathcal{T}_{j,k}^n(t)$ increases with $\rho$.
% \end{corollary}

As the exploration counts $c_j^n(t)$ of all arms increases, the exploration benefit in \cref{delta_mu_selfish} decreases to zero, and players converge to the Nash equilibrium (NE), denoted by $\Bar{\bm{\pi}}^{(s)}$. In $\Bar{\bm{\pi}}^{(s)}$, no player can unilaterally switch arms to improve its own reward. 
Let $\Bar{\bm{\pi}}^{(s)}_{-n}$ denote the arm decisions of the other $N-1$ players except player $n$.
Then we generally define the $\epsilon$-Nash equilibrium ($\epsilon$-NE, \cite{roughgarden2010algorithmic}) for our CMAB games.
\begin{definition}[$\epsilon$-Nash Equilibrium ($\epsilon$-NE)]\label{def:nash_equilibrium}
In CMAB games, an arm decision $\Bar{\pi}_n^{(s)}=k\in \mathbb{K}$ is an NE for player $n$ if for all $k'\in\mathbb{K}$ with $k'\neq k$,
\begin{align}\label{def_NE}
    \mathbb{E}\big[r_k^n(t)\big|\bar{\bm{\pi}}^{(s)}\big]\geq \mathbb{E}\big[r_{k'}^n(t)\big|{\pi}_n^{(s)}=k',\bar{\bm{\pi}}_{-n}^{(s)}\big]-\epsilon,
\end{align}
where $\epsilon=o(1)$.
\end{definition}
Note that when $\epsilon=0$, $\Bar{\pi}_n^{(s)}$ becomes the NE in \cref{def_NE}.
Based on \Cref{def:nash_equilibrium}, we define the convergence of selfish players in CMAB games.
\begin{definition}[Convergence]\label{def:convergence}
In CMAB games, the convergence refers to all players' arm decisions converging to $\epsilon$-NE $\Bar{\pi}_n^{(s)}$.
\end{definition}

Let $T^{(s)}$ denote the convergence time for all players to converge to the $\epsilon$-NE. Recall that $\eta$ is the minimal gap between the mean rewards of any two arms, i.e., $|\mu_i-\mu_j|>\eta$ for any $i,j\in\mathbb{K}$. 
We then analyze the order of $T^{(s)}$ in the following proposition.

\begin{proposition}\label{lemma:exploration_period_selfish}
Under the selfish policy in \cref{pi_n_s(t)}, for $\eta,\delta>0$, with probability at least $1-\delta$, all players will converge to equilibrium $\Bar{\bm{\pi}}^{(s)}$ in $T^{(s)}= \Omega\big(\frac{K}{\eta^2}\ln({\frac{KN}{\delta}})\big)$ time slots.
% \begin{align*}
%     \max_{\substack{\bm{\mu},\bm{\theta}^n,\bm{U}\\ \rho, N,K}} T^{(s)}= \Omega\Big(\frac{K}{\eta^2}\ln({\frac{KN}{\delta}})\Big).
% \end{align*} 
\end{proposition}
The proof of \Cref{lemma:exploration_period_selfish} is given in Appendix~C. Under the selfish policy in \cref{pi_n_s(t)}, each player $n\in\mathbb{N}$ subsequently explores arms under \cref{threshold_T} until converging to $\Bar{\pi}_n^{(s)}$. The likelihood of collisions per time slot requires additional time slots for players to choose each arm. In the next subsection, we will compare $T^{(s)}$ with $T^*$ under the social optimum to show the exploration loss of the selfish policy.
% However, the effective explorations for each player $n$, i.e., $c_k^n(t+1)$ in \cref{c_k^n}), are reduced due to potential collisions with competitive others. 
% Consequently, it takes all players at most $\mathcal{O}(NK)$ time slots to complete their explorations.

\subsection{Analysis of Socially Optimal Policy}

Before analyzing the exploration threshold for the socially optimal policy, we first demonstrate that the socially optimal policy always avoids collisions among players in the next lemma.
\begin{lemma}\label{lemma:optimal_nocollision}
Under the socially optimal policy in \cref{pi^*(t)}, at any time $t\in\mathbb{T}$, the number of players choosing each arm $k\in\mathbb{K}$ satisfies $|\mathbb{N}_k(t)|\leq 1$.
\end{lemma}
The proof of \Cref{lemma:optimal_nocollision} is given in Appendix~D. 
The socially optimal policy ensures $|\mathbb{N}_k(t)|\leq 1$ to avoid collisions among players, thereby maximizing the total rewards for all players in \cref{pi^*(t)}.

Let $\mathcal{T}^*_{j,k}(t)$ denote the exploration threshold of arm $j$ under socially optimal policy \cref{pi^*(t)}. Unlike $\mathcal{T}^n_{j,k}(t)$ in \cref{threshold_T}, which explores arms in a distributed way, the socially optimal policy decides arms in a centralized way. 
Based on \Cref{lemma:optimal_nocollision}, if $\tilde{\mu}_j(t)<\mathcal{T}^*_{j,k}(t)$, we similarly characterize the solution of the socially optimal policy \cref{pi^*(t)} in the following proposition.
\begin{proposition}\label{prop:optimal_threshold}
Under socially optimal policy \cref{pi^*(t)}, there exists a common exploration threshold in the following case-by-case ranges for player $n$ to consider arm $j\neq k$ with $|\mathbb{N}_j(t-1)|=0$ at time $t$:  
\begin{align}
    \mathcal{T}^*_{j,k}(t)\in \begin{cases}
        \big[\tilde{\mu}_k(t)-\Delta \mu^*_{j,k}(t), \tilde{\mu}_k(t)\big], \text{ if } c_j(t)<c_k(t),\\
        \big[\tilde{\mu}_k(t), \tilde{\mu}_k(t)-\Delta \mu_{j,k}^*(t) \big], \text{ if } c_j(t)\geq c_k(t),
    \end{cases}\label{threshold_T*}
\end{align}
depending on up-to-now exploration numbers $c_k^n(t)$ and $c_j^n(t)$ between the two arms $k$ and $j$, where 
\begin{align}
    \Delta \mu_{j,k}^*(t)=\frac{(c_k(t)-c_j(t))(1-\tilde{\mu}_k(t))}{c_k(t)c_j(t)+c_j(t)}. \label{delta_mu_optimal}
\end{align}
That is, if the empirical mean reward of arm $j$ satisfies $\tilde{\mu}_j(t)<\mathcal{T}_{j,k}(t)$, then $\pi_n^*(t)=k$ strictly dominates $\pi_n^*(t)=j$ for player $n$. 
The exploration threshold $\mathcal{T}^*_{j,k}(t)$ in \cref{threshold_T*} increases with $c_j(t)$. Additionally, if $c_j(t)<c_k(t)$, $\mathcal{T}^*_{j,k}(t)$ decreases with discount factor $\rho$. Otherwise, $\mathcal{T}^*_{j,k}(t)$ increases with $\rho$.
\end{proposition}
The proof of \Cref{prop:optimal_threshold} is given in Appendix~E.
The optimal exploration threshold $\mathcal{T}^*_{j,k}(t)$ in \cref{threshold_T*} is similarly derived as $\mathcal{T}_{j,k}^n(t)$, by letting $|\mathbb{N}_k(t-1)|=1$ and $\mathbb{E}[|\mathbb{N}_j(t-1)|\big|\tilde{\bm{\mu}}^n(t-1)]=0$ in \cref{threshold_T} to avoid collision, based on \Cref{lemma:optimal_nocollision}.
According to \cref{threshold_T*}, to avoid collisions among players, the socially optimal policy only compares arm $k$ to another arm~$j$ without player exploration at last time $t-1$, i.e., $|\mathbb{N}_j(t-1)|=0$. This is different from the selfish threshold $\mathcal{T}_{j,k}^n(t)$ in \cref{threshold_T} that compares to any arm $j\neq k$. 


According to \cref{threshold_T*}, as $c_k(t)$ and $c_j(t)$ increase to make the maximum exploration benefit $\Delta \mu^*_{j,k}(t)$ in \cref{delta_mu_selfish} to approach zero, the exploration threshold $\mathcal{T}^*_{j,k}(t)$ becomes myopic $\tilde{\mu}_k(t)$. 
Meanwhile, the empirical mean reward $\tilde{\mu}_k(t)$ converges for each arm~$k$.

Let $\bar{\bm{\pi}}^*$ denote the steady decision set after convergence under the socially optimal policy \cref{pi^*(t)}. 
Based on \Cref{lemma:optimal_nocollision} and \Cref{prop:optimal_threshold}, in the steady decision $\Bar{\bm{\pi}}^*$, the socially optimal policy always chooses the top $N$ arms to maximize the long-term total reward for $N$ players. 
In the next proposition, we similarly analyze the convergence time under the socially optimal policy \cref{pi^*(t)}, denoted by $T^*$.
\begin{proposition}\label{lemma:exploration_stage_optimal}
Under socially optimal policy in \cref{pi^*(t)}, for $\eta,\delta>0$, with probability at least $1-\delta$, all players will converge to the optimal steady decision $\Bar{\bm{\pi}}^*$ in $T^*= \mathcal{O}\big(\frac{K}{N\eta^2}\ln{(\frac{K}{\delta})}\big)$ time slots.
% \begin{align}
%     \max_{\substack{\bm{\mu},\bm{\theta}^n,\bm{U}\\ \rho, N,K}} T^*= \mathcal{O}\Big(\frac{K}{N\eta^2}\ln{(\frac{K}{\delta})}\Big).\label{optimal_convergence}
% \end{align}
\end{proposition}
The proof of \Cref{lemma:exploration_stage_optimal} is given in Appendix~F. Different from selfish policy's subsequent explorations with potential collisions in \Cref{lemma:exploration_period_selfish}, socially optimal policy \cref{pi^*(t)} recommends $N$ players simultaneously explore $N$ different arms to avoid collisions. Therefore, the convergence time is greatly reduced to $\mathcal{O}(\frac{K}{N\eta^2}\ln{(\frac{K}{\delta})})$, which is still an upper bound. 
Its comparison with \Cref{lemma:exploration_period_selfish} also tells the importance of designing incentive mechanisms among selfish players to accelerate the convergence process. 

