\subsection{Proof of Lemma 1}
For any player $n$, we suppose it chooses arm $j$ at time $t$. Then its empirical mean reward $\tilde{\mu}^n_i(t+1)$ equals $\tilde{\mu}^n_i(t)$ for any $i\neq j$, as there is no observations on arm $i$. If this user is not selected to pull arm $j$, we obtain $\mathbb{E}[\tilde{\mu}^n_j(t+1)]=\tilde{\mu}^n_j(t)$ for arm $j$.

If it is selected to pull arm $j$, based on eq. (5), we calculate its expected empirical mean reward below:
\begin{align*}
    &\mathbb{E}[\tilde{\mu}^n_j(t+1)]\\=&\mathbb{P}(r_j^n(t)=1)\cdot \frac{\sum_{\tau=1}^t r_j^n(\tau)\mathds{1}\{\pi_n(\tau)=j\}+1}{c_j^n(t)+1}\\&+\mathbb{P}(r_j^n(t)=0)\cdot \frac{\sum_{\tau=1}^t r_k^n(\tau)\mathds{1}\{\pi_n(\tau)=j\}}{c_j^n(t)+1}\\
    =&\tilde{\mu}^n_j(t)\cdot \frac{\sum_{\tau=1}^t r_j^n(\tau)\mathds{1}\{\pi_n(\tau)=j\}+1}{c_j^n(t)+1}\\&+(1-\tilde{\mu}^n_j(t))\cdot \frac{\sum_{\tau=1}^t r_k^n(\tau)\mathds{1}\{\pi_n(\tau)=j\}}{c_j^n(t)+1}\\
    =&\frac{\tilde{\mu}_j^n(t)\cdot(\tilde{\mu}_j^n(t)\cdot c_j^n(t)+1)+(1-\tilde{\mu}_j^n(t))\cdot \tilde{\mu}_j^n(t)\cdot c_j^n(t)}{c_j^n(t)+1}\\
    =&\tilde{\mu}_j^n(t),
\end{align*}
where the second equality is because of $\mathbb{P}(r_j^n(t)=1)=\tilde{\mu}^n_j(t)$ and the third equality is because of $\sum_{\tau=1}^t r_j^n(\tau)\mathds{1}\{\pi_n(\tau)=j\}=\tilde{\mu}_j^n(t)\cdot c_j^n(t)$ derived by eq. (5). Consequently, we obtain $\mathbb{E}[\tilde{\bm{\mu}}^n(t+1)]=\tilde{\bm{\mu}}^n(t)$.

\subsection{Proof of Proposition 1}\label{Appendix_E}
We first prove that when $\rho=0$, player $n$ will switch from arm $k$ to arm $j$ if $\tilde{r}_j^n(t)>\tilde{r}_k^n(t)$, where arm $k$ was the best arm for player $n$ and arm $j$ was the second-best arm for player $n$ at time $t-1$. Then we prove that when $\rho=1$, player $n$ will switch from arm $k$ to arm $j$ if $\tilde{r}_j^n(t)>\tilde{r}_k^n(t)-\Delta \mu_{j,k}$, where $\Delta \mu_{j,k}$ is defined in (10).
Finally, we establish the monotonicity of this exploration threshold $\mathcal{T}^n_{j,k}(t)$, which dictates the minimum immediate reward of arm $j$ for player $n$ to switch to, with respect to $c_j^n(t)$ and $\rho$.


According to the optimization problem (7) under the selfish policy, non-myopic players focus more on long-term rewards as discount factor $\rho\in(0,1)$ increases.
If $\rho=0$, selfish players under (7) become myopic and will switch from arm $k$ to another arm $j$ with a higher immediate expected reward $\tilde{r}_j^n(t)>\tilde{r}_k^n(t)$, regardless of the relationship between $c_j^n(t)$ and $c_k^n(t)$. In this case, the exploration threshold from arm $k$ to arm $j$ satisfies $\mathcal{T}_{j,k}^n(t)=\tilde{r}_k^n(t)$.
% based on (6). 
% Therefore, if $\rho=0$, the exploration threshold for player $n$ to switch from arm $k$ to arm $j$ is $\mathcal{T}_{j,k}^n(t)=\tilde{r}_k^n(t)$.

If $\rho>0$, player $n$ under selfish policy (7) will explore arm $j$ if it leads to a higher long-term expected reward than arm $k$ from the current time $t$. 
Let $U_t(k,\bm{\pi}^{(s)}_{-n}(t))$ and $U_t(j,\bm{\pi}^{(s)}_{-n}(t))$ denote the long-term expected rewards since time $t$ for player $n$ under current arm decisions $\pi_n(t)=j$ and $\pi_n(t)=k$, respectively.
According to selfish policy (7), player $n$ decides its decision $k$ or $j$ by comparing the two long-term expected rewards below:
\begin{align}
    &U_t\big(k,\bm{\pi}^{(s)}_{-n}(t)\big)-U_t\big(j,\bm{\pi}^{(s)}_{-n}(t)\big)\notag\\=&\tilde{r}_j^n(t)-\tilde{r}_k^n(t)\notag\\&+\rho U_{t+1}\big(\pi_n(t+1|j),\bm{\pi}^{(s)}_{-n}(t+1)\big)\notag\\&-\rho U_{t+1}\big(\pi_n(t+1|k),\bm{\pi}^{(s)}_{-n}(t+1)\big)\notag\\
    =& \frac{\Tilde{\mu}_j^n(t)}{\mathbb{E}\big[|\mathbb{N}_j(t-1)|\big|\tilde{\bm{\mu}}^n(t-1)\big]+1}-\frac{\Tilde{\mu}_k^n(t)}{\mathbb{E}\big[|\mathbb{N}_k(t-1)|\big|\tilde{\bm{\mu}}^n(t-1)\big]}\notag\\&+\rho U_{t+1}\big(\pi_n(t+1|j),\bm{\pi}^{(s)}_{-n}(t+1)\big)\notag\\&-\rho U_{t+1}\big(\pi_n(t+1|k),\bm{\pi}^{(s)}_{-n}(t+1)\big),\tag{21}\label{24}
\end{align}
where $\mathbb{E}\big[|\mathbb{N}_k(t-1)|\big|\tilde{\bm{\mu}}^n(t-1)\big]$ and $\mathbb{E}\big[|\mathbb{N}_j(t-1)|\big|\tilde{\bm{\mu}}^n(t-1)\big]$ are the expected numbers of players choosing arms $k$ and $j$ under $\tilde{\bm{\mu}}^n(t-1)$ at the last time $t-1$, respectively. 
% Here the second equality in (\ref{24}) is derived because player $n$'s empirical mean reward $\Tilde{\bm{\mu}}^n(t)$ does not change

Based on (\ref{24}), the sufficient condition for player $n$ to switch from arm $k$ to arm $j$ is $U_t\big(k,\bm{\pi}^{(s)}_{-n}(t)\big)-U_t\big(j,\bm{\pi}^{(s)}_{-n}(t)\big)<0$, which is equivalent with solving
\begin{align}
    &\rho U_{t+1}\big(\pi_n(t+1|j),\bm{\pi}^{(s)}_{-n}(t+1)\big)\notag\\&-\rho U_{t+1}\big(\pi_n(t+1|k),\bm{\pi}^{(s)}_{-n}(t+1)\big)\tag{22}\label{25}\\>&\frac{\Tilde{\mu}_j^n(t)}{\mathbb{E}\big[|\mathbb{N}_j(t-1)|\big|\tilde{\bm{\mu}}^n(t-1)\big]+1}-\frac{\Tilde{\mu}_k^n(t)}{\mathbb{E}\big[|\mathbb{N}_k(t-1)|\big|\tilde{\bm{\mu}}^n(t-1)\big]}.\notag
\end{align}
To solve the above inequality, we need to expand the two cost-to-go functions $U_{t+1}\big(\pi_n(t+1|j),\bm{\pi}^{(s)}_{-n}(t+1)\big)$ and $U_{t+1}\big(\pi_n(t+1|k),\bm{\pi}^{(s)}_{-n}(t+1)\big)$.
For future arm decisions after choosing arm $\pi_n(i)=j$, player $n$ will switch back to the previously best arm $k$ as long as it pulls arm $j$ and observes $r_j(i)=0$ there. While if it observes $r_j(i)=1$, it will stick with the best arm $j$ at time $i+1$. Therefore, we further expand (\ref{25}) under $\rho=1$ into:
\begin{align}
    & U_{t+1}\big(\pi_n(t+1|j),\bm{\pi}^{(s)}_{-n}(t+1)\big)-U_{t+1}\big(\pi_n(t+1|k),\bm{\pi}^{(s)}_{-n}(t+1)\big)\notag\\ \geq &\Tilde{\mu}_j^n(t) \cdot \frac{\Tilde{\mu}_j^n(t+1|r_j(t)=1)}{\mathbb{E}\big[|\mathbb{N}_j(t-1)|\big|\tilde{\bm{\mu}}^n(t-1)\big]+1}+(1-\Tilde{\mu}_j^n(t))\tilde{r}_k^n(t+1)\notag\\ &-\tilde{r}_k^n(t+1)+\Tilde{\mu}_j^n(t) \cdot\sum_{i=t+2}^{\infty}\big(\tilde{r}_j^n(i)-\tilde{r}_k^n(i)\big)\notag\\
    \geq &\Tilde{\mu}_j^n(t) \frac{1}{\mathbb{E}\big[|\mathbb{N}_j(t-1)|\big|\tilde{\bm{\mu}}^n(t-1)\big]+1}\cdot \frac{\Tilde{\mu}_j^n(t)c_j^n(t)+1}{c_j^n(t)+1}\notag\\&-\Tilde{\mu}_j^n(t)\tilde{r}_k^n(t+1)\tag{23}\label{26}+\Tilde{\mu}_j^n(t) \cdot\sum_{i=t+2}^{\infty}\tilde{r}_j^n(i)-\tilde{r}_k^n(i),
\end{align}
where the second inequality is because of $\Tilde{\mu}_j^n(t+1|r_j(t)=1)=\frac{\Tilde{\mu}_j^n(t)c_j^n(t)+1}{c_j^n(t)+1}$ by (5) and player $n$ switches back to arm $k$ since $t+1$ after observing $r_j(t)=0$ with probability $1-\tilde{\mu}_j^n(t)$.

By combining the above two inequalities in (\ref{25}) and (\ref{26}), we obtain 
\begin{align}
    &\frac{\tilde{\mu}^n_j(t)}{\mathbb{E}\big[|\mathbb{N}_j(t-1)|\big|\tilde{\bm{\mu}}^n(t-1)\big]+1}\tag{24}\label{26-a}\\>&\frac{\tilde{\mu}^n_k(t)}{|\mathbb{N}_k(t-1)|}-\frac{(c_k^n(t)-c_j^n(t))(1-\frac{\tilde{\mu}^n_k(t)}{|\mathbb{N}_k(t-1)|})}{(\mathbb{E}\big[|\mathbb{N}_j(t-1)|\big|\tilde{\bm{\mu}}^n(t-1)\big]+1)(c_k^n(t)c_j^n(t)+c_j^n(t))}.\notag
\end{align}
Letting $\Delta \mu_{j,k}=\frac{|c_k^n(t)-c_j^n(t)|(1-\frac{\tilde{\mu}^n_k(t)}{|\mathbb{N}_k(t-1)|})}{(\mathbb{E}\big[|\mathbb{N}_j(t-1)|\big|\tilde{\bm{\mu}}^n(t-1)\big]+1)(c_k^n(t)c_j^n(t)+c_j^n(t))}$. Then if $c_j^n(t)<c_k^n(t)$, (\ref{26-a}) is the lower bound of threshold $\mathcal{T}_{j,k}^n(t)$ in (9). While if $c_j^n(t)\geq c_k^n(t)$, (\ref{26-a}) becomes the upper bound of $\mathcal{T}_{j,k}^n(t)$ for $c_j^n(t)\geq c_k^n(t)$ in (9). 
Therefore, we derive the exploration threshold $\mathcal{T}_{j,k}^n(t)$ for player $n$ to switch from arm $k$ to arm $j$ when $\rho=1$.
% This completes the proof of the case-by-case ranges of $\mathcal{T}_{j,k}^n(t)$ for $c_j^n(t)\geq c_k^n(t)$ in (9).


Next, we prove the monotonicity of $\mathcal{T}_{j,k}^n(t)$ with respect to the exploration counts $c_j^n(t)$ and the discount factor $\rho$. By proving $\mathcal{T}_{j,k}^n(t)$ increases with $\rho$ if $c_j^n(t)<c_k^n(t)$ while decreases with $\rho$ if $c_j^n(t)\geq c_k^n(t)$, we can complete the proof of case-by-case ranges of exploration threshold $\mathcal{T}_{j,k}^n(t)$ in (9) of Proposition 1.

In (9), by solving the first-order derivative of $\Delta \mu$ with respect to $c_j^n(t)$, it is straightforward to find that $\Delta \mu$ decreases with $c_j^n(t)$ if $c_j^n(t)<c_k^n(t)$ while increasing with $c_j^n(t)$ if $c_j^n(t)\geq c_k^n(t)$. Thus, $\mathcal{T}_{j,k}^n(t)$ always increases with $c_j^n(t)$, based on the expression in (9). 

To prove $\mathcal{T}_{j,k}^n(t)$ increases/decreases with $\rho$, we only need to show $U_{t+1}\big(\pi_n(t+1|j),\bm{\pi}^{(s)}_{-n}(t+1)\big)-U_{t+1}\big(\pi_n(t+1|k),\bm{\pi}^{(s)}_{-n}(t+1)\big)$ increases/decreases with $\rho$ in (\ref{24}). 

If $c_j^n(t)<c_k^n(t)$, then threshold $\mathcal{T}_{j,k}^n(t)<\frac{\Tilde{\mu}_k^n(t)}{|\mathbb{N}_k(t-1)|}$, as players are always willing to explore arm $j$ with a higher immediate expected reward $\frac{\Tilde{\mu}_j^n(t)}{\mathbb{E}\big[|\mathbb{N}_j(t-1)|\big|\tilde{\bm{\mu}}^n(t-1)\big]+1}$ and less exploration counts $c_j^n(t)$. In this case, 
\begin{align*}
    &\rho U_{t+1}\big(\pi_n(t+1|j),\bm{\pi}^{(s)}_{-n}(t+1)\big)\\&-\rho U_{t+1}\big(\pi_n(t+1|k),\bm{\pi}^{(s)}_{-n}(t+1)\big)>0
\end{align*}
in both (\ref{24}) and (\ref{25}). 
Therefore, a larger discount factor $\rho$ in (\ref{24}) leads to an increased difference between the two cost-to-go, and thus the threshold $\mathcal{T}_{j,k}^n(t)$ also increases. 
While if $c_j^n(t)\geq c_k^n(t)$, we can similarly show
\begin{align*}
    &\rho U_{t+1}\big(\pi_n(t+1|j),\bm{\pi}^{(s)}_{-n}(t+1)\big)\\&-\rho U_{t+1}\big(\pi_n(t+1|k),\bm{\pi}^{(s)}_{-n}(t+1)\big)<0.
\end{align*}
which decreases with $\rho$, indicating that the threshold $\mathcal{T}_{j,k}^n(t)$ decreases with $\rho$.

In summary, If $c_j^n(t)<c_k^n(t)$, this threshold $\mathcal{T}_{j,k}^n(t)$ decreases with discount factor $\rho$. Otherwise, $\mathcal{T}_{j,k}^n(t)$ increases with $\rho$. Based on our derived upper and lower bounds of $\mathcal{T}_{j,k}^n(t)$ under $\rho=1$ and $\rho=0$,
we finally completes the proof of Proposition~1.


\subsection{Proof of Proposition~2}\label{Appendix_A}
We first prove that if any player $n$ has at least $\frac{2}{\eta^2}\ln(\frac{2KN}{\delta})$ observations of each arm, all players will have an $\eta$-correct ranking of all arms with probability at least $1-\delta$. Then we derive the length of exploration $T^{(s)}=\Omega(\frac{K}{\eta^2}\ln(\frac{KN}{\delta}))$ to guarantee the $\frac{2}{\eta^2}\ln(\frac{2KN}{\delta})$ observations for all players. 

Let $O$ denote the required number of observations for each player at each arm. Define $I_n=1$ to be the event that player $n$ does not have an $\eta$-correct ranking. We need to obtain
\begin{align*}
    \mathbb{P}(I_n=1|\text{$\geq O$ observations of each arm})<\frac{\delta}{N}.
\end{align*}
Then we calculate
\begin{align*}
    &\mathbb{P}(I_n=1|\text{$\geq O$ observations of each arm})\\
    \leq & \mathbb{P}\Big(\exists k \text{ s.t. }|\Tilde{\mu}^n_k(t)-\mu_k|>\frac{\eta}{2}\Big|\text{$\geq O$ observations of each arm}\Big)\\
    \leq & \sum_{k=1}^K \mathbb{P}\Big(|\Tilde{\mu}^n_k(t)-\mu_k|>\frac{\eta}{2}\Big|\text{$\geq O$ observations of each arm}\Big)\\
    =& \sum_{k=1}^K\sum_{c=O}^{\infty} \mathbb{P}\Big(|\Tilde{\mu}^n_k(t)-\mu_k|>\frac{\eta}{2}\Big|\# \text{ of observations}=c\Big)\\ &\cdot \mathbb{P}(c \text{ observations}|c\geq O)\\
    \leq &\sum_{k=1}^K\sum_{c=O}^{\infty} 2\exp{(\frac{c\cdot \eta^2}{2})}\mathbb{P}(c \text{ observations}|c\geq O)\\
    \leq &2K\exp{(\frac{-O\cdot \eta^2}{2})},
\end{align*}
where the second inequality is derived by the union bound, the third inequality is derived by Hoeffding's inequality.

To make sure that
\begin{align*}
    \mathbb{P}(I_n=1|\text{$\geq O$ observations of each arm})<\frac{\delta}{N},
\end{align*}
we need $2K\exp{(\frac{-O\cdot \eta^2}{2})}<\frac{\delta}{N}$, solving which we obtain
\begin{align*}
    O>\frac{2}{\eta^2}\ln(\frac{2KN}{\delta}).
\end{align*}

Next, we show that if any player $n$ has at least $\frac{2}{\eta^2}\ln(\frac{2KN}{\delta})$ observations of each arm, all players will have an $\eta$-correct ranking of all arms with probability at least $1-\delta$.  We define the following events:
\begin{itemize}
    \item $L$ denotes the event that all players have an $\eta$-correct ranking.
    \item $L_n$ denotes the event that player $n$ has an $\eta$-correct ranking.
    \item $J$ denotes the event that all players have observed each arm at least $O$ times.
    \item $J_n$ denotes the event that player $n$ has observed each arm at least $O$ times.
\end{itemize}
Then we have 
\begin{align*}
    \mathbb{P}(L|J)&\geq 1-\mathbb{P}(\bigcup_{n\in\mathbb{N}} \Bar{L}_n|J_n )\\ &\geq 1-\sum_{n=1}^N \mathbb{P}(\Bar{L}_n|J_n )\\ &\geq 1-N \frac{\delta}{N}\\&=1-\delta,
\end{align*}
where the second inequality is derived by the union bound.

Finally, we show that there exists a $T^{(s)}$ large enough so that all players have $>O$ observations of each arm with probability at least $1-\delta$. We define $A_{n,k}(t)=1$ to be the event that player $n$ observed arm $k$ at time $t$. By the symmetry property, we have
\begin{align*}
    \mathbb{P}(A_{n,k}(t)=1)=&\mathbb{P}(\pi_{n}^{(s)}(t)=k)\mathbb{P}(\sigma_n(t)=0)\\ \leq& \frac{1}{K},
\end{align*}
where the inequality is because of $\mathbb{P}(\pi_{n}^{(s)}(t)=k)=\frac{1}{K}$ by the symmetry property and $\mathbb{P}(\sigma_n(t)=0)\leq 1$. 
To guarantee that the total number of observations each player has of each arm to be at least $O$, we have
\begin{align*}
    \sum_{t=1}^{T^{(s)}}A_{n,k}(t)\geq T^{(s)}\cdot  \mathbb{E}[A_{n,k}(t)]\geq O,
\end{align*}
solving which we obtain 
\begin{align*}
    T^{(s)}> \frac{2K}{\eta^2}\ln{\left(\frac{2KN}{\delta}\right)}=\Omega\left(\frac{K}{\eta^2}\ln(\frac{KN}{\delta})\right),
\end{align*}
which completes the proof of Proposition~2.



\subsection{Proof of Lemma 1}\label{proof_lemma_nocollision}
We prove Lemma~1 by contradiction. Assume that there exists an arm $k$ that $|\mathbb{N}_k|\geq 2$ under the socially optimal policy, denoted by $\hat{\bm{\pi}}(t)$. We then prove that the long-term total reward for all players under $\hat{\bm{\pi}}(t)$ is smaller than that under $\bm{\pi}^*(t)$ under Lemma~1.

Under $\hat{\bm{\pi}}(t)$, we assume players $n$ and $n'$ choosing the same arm $k$, i.e., $\hat{\pi}_n(t)=\hat{\pi}_{n'}(t)=k$. Under $\bm{\pi}^*(t)$, we assume $\hat{\pi}_n(t)=k$ and $\hat{\pi}_{n'}(t)=k'\neq k$. While for any other player $j\neq n,n'$, we assume $\hat{\pi}_j(t)=\pi^*_j(t)$. Then we only need to compare the summed long-term rewards of players $n$ and $n'$ under the two policies, denoted by $\hat{R}(t)$ and $R^*(t)$, respectively. We calculate:
\begin{align*}
    R^*(t)-\hat{R}(t)=&\tilde{\mu}_k(t)+\tilde{\mu}_{k'}(t)+\rho \mathbb{E}[R^*(t+1)]\\ &-\tilde{\mu}_k(t)-\rho \mathbb{E}[\hat{R}(t+1)],
\end{align*}
where the first equality is because players $n$ and $n'$ receive a total reward of $\tilde{\mu}_k(t)+\tilde{\mu}_{k'}(t)$ under $\bm{\pi}^*(t)$, while they only receive $\tilde{\mu}_k(t)$ under $\hat{\bm{\pi}}(t)$ due to collision. For arm $k'$ that explored by player $n'$ under $\bm{\pi}^*(t)$, its expected empirical mean reward at the next time $t+1$ satisfies
\begin{align*}
    \mathbb{E}[\Tilde{\mu}_k(t+1)]=&\Tilde{\mu}_k(t+1) \mathbb{E}[\Tilde{\mu}_k(t+1)|r_k(t)=1]\\&+(1-\Tilde{\mu}_k(t+1))\mathbb{E}[\Tilde{\mu}_k(t+1)|r_k(t)=0]\\
    =&\Tilde{\mu}_k(t+1) \cdot \frac{\Tilde{\mu}_k(t+1) c_k(t)+1}{c_k(t)+1}\\&+(1-\Tilde{\mu}_k(t+1))\cdot \frac{\Tilde{\mu}_k(t+1) c_k(t)}{c_k(t)+1}\\
    =&\Tilde{\mu}_k(t+1),
\end{align*}
where the second equality is derived based on the calculation of empirical mean reward in (5). Therefore, given $\mathbb{E}[R^*(t+1)]=\mathbb{E}[\hat{R}(t+1)]$ under both policies, we obtain $\mathbb{E}[\hat{R}(t+1)]\leq \mathbb{E}[R^*(t+1)]$, as both policies can always make the same decisions for players $n$ and $n'$. Consequently, we obtain
\begin{align*}
    R^*(t)-\hat{R}(t)&=\tilde{\mu}_{k'}(t)+\rho (\mathbb{E}[R^*(t+1)]-\mathbb{E}[\hat{R}(t+1)])\\&\geq \tilde{\mu}_{k'}(t)>0,
\end{align*}
meaning that policy $\bm{\pi}^*(t)$ with $|\mathbb{N}_k|\leq 1$ outperforms $\hat{\bm{\pi}}(t)$ with $|\mathbb{N}_k|= 2$. This completes the proof of Lemma~1.

