\section{An algorithm for minimal Morse sequences} \label{app:min}


In this appendix, we give an algorithm for computing 
a Morse sequence from $L$ to $K$ that is minimal for $F$. 
The input of Algorithm~\ref{alg:DC} is the set $S = K \setminus L$ and the map $F$,
which is restricted to $S$. 




The same notations as for Algorithm~\ref{alg:IC} are used. We derive in the same manner the 
soundness of the algorithm. Here again, the sets $\underline{S}$ to $\overline{S}$ are not needed for computing {\bf Min}$(S,F)$.


 \begin{proposition} \label{prop:cosim5}
If $S$ is a cosimplicial complex,
then {\bf Min}$(S,F)$ is a simplex-wise Morse sequence from $\underline{S}$ to $\overline{S}$
that  is minimal for~$F$. If $K$ is a simplicial complex, then {\bf Min}$(K,F)$ is a Morse sequence on $K$ that  is minimal for~$F$. 
\end{proposition}






\begin{algorithm2e*}[tb]
\KwData{- A cosimplicial complex $S$ with its operators $\partial$ and $\delta$; and\\
- A stack $F : S \rightarrow \mathbb{Z}$.\\
The datastructure for $S$ is an array that stores the simplexes according to their decreasing dimension and weight: we have, for $1 \leq i < j \leq N = Card(S)$:
$dim(S[i]) \geq dim(S[j])$ whenever $F(S[i]) = F(S[j])$; \\ and $F[S[i]] > F(S[j])$ otherwise.}
\KwResult{A Morse sequence from $\underline{S}$ to $\overline{S}$ which is minimal for $F$.}

$i:= 1$; $T := \emptyset$; $U := \emptyset$; $\diamond \ms := \epsilon$; 

 \ForAll{$\sigma \in S$}{
 $\rho(\sigma) := \text{Card}(\delta(\sigma,S))$;

 \lIf{$\rho(\sig$) = 1}{$U:=U \cup \{\sig\}$}
}

\While{$i \leq N$}{

\While{$U \not= \emptyset$}{
 Extract $\sig \in U$;

 \If{ $\rho(\sig) = 1$}{
 Find out the simplex $\tau$ such that $\tau \in \delta(\sig,S)$ and $\tau \not\in T$;

   \If{ $F(\tau) = F(\sigma)$}{

 $\diamond \ms := (\sig,\tau) \cdot (\diamond  \ms)$; $T := T \cup \{\sig,\tau\}$;

 \ForAll{$\mu \in \partial(\sig,S) \cup \partial(\tau,S)$}{
 $\rho(\mu) := \rho(\mu) - 1$; 

 \lIf{$\rho(\mu) = 1$}{$U := U \cup \{ \mu \}$}

}

}

}
}
\lWhile{$S[i] \in S$ and $i \leq N$}{ $i:= i+1$}

\If{$i\leq N$}{

 $\tau := K[i]$;  $T := T \cup \{ \tau \}$; $\diamond \ms := \tau \cdot (\diamond \ms)$;  

 \ForAll{$\sig \in \partial(\tau)$}{
 $\rho(\sig) := \rho(\sig) - 1$; 

 \lIf{$\rho(\sig) = 1$}{$U := U \cup \{ \sig \}$}
}}}

\Return $\diamond \ms$\;
\caption{{\bf Min}($S,F$)} \label{alg:DC}
