\begin{algorithm}[h]
\label{alg:tcp_dependency}
\caption{Filter Adversarial Examples for Categorical and Numerical Dependencies in TCP Case}
\small
\SetAlgoLined
\KwIn{- $x_{adv}$: Adversarial Examples (structured as a dataframe), \newline 
       - Service\_tcp, Service\_udp, Service\_icmp: Lists of protocol-specific services, \newline
       - Flag\_tcp, Flag\_udp, Flag\_icmp: Lists of protocol-specific flags, \newline
       - Binary\_features: List of features expected to be binary}
\KwOut{Valid adversarial examples $x_{valid}$}

\textbf{Convert} $x_{adv}$ to dataframe $adversarial\_data$\;
\textbf{Initialize} $x_{valid} \gets []$\;

\For{$i = 1$ \textbf{to} size($x_{adv}$)[0]}{
    Cast binary features and protocol type fields of $adversarial\_data_i$ to integer\;
    \If{$adversarial\_data_i[protocol\_type\_tcp] == 1$}{
        Ensure $adversarial\_data_i[protocol\_type\_udp] = 0$ and $adversarial\_data_i[protocol\_type\_icmp] = 0$\;
        \For{each $feature$ in Binary\_features}{
            Ensure $adversarial\_data_i[feature] \in \{0, 1\}$\;
        }
        \If{any($adversarial\_data_i[service] == 1$) for $service \in Service\_tcp$}{
            \If{any($adversarial\_data_i[flag] == 1$) for $flag \in Flag\_tcp$}{
                Append $adversarial\_data_i$ to $x_{valid}$\;
            }
        }
    }
}
\Return $x_{valid}$\;

\end{algorithm}
