\section{Pseudo Code} \label{sec:Pseudo Code}

Without implicit knowledge sharing approaches, each task $i$ has its control policy $\pi_i$ and guide policy $\Pi^g_i$.
With implicit knowledge sharing approaches, there is a unified control policy $\pi$ and guide policy $\Pi^g$ with the input of task representation $z_i$.
In both cases, we uniformly represent tasks as subscripts and omit the network parameters for a clear presentation in pseudo-code.
Specifically,
\begin{itemize}[leftmargin=2em]
\vspace{-5pt}
\setlength{\itemsep}{0pt}
\setlength{\parsep}{0pt}
\setlength{\parskip}{2pt}
    \item The \textbf{actor network} with parameter $\phi$ for task $i$'s control policy is denoted as $\pi_i(a_t|s_t)$.
    \item The \textbf{critic network} with parameter $\theta$ for task $i$'s control policy is denoted as $Q_i(s_t,a_t)$.
    \item The \textbf{temperature parameter} for task $i$'s control policy is denoted as $\alpha_i$.
    \item The \textbf{guide actor network} with parameter $\phi^g$ for task $i$'s guide policy is denoted as $\Pi^g_i(j_t|s_t)$.
    \item The \textbf{guide critic network} with parameter $\theta^g$ for task $i$'s guide policy is denoted as $Q^g_i(s_t, j_t)$.
    \item The \textbf{guide temperature parameter} for task $i$'s guide policy is denoted as $\alpha^g_i$.
    \item The \textbf{comparable guide critic network} with parameter $\hat{\theta}^g$ for task $i$ is denoted as $\hat{Q}^g_i(s_t, j_t)$.
\end{itemize}

\vspace{-3pt}
\begin{algorithm}[htbp]
\caption{Control Policy's Training Step}
\label{alg:control_policy}
\textbf{Input}: minibatch $\mathcal{B}$ contains $\langle i, s_t, a_t, r_t, s_{t+1} \rangle$ \\
\textbf{Initialization}:
actor network $\pi$, critic network $Q$, SAC temperature $\alpha$
\begin{algorithmic}[1] %[1] enables line numbers
\State Optimize $\theta$ with SAC's critic loss in Equation \ref{eq:sac_critic}
$$
J_Q(\theta) = \mathbb{E}_{(i, s_t, a_t, r_t, s_{t+1}) \sim \mathcal{B}} \left[ \frac{1}{2} \left( Q_i(s_t, a_t) - \left( r_t + \gamma V_{i}(s_{t+1}) \right) \right)^2 \right]
$$
\State Optimize $\phi$ with SAC's actor loss in Equation \ref{eq:sac}
$$
J_\pi(\phi) = \mathbb{E}_{(i, s_t) \sim \mathcal{B}} \left[ \mathbb{E}_{a_t \sim \pi_i} \left[ \alpha_i \log \pi_i(a_t| s_t) - Q_i(s_t, a_t) \right] \right]
$$
\State Optimize $\alpha$ with SAC's alpha loss in Equation \ref{eq:sac_alpha}
$$
J(\alpha) = \mathbb{E}_{i \sim \mathcal{B}} \left[ \mathbb{E}_{a_t \sim \pi_i}  \left[ -\alpha_i \log \pi_i(a_t | s_t) - \alpha_i \bar{\mathcal{H}} \right] \right]
$$
\end{algorithmic}
\end{algorithm}

\vspace{-2pt}
\begin{algorithm}[htbp]
\caption{Guide Policy's Training Step}
\label{alg:guide_policy}
\textbf{Input}: actor network $\pi$, SAC temperature $\alpha$, minibatch $\mathcal{B}^g$ contains $\langle \{s_{t'}, a_{t'}, r_{t'}\}_{t'=t}^{t+K-1}, i, j_t, s_{t+K} \rangle$ \\
\textbf{Initialization}:
guide actor network $\Pi^g$, guide critic network $Q^g$, guide SAC temperature $\alpha^g$
\begin{algorithmic}[1] %[1] enables line numbers
\State Hindsight off-policy correct $j_t$ into $j'_t$ following Equation \ref{eq:hindsight}
$$
j'_t = \arg \max_{j} \sum_{t'=t}^{t+K-1} \log \pi_j(a_{t'}|s_{t'})
$$
\State Calculate the guide reward $r^g_t$ following Equation \ref{eq:guide_reward}
$$
r^g_t = \sum_{t'=t}^{t+K-1} \gamma^{t'-t} r_{t'}
$$
\State Optimize $\theta^g$ with SAC's critic loss for guide policy
$$
J_{Q^g}(\theta^g) = \mathbb{E}_{(i, s_t, j'_t, r^g_t, s_{t+K}) \sim \mathcal{B}^g} \left[ \frac{1}{2} \left( Q^g_i(s_t, j'_t) - \left( r^g_t + \gamma^K V^g_{i}(s_{t+K}) \right) \right)^2 \right]
$$
\State Optimize $\phi^g$ with SAC's actor loss for guide policy
$$
J_{\Pi^g}(\phi^g) = \mathbb{E}_{(i, s_t) \sim \mathcal{B}^g} \left[ \mathbb{E}_{j_t \sim \Pi^g_i} \left[ \alpha^g_i \log \Pi^g_i(j_t| s_t) - Q^g_i(s_t, j_t) \right] \right]
$$
\State Optimize $\alpha^g$ with SAC's alpha loss for guide policy
$$
J(\alpha^g) = \mathbb{E}_{i \sim \mathcal{B}^g} \left[ \mathbb{E}_{j_t \sim \Pi^g_i}  \left[ -\alpha^g_i \log \Pi^g_i(j_t | s_t) - \alpha^g_i \bar{\mathcal{H}}^g \right] \right]
$$
\end{algorithmic}
\end{algorithm}

\subsection{Pseudo Code of Policy Training} \label{sec:Pseudo Code of Policy Training}

Algorithm \ref{alg:control_policy} describes a training step for the control policy given a minibatch of data $\mathcal{B}$, which contains a batch of tasks $i$, states $s_t$, actions $a_t$, rewards $r_t$, and next states $s_{t+1}$.

In addition, Algorithm \ref{alg:guide_policy} describes a training step for the guide policy given a minibatch data $\mathcal{B}^g$.
The data $\mathcal{B}^g$ not only contains a batch of tasks $i$, states $s_t$, actions $j_t$ taken by guide policy, and $K$ timesteps ahead states $s_{t+K}$ but also contains rewards $\{r_{t'}\}_{t'=t}^{t+K-1}$ accrued over $K$ timesteps for calculating the guide reward.
Moreover, $\mathcal{B}^g$ includes states $\{s_{t'}\}_{t'=t}^{t+K-1}$ and actions $\{a_{t'}\}_{t'=t}^{t+K-1}$ taken by control policy over the $K$ timesteps for hindsight off-policy correction.

\subsection{Pseudo Code of Comprehensive CTPG} \label{sec:Pseudo Code of Comprehensive CTPG}

The full pseudo-code of CTPG is described in Algorithm \ref{alg:CTPG}.

\begin{algorithm}[htbp]
\caption{Cross-Task Policy Guidance}
\label{alg:CTPG}
\textbf{Input}: guide step $K$ \\
\textbf{Initialization}:
actor network $\pi$, critic network $Q$,
guide actor network $\Pi^g$, guide critic network $Q^g$,
comparable guide critic network $\hat{Q}^g$,
replay buffer $\mathcal{D} \leftarrow \emptyset$
\begin{algorithmic}[1] %[1] enables line numbers
\For{each epoch}
    \State Update the task subset $\mathbb{T}^g$ requiring guidance with
    $$
    \mathbb{T}^g = \left\{ i | \log \alpha_i \le \frac{1}{N} \sum_{j=1}^N \log \alpha_j \right\}
    $$
    \State \textcolor{gray}{\texttt{\//\// Inference Stage}}
    \For{each task $i$}
        \For{each timestep $t=0,1,\dots,T$}
            \If{$t~\%~K = 0$} 
                \If{$i \notin \mathbb{T}^g$}
                \Comment{Guide-Block Gate}
                    \State Behavior policy $\pi' \leftarrow \pi_i$
                \Else
                    \State Get comparable guide Q-values $\{\hat{Q}_i^g(s_t, j)\}_{j=1}^N$
                    \State Get control V-value $V_i(s_t)$ with Monte Carlo sampling control Q-values
                    \State Calculate policy-filter gate mask $m$ following
                    \Comment{Policy-Filter Gate}
                    $$
                    m_{j} \leftarrow \left\{ 
                        \begin{aligned}
                            & 1, & \hat{Q}_i^g(s_t, j) \ge V_i(s_t) \\
                            & 0, & \hat{Q}_i^g(s_t, j) < V_i(s_t) 
                        \end{aligned}
                        \right.
                    $$
                    \State Sample $\pi' \leftarrow \pi_{j_t}$ with $j_t \sim \operatorname{Normalize}(\Pi_i^g(\cdot|s_t) \cdot m)$
                    \Comment{Guide Policy}
                \EndIf
            \EndIf
            \State Execute action $a_t \sim \pi'(\cdot | s_t)$ and get reward $r_t$ and next state $s_{t+1}$
            \State Store the transition into $\mathcal{D}$
        \EndFor
    \EndFor
    \State \textcolor{gray}{\texttt{\//\// Training Stage}}
    \For{each training step $t=0,1,\dots,T$}
        \State Sample a minibatch $\mathcal{B}$ of all tasks from $\mathcal{D}$
        \State Optimize $\phi$ and $\theta$ with $\mathcal{B}$ as described in Algorithm \ref{alg:control_policy}
        \If{$t~\%~K = 0$}
            \State Sample a minibatch $\mathcal{B}^g$ of task subset $\mathbb{T}^g$ from $\mathcal{D}$
            \State Optimize $\phi^g$ and $\theta^g$ with $\mathcal{B}^g$ as described in Algorithm \ref{alg:guide_policy}
            \State Optimize $\hat{\theta}^g$ using Bellman Equation in Equation \ref{eq:comparable_q} with $\mathcal{B}^g$
        \EndIf
    \EndFor
\EndFor
\end{algorithmic}
\end{algorithm}

\section{Details on Comparable Guide Q-Value} \label{sec:Details on Comparable Guide Q-Value}

We expand the value function of SAC to obtain:
\begin{equation}
\begin{aligned}
    V_i(s_t) &= \mathbb{E}_{a_{t} \sim \pi_i} \left[ Q_i (s_{t}, a_{t}) - \alpha_i \log \pi_i(a_{t} | s_{t}) \right] \\
    &= \mathbb{E}_{a_t \sim \pi_i} \left[ Q_i(s_{t}, a_{t}) + \alpha_i \mathcal{H}(\pi_{i}(\cdot|s_{t})) \right] \\
    &= \mathbb{E}_{a_t \sim \pi_i} \left[ R_i(s_t, a_t) + \gamma\mathbb{E}_{s_{t+1} \sim P_i} \left[ V_i(s_{t+1}) \right] + \alpha_i \mathcal{H}(\pi_{i}(\cdot|s_{t})) \right] \\
    &= \mathbb{E}_{a_t \sim \pi_i} \left[ R_i(s_t, a_t) + \alpha_i \mathcal{H}(\pi_{i}(\cdot|s_{t})) + \gamma\mathbb{E}_{s_{t+1} \sim P_i} \left[ V_i(s_{t+1}) \right] \right] \\
    &= \cdots \\
    &= \mathbb{E}_{a_{t'} \sim \pi_i, s_{t'+1} \sim P_i} \left[ \sum_{t'=t}^{\infty} \gamma^{t'-t} \left( R_i(s_{t'}, a_{t'}) + \alpha_i \mathcal{H}(\pi_{i}(\cdot|s_{t'})) \right) \right].
\end{aligned}
\end{equation}
By repeatedly expanding $V_i$, we get the final form, which is actually the optimization objective under the maximum entropy reinforcement learning framework.

Then, we consider that the trajectory generation process solely using the current task’s control policy $\pi_i$ can be regarded as equipped with a special guide policy $\Pi^{\tilde{g}}_i$ in SAC.
The comparable guide Q-value in Equation \ref{eq:comparable_q} of this special guide policy $\Pi^{\tilde{g}}_i$ is:
\begin{equation}
\resizebox{\linewidth}{!}{$
\begin{aligned}
    \hat{Q}^{\tilde{g}}_i(s_t, i)
    &= \mathbb{E}_{a_{t'} \sim \pi_{i}, s_{t'+1} \sim P_i} \left[ \sum_{t'=t}^{t+K-1}\gamma^{t'-t} \left( R_i(s_{t'}, a_{t'}) + \alpha_i \mathcal{H}(\pi_{i}(\cdot|s_{t'})) \right)\right]
    + \gamma^K \mathbb{E}_{s_{t+K} \sim P_i} \left[ \hat{Q}^{\tilde{g}}_i(s_{t+K}, i) \right] \\
    &= \mathbb{E}_{a_{t'} \sim \pi_{i}, s_{t'+1} \sim P_i} \left[ \sum_{t'=t}^{t+K-1}\gamma^{t'-t} \left( R_i(s_{t'}, a_{t'}) + \alpha_i \mathcal{H}(\pi_{i}(\cdot|s_{t'})) \right) + \gamma^K \hat{Q}^{\tilde{g}}_i(s_{t+K}, i) \right] \\
    &= \cdots \\
    &= \mathbb{E}_{a_{t'} \sim \pi_i, s_{t'+1} \sim P_i} \left[ \sum_{t'=t}^{\infty} \gamma^{t'-t} \left( R_i(s_{t'}, a_{t'}) + \alpha_i \mathcal{H}(\pi_{i}(\cdot|s_{t'})) \right) \right] \\
    &= V_i(s_t).
\end{aligned}
$}
\end{equation}
The ellipsis part is the repeated expansion of $\hat{Q}^{\tilde{g}}_i$.
Therefore, in SAC, the policy-filter gate can refine the action space of the guide policy by directly comparing $\hat{Q}_i^g(s_t, j_t)$ and $V_i(s_t)$.


\section{Details on Hindsight Off-Policy Correction for SAC} \label{sec:Details on Hindsight Off-Policy Correction for SAC}

The hindsight off-policy correction mechanism is proposed to mitigate the non-stationarity challenge of the guide policy update process.
It reassigns the action $j_t$ sampled by the past guide policy to a new one $j'_t$, whose control policy $\pi_{j'_t}$ is more likely to output the historical action sequence $\{a_{t'}\}_{t'=t}^{t+K-1}$.
During the guide policy update process, we first get the reassigned action $j'_t$ following the maximum likelihood estimation in Equation \ref{eq:hindsight}.
For SAC's critic update, the critic loss of the guide policy is,
\begin{equation}
    J_{Q^g}(\theta^g) = \mathbb{E}_{(i, s_t, j'_t, r^g_t, s_{t+K}) \sim \mathcal{B}^g} \left[ \frac{1}{2} \left( Q^g_i(s_t, j'_t) - \left( r^g_t + \gamma^K V^g_{i}(s_{t+K}) \right) \right)^2 \right],
\end{equation}
where the hindsight correction explicitly modifies the update procedure by shifting the Q-value estimation from $Q_i^g(s_t, j_t)$ to $Q_i^g(s_t, j'_t)$.
For SAC's actor update, the actor loss of the guide policy is, 
\begin{equation}
    J_{\Pi^g}(\phi^g) = \mathbb{E}_{(i, s_t) \sim \mathcal{B}^g} \left[ \mathbb{E}_{j_t \sim \Pi^g_i} \left[ \alpha^g_i \log \Pi^g_i(j_t| s_t) - Q^g_i(s_t, j_t) \right] \right],
\end{equation}
which is not explicitly different from the original function in SAC.
However, it indirectly affects actor learning due to SAC's unique actor update method \cite{haarnoja2018soft}.
Specifically, SAC's actor loss is derived from its optimization objective, and the policy is updated according to,
\begin{equation}
    \pi_{\text{new}} = \arg\min_{\pi' \in \Pi} D_{KL} \left( \pi'(\cdot | s_t) \left\| \frac{\exp\left(\frac{1}{\alpha} Q^{\pi_{\text{old}}}(s_t, \cdot) \right)}{Z^{\pi_{\text{old}}}(s_t)} \right. \right),
\end{equation}
where the partition function $Z^{\pi_{\text{old}}}(s_t)$ normalizes the distribution.
In essence, SAC's policy is updated by fitting the distribution of the SoftMax function of Q-value with temperature $\alpha$.
Therefore, modifying the update of $Q_i^g(s_t, j_t)$ to $Q_i^g(s_t, j'_t)$ using hindsight correction leads to a different guide policy actor optimization objective, thus affecting the training of the guide actor network.

