% \end{equation}
where \( \bm{R}_i^{T_o} \in \mathbb{R}^{2 \times 2} \) is the rotation matrix parameterized by \( \theta_i\). Similarly, lane segments are also converted into the agent-centric coordinate frame. For a lane segment \( \bm{L} \), its attribute $\bm{P}_L$ is defined as $\bm{P}_L= \bm{P}_1^L - \bm{P}_0^L$, where $\bm{P}_0^L, \bm{P}_1^L \in \mathbb{R}^2$ are the start and end positions of lane segment, respectively. 
\subsection{{Local Temporal-Spatial Encoder
}}
Local Temporal-Spatial Encoder includes Agent-Agent Encoder, LTAA, MSE, and Agent-Lane Encoder are shown in Fig. \ref{fig:2}.
\begin{figure}
    \centering
    \includegraphics[width=1\linewidth]{three.pdf}
    \caption{Illustration of Local Box Convolutional Attention with local boxes of sizes 3, 6, and 12 at each layer. In this study, we use local boxes of sizes 3, 7, and 21 at each layer, depending on the length of the sequence in the Argoverse 1 motion prediction dataset.}
    \label{fig:3}
\end{figure}
% The LTAA aims to capture the local temporal interactions of agents in observed time steps, which enhances the model's ability to model local temporal motion trends and social interaction within specific temporal ranges. Similar to \cite{zhou2022hivt}, We use an Agent-Agent Encoder to capture the spatial interaction features between the agents as the input of LTAA.
\subsubsection{\textbf{Agent-Agent Encoder}}
This module aims to capture the interaction features between the central agent and its neighboring agents over the time steps from $t=1$ to $T_{o}$. Given the inputs $\bm{h}_i^t$, $\bm{h}_j^t$, and $\bm{h}_{ij}^t$, the embeddings are computed as follows:
\begin{equation}
\bm{s}_i^t = \phi_{\text{center}}(\bm{h}_i^t) , \quad \bm{s}_{ij}^t = \phi_{\text{nbr}}(\bm{[h}_j^t, \bm{h}_{ij}^t]),
\label{eq:4}
\end{equation}
where $\phi_{\text{center}(\cdot)}$ and $\phi_{\text{nbr}(\cdot)}$ are MLP blocks. Following HiVT\cite{zhou2022hivt}, we adopt the multi-head attention (MHA) mechanism to represent the spatial interaction features \( \bm{c}_i^t \) among agents:
\begin{equation}
\bm{c}_i^t = \text{MHA}(\bm{s}_i^t, \bm{s}_{ij}^t),
\label{eq:9}
\end{equation}
where \( \bm{c}_i^t \in \mathbb{R}^{d_h} \), ${d_h}$ is the model dimension.
Finally, we concatenate the output \( \bm{c}_i^t \) from time step 1 to \( T_{\text{o}} \) as \( \bm{z}_i = \{\bm{c}_i^t\}_{t=1}^{T_{\text{o}}} \), where \( \bm{z}_i \in \mathbb{R}^{T_{\text{o}} \times d_h} \), and put it into the subsequent LTAA module.
\subsubsection{\textbf{Local Trend-Aware Attention Mechanism}}
LTAA aims to capture the local temporal motion trends of agents in observed time steps, thereby enhancing the ability to model agent social interactions in the temporal dimension.
Like \cite{zhou2022hivt}, we append a learnable token $\bm{z}^{T_o+1} \in \mathbb{R}^{d_h}$ at the end of the input sequence and add learnable positional embeddings to all tokens. These tokens are then stacked into a matrix $\bm{S}_i \in \mathbb{R}^{(T_o+1) \times d_h}$, which is fed into the LTAA module.
Next, the input sequence is processed through a causal $1 \times k$ convolution layer with BatchNorm to generate queries $\bm{Q}_i^{LTAA}$ and keys $\bm{K}_i^{LTAA}$, where $k$ is the convolution kernel size in the temporal dimension, a linear transformation is then applied to obtain values $\bm{V}_i^{LTAA}$:
\begin{equation}
\begin{aligned}
\bm{Q}_i^{LTAA} &= \text{BatchNorm(conv}(\bm{z}_i)), \\
\bm{K}_i^{LTAA} &= \text{BatchNorm(conv}(\bm{z}_i)), \\
\bm{V}_i^{LTAA} &= \bm{W}_V^{LTAA} \bm{z}_i,
\end{aligned}
\end{equation}
where $\bm{W}_V^{LTAA}$ is a learnable matrix. 
We apply causal $1 \times k$ convolutions within each box to ensure the temporal trend features at the current time step depend on the current and previous $k-1$ time steps. 
% Causality is enforced by combining padding, clipping, and applying a mask within the local box to ensure that each time step depends only on the current and previous time steps.
Considering that adjacent time steps typically exhibit stronger correlations than distant ones, we apply local box convolutional attention (denoted as \(\text{LMHA}\), see Fig. \ref{fig:3}) within non-overlapping local boxes to capture temporal motion trends, formulated as:
\begin{equation}
\bm{b}_i^{u_v} = \text{LMHA}(\bm{Q}_i^{LTAA}, \bm{K}_i^{LTAA}, \bm{V}_i^{LTAA}),
\end{equation}
where \(\bm{b}_i^{u_v}\) represents the embedded local temporal motion trend for the $v$-th layer, with box size of \(u_v\). To capture multi-scale local temporal motion trends while preserving the large receptive field of standard $\text{MHA}$, we progressively increase the local box size across different layers of local box convolutional attention from bottom to top. Specifically, LTAA consists of three cascaded layers, each operating at different local box sizes, denoted as \(\bm{b}_i^{u_1}\), \(\bm{b}_i^{u_2}\), and \(\bm{b}_i^{u_3}\). The outputs of these layers are cascaded to form the final unified representation $\bm{B}_i = \text{Cascade}(\bm{b}_i^{u_1}, \bm{b}_i^{u_2}, \bm{b}_i^{u_3})$. Compared to multi-head attention, LTAA reduces parameter complexity by restricting attention computations to localized matrices, thereby improving computational efficiency.
Similar to BERT \cite{lee2018pre}, we use the GELU activation function in the feedforward layer to enhance the model performance.


