\subsubsection{\textbf{Motion State Encoder} }
% The kinematic state of agents at observed time steps significantly influences their future trajectories. To capture the dynamic social interactions among agents, we have developed the Kinematic Encoder, which is deployed after the LTAA module. 
In trajectory prediction, the high-order motion state attributes of agents play a crucial role in determining their future trajectories. The ability to model and understand the dynamic interactions between agents is essential for accurate prediction. To achieve this, we have designed the MSE, which is deployed after the LTAA module to capture the high-order motion state attributes and further enhance the spatial interactions of the agents.
MSE encodes motion state attributes in a vector $\bm{k}_{ij}$, defined as:
\begin{equation}
    \bm{k}_{ij} = [\bm{h}_{ij}, \bm{a}_{j}, \dot{\bm{a}_{j}}, \theta_{j}],
\end{equation}
where $\bm{h}_{ij}$ represents the relative positions of agents, while $\bm{a}_{j}$, $\dot{\bm{a}_{j}}$ and $\theta_{j}$ correspond to the acceleration, jerk, and heading of neighboring agents, respectively. Specifically, the relative positions and heading angles are spatial information, while acceleration and jerk are higher-order motion information.
We employ an MLP denoted as $\phi_\text{m}(\cdot)$ to embed high-order motion state attributes $\bm{k}_{ij}$, and implement MHA with $\bm{B}_{i}$ from LTAA module to generate a temporal-spatial embedding $\bm{e}_i$:
\begin{equation}
    \bm{e}_i = \text{MHA}(\bm{B}_i, \phi_\text{m}(\bm{k}_{ij})),
\end{equation}
where $\bm{B}_i$ serves as the query, while $\phi_\text{m}(\bm{k}_{ij})$ serves as both the key and value in the MHA process. The MSE enables the model to effectively integrate motion state information, which is then fed into the subsequent agent-lane encoder module, improving the accuracy of trajectory prediction.

% \subsection{Interaction Feature Fusion}
% The Interaction Feature Fusion module integrates temporal-spatial features from local and global contexts, aggregating interactions from multiple agents and agent-lane features while using multi-head attention to capture global dependencies and social interactions across the scene.
\subsubsection{\textbf{Agent-Lane Encoder}}
To capture the interaction between agents and surrounding lanes, we introduce the encoding of local lane information:  
\begin{equation}  
\bm{z}_i^L = \phi_{\text{lane}} \left( \left[ \bm{R}_i^{T_o} \bm{P}_L,\bm{R}_i^{T_o} \left(\bm{P}_0^L - \bm{p}_i^{T_o}\right), a^L \right] \right),  
\end{equation}  
where $\phi_{\text{lane}}(\cdot)$ is an MLP encoder for lane segment features, and $a^L$ denotes the semantic attributes of the lane segment. For more details, see HiVT \cite{zhou2022hivt}.
% where $\phi_{\text{lane}}(\cdot)$ is an MLP encoder to extracte lane segment features and $a^L$ represents the semantic attributes of the lane segment.  
We can obtain the local interaction embedding as follows:
\begin{equation}
    \psi^\text{local}_i = \text{MHA}(\bm{e}_i, \bm{z}_i^L),
\end{equation}
where $\psi^\text{{local}}_i$ is final local interaction embedding, $\bm{e}_i$ is the query, both key and value are $\bm{z}_i^L$.

\subsection{Global Interaction}
In this module, we use an MLP $\phi_{\text{global}}(\cdot)$ to encode the relative positions and angular differences between agents, generating interaction embeddings for each agent pair. Then, the pairwise embedding $\bm{g}_{ij}$ is defined as:  
\begin{equation}
  \bm{g}_{ij} = \phi_{\text{global}} \left(\left[ \bm{h}_{ij}^{T_o},\cos(\Delta \theta_{ij}), \sin(\Delta \theta_{ij})\right] \right),
\end{equation}
where $\Delta \theta_{ij}$ represents the relative angle between agents $i$ and $j$. Then, we leverage the MHA mechanism to combine local interaction embedding $\psi^\text{{local}}_i$ and the pairwise embedding $\bm{g}_{ij}$, formulated as:   
\begin{equation}
    \psi^\text{{global}}_i = \text{MHA}\left(\psi^\text{{local}}_i, [ \psi^\text{{local}}_j,\bm{g}_{ij}] \right),
\end{equation}
where $\psi^\text{{global}}_i$ is the global interaction embedding. After this step, we could integrate rich information about surrounding agents and lane segments.

% To further refine the trajectory predictions, we have adopted a two-stage framework that uses an MLP-based refinement network to correct the trajectory prediction errors.
\subsection{Multi-modal Decoder}
We use three separate MLP blocks $\phi_\text{{d}}(\cdot)$, to process $\psi^\text{{local}}_i$ and $\psi^\text{{global}}_i$. These blocks output the concatenation of the predicted future position $\bm{\hat\mu}_{i,m}$, scale $\bm{\hat\beta}_{i,m}$, and the associated probability $\bm{\hat\pi}_{i,m}$ for each agent $i$ and the trajectory mode $m$:
% We use a three separate MLP blocks $\phi_{d}(\cdot)$ to process the $\psi^{local}_i$ and $\psi^{global}_i$ and output the concatenation of the future position $\hat\mu_{i,m}$ and scale $\hat\beta_{i,m}$, along with the associated probability $\hat\pi_{i,m}$ for each agent $i$ and mode $m$:
\begin{equation}
    \{(\bm{\hat\mu}_{i,m}, \bm{\hat\beta}_{i,m}), \bm{\hat{\pi}}_{i,m}\}_{m=1}^{M} = \phi_\text{{d}}([\psi^\text{local}_{i}, \psi^{\text{global}}_i]),
\end{equation}
where $M$ is the number of modes, we define the distribution of the stage-one output trajectories as a mixture of Laplace distributions, formulated as:
\begin{equation}
    {\bm{\hat{Y}}_i^{\text{1}}} = \sum_{m=1}^{M} \bm{\hat\pi}_{i,m} \text{Laplace}(\bm{\hat\mu}_{i,m}, \bm{\hat\beta}_{i,m}),
\end{equation}
where ${\bm{\hat{Y}}_i^{\text{1}}}$ represents the predicted trajectory distribution of agent \(i\) at the first stage.
\subsection{Lightweight Proposal Refinement Module}
% The Lightweight Proposal Refinement Module (LPRM) refines the initial trajectory predictions with multiple lightweight MLP layers, achieving both high computational efficiency and enhanced prediction accuracy. The inputs to LPRM include the first-stage predicted trajectories \( \hat{Y}_i^{\text{1}} \), local features \( \psi^{local}_i \), global features \( \psi^{global}_i \), and the full trajectory \( Y_i^{\text{full}} \), composed of the observed trajectory \( X \) and the first-stage predicted trajectories \( \hat{Y}_i^{\text{1}} \).  
The LPRM refines the initial trajectory predictions using lightweight MLP layers, effectively reducing parameter complexity while enhancing prediction accuracy.

\subsubsection{\textbf{Proposal Embedding}}
The initial trajectory prediction serves as the proposal, providing a foundation for subsequent refinement in the second stage. We use an MLP \( \phi_\text{p}(\cdot) \) to process \( \hat{Y}_i^{\text{1}} \), formulated as:
\begin{equation}
       \psi^\text{P}_i = \phi_\text{p}(\bm{\hat{Y}}_i^{\text{1}}),
\end{equation}
where $\psi^\text{P}_i$ is the trajectory proposal embedding.
\subsubsection{\textbf{Consist Embedding} }
The full trajectory \( \bm{Y}_i^{\text{full}} \) represents as \( \bm{Y}_i^{\text{full}}=[\bm{X},\bm{\hat{Y}}_i^{\text{1}}] \),  
% comprising the observed trajectory \( \bm{X} \) and the first-stage predicted trajectories \( \bm{\hat{Y}}_i^{\text{1}} \),  
is processed using a two-layer MLP with residual connections, denoted as \( f_{\text{full}} \), and formulated as:
\begin{equation}
  Y^f_{i} = f_{\text{full}}(\bm{Y}_i^{\text{full}}),
\end{equation}
where ${Y}_i^f$ is the refined full trajectory embedding.
Then, we use a three-layer MLP \( \phi_{\text{cons}(\cdot)} \) to process \( {Y}_i^f \) for consistency processing, capturing physical constraints and temporal-spatial regularities:
\begin{equation}
    \psi_i^\text{cons} = \phi_{\text{cons}}({Y}_i^f),
\end{equation}
where \( \psi_i^\text{cons} \) is the consistency trajectory embedding that enhances trajectory continuity and physical plausibility.

\subsubsection{\textbf{Proposal Refinement Decoder} }
We utilize a three-layer MLP \( \phi_{\text{refine}}(\cdot) \) to process the joint embedding \( \psi^\text{refine}_i=\text{Concat}(\psi_i^\text{cons},\psi^\text{P}_i,\psi^\text{local}_i,\psi^\text{global}_i) \) and compute the trajectory offset $\Delta \bm{\hat{Y}}_i$, as expressed by:  
\begin{equation}
\Delta \bm{\hat{Y}}_i = \phi_{\text{refine}}(\psi^\text{refine}_i),
\end{equation}
\begin{equation}
\bm{\hat{Y}}_{i} = \bm{\hat{Y}}_i^{\text{1}}+ \Delta \bm{\hat{Y}}_i,
\end{equation}
where \( \bm{\hat{Y}}_{i} \) is the stage-two predicted trajectory of agent \( i \).
LPRM exclusively utilizes MLPs for a lightweight design, significantly reducing computational overhead while enhancing the accuracy, continuity, and physical plausibility of trajectory predictions.
\subsection{Loss Function} 
The loss function includes two-stage losses to optimize trajectory diversity and accuracy:
\begin{equation}
L_{all} = L_{\text{stage1}} + \lambda_1 L_{\text{stage2}},
\end{equation}
where \(L_{all}\) is the total loss function, \( \lambda_1 \) is a hyperparameter controlling the importance of the second stage, $ L_{\text{stage1}}$ and $ L_{\text{stage2}}$ are the loss functions for the first and second stages, respectively.
% The first stage loss function 
\( L_{\text{stage1}} \) aims to promote the diversity of multi-modal trajectories and consists of classification loss \( L_{\text{cls}} \) and regression loss \( L_{\text{reg}} \):
\begin{equation}
    L_{\text{stage1}} = L_{\text{cls}} + L_{\text{reg}}.
\end{equation}

Similar to \cite{zhou2022hivt}, \( L_{\text{cls}} \) uses the cross-entropy loss to measure the difference between the predicted probabilities and the target distribution. \( L_{\text{reg}} \) uses negative log-likelihood to encourage the diversity of multi-modal trajectories.
% \begin{equation}
% L_{\text{reg}} = - \frac{1}{N T_{\text{p}}} \sum_{i=1}^{N} \sum_{t=T_\text{o}+1}^{T_\text{o}+T_{\text{p}}} \log P(\bm{G}_{i}^t | \bm{\hat{\mu}}_{i}^t, \bm{\hat{\beta}}_{i}^t),
% \end{equation}
% where $\mathrm{P}(\cdot\mid\cdot)$ represents the probability density function of the Laplace distribution, \(\bm{G}_{i}^t \) represents the ground truth, \( \bm{\hat{\mu}}_{i}^t \) and \(\bm{\hat{\beta}}_{i}^t \) are the best-predicted position and scale parameters, respectively.
\( L_{\text{stage2}} \) aims to further refine the trajectory and improve the accuracy of the prediction using the Smooth L1 loss function:
\begin{equation}
L_{\text{stage2}} = \frac{1}{NT_{\text{p}}} \sum_{i=1}^{N} \sum_{t=T_{\text{o}} + 1}^{T_\text{o}+T_{\text{p}}} \text{SmoothL1}(\bm{\hat{Y}}_{i}^t - \bm{G}_{i}^t),
\end{equation}
\begin{equation}
\text{SmoothL1}(x) =
\begin{cases}
0.5x^2, & \text{if } |x| < 1, \\
|x| - 0.5, & \text{otherwise.}
\end{cases}
\end{equation}
where $\bm{G}_{i}^t$ represents the ground truth, $\text{SmoothL1}(\cdot)$ is the Smooth L1 loss function, which enhances trajectory prediction accuracy by effectively balancing error penalization.

