% & \quad +\left. \mathds{1}_{\left\{n > S\right\}} \!\!\!\!\!\! \sum_{k=2S-n+1}^{S}\!\!\!\!\!\!\mathds{1}_{\left\{\epsilon_{s_{k},s_{k-1}}\left(e\right) = s_{k}\right\}}Z_e\left(s_{k},s_{k-1}\right)\delta_{s_{k},s_{k-1}}\right]\\
