\begin{equation} \label{eq:reward_transmit}
\begin{aligned}
&R_{\textrm{E}}\left(\boldsymbol{a}\left(n\right)|\boldsymbol{s}\left(n\right)\right)\\
&= \!\!
\begin{cases}
    0, \quad \quad \quad \quad \quad \quad \quad \quad \quad \quad \quad \quad \quad \quad \ \ \text{if} \ n = 1, \\
    -\!\!\sum\limits_{e \in \mathcal{E}}\!\!\mathds{1}_{\left\{\epsilon_{s_{n-1},s_{n}}\left(e\right) = s_{n-1}\right\}}\delta_{s_{n-1},s_{n}}Z_e\!\!\left(s_{n\!-\!1}\!,\!s_{n}\right)\\
    \quad - \omega_1\mathds{1}_{\left\{E_{\textrm{R}}\left(n\right)\leq 0\right\}}
    -\omega_2\mathds{1}_{\left\{T_{\textrm{R}}\left(n\right)\leq 0\right\}}, \ \ \ \text{if} \ 2 \leq n \leq S, \\
    -\!\!\sum\limits_{e \in \mathcal{E}}\!\!\mathds{1}_{\!\left\{\!\epsilon_{s_{2S\!-\!n\!+\!1},s_{2S\!-\!n}}\!\!\left(e\right)\! =\! s_{2S\!-\!n\!+\!1}\!\right\}}\!\delta_{s_{2S\!-\!n\!+\!1},s_{2S\!-\!n}}\!\!Z_e\!\!\left(\!s_{2S\!-\!n\!+\!1}\!,\! s_{2S\!-\!n}\!\right)\\
    \quad - \omega_1\mathds{1}_{\left\{E_{\textrm{R}}\left(n\right)\leq 0\right\}}
    -\omega_2\mathds{1}_{\left\{T_{\textrm{R}}\left(n\right)\leq 0\right\}}, \ \ \  \text{if} \ S < n \leq 2S\!-\!1,
\end{cases}
\end{aligned}
\end{equation}
where
$\mathds{1}_{\left\{E_{\textrm{R}}\left(n\right)\leq 0\right\}}$ and $\mathds{1}_{\left\{T_{\textrm{R}}\left(n\right)\leq 0\right\}}$ indicate whether the time and the energy used for SL model training and deceptive signal transmission meet the corresponding requirements in (\ref{eq:constraint_d}) and (\ref{eq:constraint_e}). Specifically, if they meet the requirements (i.e., the remaining energy and time are positive), $\mathds{1}_{\left\{E_{\textrm{R}}\left(n\right)\leq 0\right\}} = \mathds{1}_{\left\{T_{\textrm{R}}\left(n\right)\leq 0\right\}}=0$; otherwise, $\mathds{1}_{\left\{E_{\textrm{R}}\left(n\right)\leq 0\right\}} = \mathds{1}_{\left\{T_{\textrm{R}}\left(n\right)\leq 0\right\}}=1$; $\omega_1$ and $\omega_2$ are weight parameters that control the weight penalty in terms of the energy and the time;
$\mathds{1}_{\left\{\epsilon_{s_{n-1},s_{n}}\left(e\right) = s_{n-1}\right\}}\delta_{s_{n-1},s_{n}}Z_e\!\!\left(s_{n\!-\!1}\!,\!s_{n}\right)$ is the information leaked to eavesdropper $e$ during the model output transmission from device $\boldsymbol{\theta_1}$ to the server. The reason that $R_{\textrm{E}}\left(\boldsymbol{a}\left(0\right)|\boldsymbol{s}\left(0\right)\right) = 0$ is that the first step ($n=1$) only determines the device that will transmit the model output and the second step ($n=2$) determines the device that will receive the model output from the device determined in the first step.
$Z_e\left(s_{n-1},s_{n}\right)$ is the monitoring indicator and is expressed as
\begin{equation}
\begin{aligned}
    &Z_e\left(s_{n-1},s_{n}\right) \\&=
\begin{cases} 
1, & \!\!\!\!\text{if eavesdropper $e$  monitors the model transmission,} \\
0, & \!\!\!\!\text{otherwise.}
\end{cases}
\end{aligned}
\end{equation}
