\subsubsection{The reward function for unknown state exploration} The reward that captures the agent’s motivation to explore unknown states is
\begin{equation} \label{eq:reward_icm}
    R_{\textrm{C}}\!\!\left(\!\boldsymbol{s}\!\left(n\right), \boldsymbol{a}\!\left(n\right)\!\right) \!\!=\!\! \frac{1}{2}\! \left\| {\boldsymbol{\phi}}_{\boldsymbol{\theta}_{\textrm{E}}}\!\!\left(\boldsymbol{s}\left(n\!+\!1\right)\right) \!\!-\! \!\hat{\boldsymbol{\phi}}_{\boldsymbol{\theta}_{\textrm{F}}, \boldsymbol{\theta}_{\textrm{E}}}\!\!\left(\boldsymbol{s}\left(n\!+\!1\right)\right) \right\|_2^2\!,
\end{equation}
where $\|\cdot\|_2^2$ represents the squared Euclidean distance (L2 norm).
From (\ref{eq:reward_icm}), we see that, if the forward dynamic model cannot accurately predict the next state, it implies that the state $\boldsymbol{s}\left(n\right)$ is unknown and the reward $R_{\textrm{C}}\left(\boldsymbol{s}\left(n\right), \boldsymbol{a}\left(n\right)\right)$ is large. Hence, a large reward in (\ref{eq:reward_icm}) encourages the agent to explore unknown states, accelerating the efficiency of model training.

Given the definitions of two rewards, the total reward of the proposed RL method is
\begin{equation} \label{eq:reward_total}
    R\!\left(\boldsymbol{a}\left(n\right)|\boldsymbol{s}\left(n\right)\right)\! =\! R_{\textrm{E}}\!\left(\boldsymbol{a}\left(n\right)|\boldsymbol{s}\left(n\right)\right) \!+\! \zeta R_{\textrm{C}}\!\left(\boldsymbol{a}\left(n\right)|\boldsymbol{s}\left(n\right)\right),
\end{equation}
where $\zeta$ is a weight parameter.

\textbf{(6) Actor Network with Cross-Attention:}  
The actor network with a cross-attention mechanism is responsible for selecting actions based on the current state and past action-state pairs. Here, the cross-attention is used to generate a combined state $\boldsymbol{s}'(n)$ as follows:
\begin{equation} \label{eq:att_state}
\begin{aligned}
    \boldsymbol{s}'(n) &= X\left(\boldsymbol{s}\left(n\right), \boldsymbol{H}\right)
    = N \left(\frac{\boldsymbol{Q} \boldsymbol{K}^T}{\sqrt{C}}\right) \boldsymbol{V},
\end{aligned}
\end{equation}
where $\boldsymbol{H} = \left[(\boldsymbol{s}(n-1), \boldsymbol{a}(n-1));...; (\boldsymbol{s}(n-I), \boldsymbol{a}(n-I))\right]$ represents a vector including the last $I$ observed state-action pairs; \( \boldsymbol{Q} = \boldsymbol{W}_\textrm{Q} [\boldsymbol{s}(n); \boldsymbol{H}] \) is the query matrix derived from the current state and past state-action pairs; \( \boldsymbol{K} = \boldsymbol{W}_{\textrm{K}} \boldsymbol{H} \) and \( \boldsymbol{V} = \boldsymbol{W}_\textrm{V} \boldsymbol{H} \) represent the key and value matrices, which encode the past \( L \) state-action pairs in \( \boldsymbol{H} \). Here, \( \boldsymbol{W}_\textrm{Q}, \boldsymbol{W}_\textrm{K}, \boldsymbol{W}_\textrm{V} \) are learnable weight matrices, and \( C \) represents the dimensionality of the vectors in \( \boldsymbol{K} \) (i.e., the number of columns of \( \boldsymbol{K} \)).  
The actor network is approximated by an MLP with parameters \( \boldsymbol{\varphi} \). Its input is \( \boldsymbol{s}'(n) \) in (\ref{eq:att_state}) and its output is an action distribution vector $\boldsymbol{\pi}_{\boldsymbol{\varphi}}(\boldsymbol{s}'(n))$ that captures the likelihood of selecting each action.

\textbf{(7) Critic Network:}  
The critic network evaluates the state and provides a state value estimation for stable policy learning. The critic network takes the current state \( \boldsymbol{s}(n) \) as input and outputs the expected cumulative reward starting from \( \boldsymbol{s}(n) \) under the policy $\boldsymbol{\pi}_{\boldsymbol{\varphi}}(\boldsymbol{s}'(n))$. The critic network is approximated by a MLP neural network with parameters $\boldsymbol{\psi}$ and the critic network output is $V_{\boldsymbol{\psi}}^{\boldsymbol{\pi}_{\boldsymbol{\varphi}}}(\boldsymbol{s}(n))$.

\subsection{Training Process of the ICM-CA Method}

The training process of the ICM-CA method consists of the following steps.

\textbf{1) Data Collection:}
The agent observes eavesdroppers' activities, the remaining training model, time, and energy to collect experiences where each experience is represented by $(\boldsymbol{s}\left(n\right), \boldsymbol{a}\left(n\right), R\left(\boldsymbol{a}(n)|\boldsymbol{s}(n)\right), \boldsymbol{s}(n+1))$ and stores them in a replay buffer.

\textbf{2) ICM Update:}  
The ICM module update includes inverse dynamic model update, forward dynamic model update, and feature extractor update, which are specified as follows.

% \textbf{(i) Inverse Dynamic Model Update:}  
% The loss function used to update the inverse dynamic model is formulated as:
% \begin{equation} \label{eq:inv_loss}
%     L_{\textrm{I}}\left(\boldsymbol{\theta}_{\textrm{I}}, \boldsymbol{\theta}_{\textrm{E}}\right) = - \sum_{i=1}^{|\mathcal{A}_n|} B_i(n) \log \hat{P}_i(n),
% \end{equation}
% where \( \mathcal{A}_n \) is the set of all the possible actions at step $n$, and \( B_i(n) \) is a binary indicator representing whether the $i$-th action was chosen as $\boldsymbol{a}\left(n\right)$. Specifically, we have
% \begin{equation}
%     B_i(n) =
%     \begin{cases}
%         1, & \text{if the } i \text{-th action is chosen at step } n, \\
%         0, & \text{otherwise}.
%     \end{cases}
% \end{equation}
% Here, \( \hat{P}_i(n) \) represents the predicted probability of selecting the $i$-th action at step \( n \), which is output by the inverse dynamic model.

\textbf{(i) Inverse Dynamic Model Update:}  
The loss function used to update the inverse dynamic model is 
\begin{equation} \label{eq:inv_loss}
    L_{\textrm{I}}\left(\boldsymbol{\theta}_{\textrm{I}}, \boldsymbol{\theta}_{\textrm{E}}\right) = - \boldsymbol{b}(n)^T \log \hat{\boldsymbol{p}}_{\boldsymbol{\theta}_{\textrm{I}}, \boldsymbol{\theta}_{\textrm{E}}}\left(n\right),
\end{equation}
where \( \boldsymbol{b}(n)=\begin{bmatrix}
        b_1(n),
        b_2(n), 
        \ldots, 
        b_{|\mathcal{A}|}(n)
    \end{bmatrix}^T \) is a one-hot encoding vector that represents the action \( \boldsymbol{a}(n) \) selected at step \( n \)
with $\mathcal{A}$ being the set of all the actions and $|\mathcal{A}|$ is the number of actions in $\mathcal{A}$. In particular $b_i(n) = 1$ implies that action $i$ in $\mathcal{A}$ is selected by the agent; otherwise, $b_i(n) = 0$.
% \begin{equation}
%     b_i(n) =
%     \begin{cases}
%         1, & \text{if the } i \text{-th element in $\mathcal{A}_n$ is chosen as $\boldsymbol{a}(n)$}, \\
%         0, & \text{otherwise}.
%     \end{cases}
% \end{equation}
The inverse dynamic model parameters \( \boldsymbol{\theta}_{\textrm{I}} \) and the feature extractor \( \boldsymbol{\theta}_{\textrm{E}} \) are updated as
    $\boldsymbol{\theta}_{\textrm{I}} \leftarrow \boldsymbol{\theta}_{\textrm{I}} - \eta_1 \nabla_{\boldsymbol{\theta}_{\textrm{I}}} L_{\textrm{I}}\left(\boldsymbol{\theta}_{\textrm{I}}, \boldsymbol{\theta}_{\textrm{E}}\right)$
and
    $\boldsymbol{\theta}_{\textrm{E}} \leftarrow \boldsymbol{\theta}_{\textrm{E}} - \eta_1 \nabla_{\boldsymbol{\theta}_{\textrm{E}}} L_{\textrm{I}}\left(\boldsymbol{\theta}_{\textrm{I}}, \boldsymbol{\theta}_{\textrm{E}}\right)$,
where $\eta_1$ is the learning rate.

\textbf{(ii) Forward Dynamic Model Update:}  
Once the inverse dynamic model has been updated, the forward dynamic model updates its parameters to predict the feature representation of the next state. The loss function is
\begin{equation} \label{eq:fw_loss}
    L_{\textrm{F}}\!\left(\boldsymbol{\theta}_{\textrm{F}}, \boldsymbol{\theta}_{\textrm{E}}\right) \!=\! \frac{1}{2}\! \left\|\!\hat{{\boldsymbol{\phi}}}_{\boldsymbol{\theta}_{\textrm{F}}, \boldsymbol{\theta}_{\textrm{E}}}(\boldsymbol{s}(n+1))\! -\! {\boldsymbol{\phi}}_{\boldsymbol{\theta}_{\textrm{E}}}(\boldsymbol{s}(n+1))\!\right\|_2^2.
\end{equation}
The forward dynamic model parameters \( \boldsymbol{\theta}_{\textrm{F}} \) are updated as
    $\boldsymbol{\theta}_{\textrm{F}} \leftarrow \boldsymbol{\theta}_{\textrm{F}} - \eta_2 \nabla_{\boldsymbol{\theta}_{\textrm{F}}} L_{\textrm{F}}\left(\boldsymbol{\theta}_{\textrm{F}}, \boldsymbol{\theta}_{\textrm{E}}\right)$.

\textbf{(iii) Feature Extractor Update:}  
The feature extractor must be updated using a loss function that considers both the performance of both inverse dynamic model and forward dynamic model. The loss function is expressed as
\begin{equation} \label{eq:emb_loss}
    L_{\textrm{E}}\left(\boldsymbol{\theta}_{\textrm{E}}\right) = L_{\textrm{F}}\left(\boldsymbol{\theta}_{\textrm{F}}, \boldsymbol{\theta}_{\textrm{E}}\right) + \upsilon L_{\textrm{I}}\left(\boldsymbol{\theta}_{\textrm{I}}, \boldsymbol{\theta}_{\textrm{E}}\right),
\end{equation}
where \( \upsilon \) is the weight parameter. Then, the feature extractor parameters \( \boldsymbol{\theta}_{\textrm{E}} \) are updated as
    $\boldsymbol{\theta}_{\textrm{E}} \leftarrow \boldsymbol{\theta}_{\textrm{E}} - \eta_3 \nabla_{\boldsymbol{\theta}_{\textrm{E}}} L_{\textrm{E}}\left(\boldsymbol{\theta}_{\textrm{E}}\right)$.


\textbf{3) Critic Update:}  
The critic network is updated by reducing the difference between its predicted value of the current state and a reference value based on future rewards. The critic loss function is given by
\begin{equation} \label{eq:critic}
    L_{\textrm{C}}\!({\boldsymbol{\psi}})\!\! =\!\! \mathbb{E} \!\!\left[ \!(R\!\left(\boldsymbol{a}(n)|\boldsymbol{s}(n)\right)\! +\! \gamma V_{\boldsymbol{\psi}}^{\boldsymbol{\pi}_{\boldsymbol{\varphi}}}\!(\boldsymbol{s}(n+1))\!\! -\!\! V_{\boldsymbol{\psi}}^{\boldsymbol{\pi}_{\boldsymbol{\varphi}}}\!(\boldsymbol{s}\left(n\right)))^2\! \right]\!.
\end{equation}
Then, the parameters \( {\boldsymbol{\psi}} \) of the critic network are updated using gradient descent as
    ${\boldsymbol{\psi}} \leftarrow {\boldsymbol{\psi}} - \eta_c \nabla_{{\boldsymbol{\psi}}} L_{C}({\boldsymbol{\psi}})$,
where \( \eta_c \) is the learning rate.

\textbf{4) Actor Update:}  
The loss function used to update the actor network is
\begin{equation} \label{eq:actor}
    L_{\textrm{A}}({\boldsymbol{\varphi}})\! =\! -\!\mathbb{E}\! \left[ \log \pi_{\boldsymbol{\varphi}}\!(\boldsymbol{a}\left(n\right) | \boldsymbol{s}'\left(n\right)) Y_{\boldsymbol{\psi}}\!\left(n\right)\! -\! \alpha H\!\left(\boldsymbol{\pi}_{\boldsymbol{\varphi}}\!\!\left(s'(n)\right)\right) \right],
\end{equation}
where $\pi_{\boldsymbol{\varphi}}(\boldsymbol{a}\left(n\right) | \boldsymbol{s}'\left(n\right))$ is the probability of selecting action $\boldsymbol{a}(n)$ by the agent based on action distribution $\boldsymbol{\pi}_{\boldsymbol{\varphi}}\left(s'(n)\right)$; \( \alpha \) is the parameter that controls the balance between maximizing rewards and maintaining diversity in action selection; $Y_{\boldsymbol{\psi}}(\boldsymbol{a}(n), \boldsymbol{s}(n)) = R\left(\boldsymbol{a}(n)|\boldsymbol{s}(n)\right) + \gamma V_{\boldsymbol{\psi}}^{\boldsymbol{\pi}_{\boldsymbol{\varphi}}}(\boldsymbol{s}(n+1)) - V_{\boldsymbol{\psi}}^{\boldsymbol{\pi}_{\boldsymbol{\varphi}}}(\boldsymbol{s}\left(n\right))$ measures whether taking action $\boldsymbol{a}\left(n\right)$, which results in the change of the state from $\boldsymbol{s}(n)$ to $\boldsymbol{s}(n+1)$, can achieve a higher accumulated reward compare to the value of the current state $\boldsymbol{s}(n)$; $Y_{\boldsymbol{\psi}}(\boldsymbol{a}(n), \boldsymbol{s}(n) > 0$ implies that taking action $\boldsymbol{a}(n)$ leads to a higher estimated accumulated reward than staying in the current state $\boldsymbol{s}(n)$; otherwise, we have $Y_{\boldsymbol{\psi}}(\boldsymbol{a}(n), \boldsymbol{s}(n) \leq 0$; 
% The $Y_{\boldsymbol{\psi}}(\boldsymbol{a}(n), \boldsymbol{s}(n)$ is expressed as
% \begin{equation}
%     Y_{\boldsymbol{\psi}}(\boldsymbol{a}(n), \boldsymbol{s}(n)) = R\left(\boldsymbol{a}(n)|\boldsymbol{s}(n)\right) + \gamma V_{\boldsymbol{\psi}}^{\boldsymbol{\pi}_{\boldsymbol{\varphi}}}(\boldsymbol{s}(n+1)) - V_{\boldsymbol{\psi}}^{\boldsymbol{\pi}_{\boldsymbol{\varphi}}}(\boldsymbol{s}\left(n\right));
% \end{equation}
\( H\!\left(\boldsymbol{\pi}_{\boldsymbol{\varphi}}\left(s'(n)\right)\right) \) represents the entropy of the distribution $\boldsymbol{\pi}_{\boldsymbol{\varphi}}\left(s'(n)\right)$, which measures the uncertainty in action selection. 
The actor network parameters \( {\boldsymbol{\varphi}} \) are updated as
    ${\boldsymbol{\varphi}} \leftarrow {\boldsymbol{\varphi}} - \eta_a \nabla_{{\boldsymbol{\varphi}}} L_{\textrm{A}}({\boldsymbol{\varphi}})$,
where \( \eta_a \) is the learning rate. The detailed training process of ICM-CA is summarized in Algorithm \ref{alg:sac_icm_ca}.

\subsection{Convergence and Implementation Analysis}
Next, we analyze the convergence and implementation of the proposed ICM-CA method.

\subsubsection{Convergence analysis}
Here, we analyze the convergence of the proposed ICM-CA method. Since the proposed RL framework consists of a critic network $\boldsymbol{\psi}$ and an actor network $\boldsymbol{\varphi}$, we must analyze the convergence for both of them. Let \( V^{\pi_{\boldsymbol{\varphi}}}(\boldsymbol{s}(n)) \) be the actual value function, i.e., the expected cumulative reward starting from state \( \boldsymbol{s}(n) \) under policy \( \pi_{\boldsymbol{\varphi}} \). Then, the convergence of the critic network $\boldsymbol{\psi}$ is summarized in the following lemma.

\begin{lemma}
\label{lem:critic_converge}
If (i) the reward \( R(\boldsymbol{a}(n) | \boldsymbol{s}(n)) \) is bounded and (ii) the size of action space $\left|\mathcal{A}\right|$ is finite (i.e., $\left|\mathcal{A}\right| < \infty$), then the output of the critic network will converge to the actual value function \( V^{\pi_{\boldsymbol{\varphi}}}(\boldsymbol{s}(n)) \) \cite{haarnoja2018soft}.
\end{lemma}
\begin{proof}
In our designed algorithm, the reward $R_{\textrm{E}}\left(\boldsymbol{a}\left(n\right)|\boldsymbol{s}\left(n\right)\right)$ in (\ref{eq:reward_transmit}) is bounded since its maximum value is $0$; Its minimum value is $-\left|\mathcal{E}\right|\delta_{s_{n-1},s_{n}}-\omega_1-\omega_2$ if $n \leq S$ and $\left|\mathcal{E}\right|\delta_{s_{2S-n+1},s_{2S-n}}-\omega_1-\omega_2$ if $S <n \leq 2S - 1$. Meanwhile, since each element in 
${\boldsymbol{\phi}}_{\boldsymbol{\theta}_{\textrm{E}}}\!\!\left(\boldsymbol{s}\left(n\!+\!1\right)\right) $ or $ \hat{\boldsymbol{\phi}}_{\boldsymbol{\theta}_{\textrm{F}}, \boldsymbol{\theta}_{\textrm{E}}}\!\!\left(\boldsymbol{s}\left(n\!+\!1\right)\right)$ is between $0$ and $1$ \cite{pathak2017curiosity}, $R_{\textrm{C}}\left(\boldsymbol{a}\left(n\right)|\boldsymbol{s}\left(n\right)\right)$ in (\ref{eq:reward_icm}) is also bounded. Therefore, the reward function \( R(\boldsymbol{a}(n) | \boldsymbol{s}(n)) \) in (\ref{eq:reward_total}) is bounded and hence our designed RL meets the first condition. Next, we prove that the action space $\mathcal{A}$ is finite. In an action $\boldsymbol{a}(n)$, the device selection $\mathcal{S}$ and $\mathcal{D}$ is limited by the total number of devices in the system, the split model $\boldsymbol{\theta}_k$ depends on the total number of layers in the ML model, and the transmit power for each device is chosen from a predefined set of discrete levels. Therefore, the action space is also finite. Hence, both conditions in Lemma~\ref{lem:critic_converge} are satisfied. This completes the proof.
\end{proof}

\noindent When the critic network converges, the actor network is guaranteed to converge, as proved in ~\cite[Theorem~1]{haarnoja2018soft}.
