\begin{algorithm}[t]
\footnotesize
\caption{The ICM-CA Algorithm for Private SL}
\label{alg:sac_icm_ca}
\begin{algorithmic}[1]
    \STATE \textbf{Initialize:} Actor network $\boldsymbol{\pi}_{\boldsymbol{\varphi}}$, critic network $V_{\boldsymbol{\psi}}$, and replay buffer.

    \FOR{each episode}
        \FOR{each step $n = 1, 2, \dots, S$}
            \STATE \textbf{State Representation:} Compute the cross-attention-enhanced state representation $\boldsymbol{s}'\left(n\right)$ using (\ref{eq:att_state}).
            \STATE \textbf{Action Selection:} Sample action $\boldsymbol{a}\left(n\right) \sim \boldsymbol{\pi}_{\boldsymbol{\varphi}}(\boldsymbol{s}'\left(n\right))$.
            \STATE \textbf{Environment Interaction:} Execute action $\boldsymbol{a}\left(n\right)$ and observe next state $\boldsymbol{s}(n+1)$ and reward $R\left(\boldsymbol{a}(n)|\boldsymbol{s}(n)\right)$ using (\ref{eq:reward_total}).
            \STATE \textbf{Replay Buffer Update:} Observe and store each experience $(\boldsymbol{s}\left(n\right), \boldsymbol{a}\left(n\right), R\left(\boldsymbol{a}(n)|\boldsymbol{s}'(n)\right), \boldsymbol{s}(n+1))$ in replay buffer.

            \STATE \textbf{ICM Update:}
            \STATE \hspace{0.5cm} 1. Update inverse dynamic model and feature extractor.
            \STATE \hspace{0.5cm} 2. Update forward dynamic model.
            \STATE \hspace{0.5cm} 3. Update feature extractor with combined loss.

            \STATE \textbf{Critic and Actor Update:} 
            \STATE \hspace{0.5cm} 1. Update the critic network.
            \STATE \hspace{0.5cm} 2. Update the actor network.

        \ENDFOR
    \ENDFOR
\end{algorithmic}
\end{algorithm}



