\section{Performance Analysis}
Next, we analyze how the transmit powers of the model training and deceptive signal transmission devices affect the information leaked to the eavesdroppers. The analytical results can be used to simply the RL action space. It can also find the optimal transmit powers of the model training and deceptive signal transmission devices to minimize the expected amount of information leaked to eavesdroppers under two special network settings.
\begin{theorem}\label{the:1}
Given a model training device $s_k$ that transmits the output of model $\boldsymbol{\theta}_k$ to model training device $s_{k+1}$, the set $\mathcal{D}_{s_k, s_{k+1}}$ of deceptive signal transmission devices, and the probability $q_e^{(s_k,s_{k+1})}$ that eavesdropper $e \in \mathcal{E}$ monitors the model information transmitted by $s_k$, the expectation of the amount of information leaked to all eavesdroppers at this model output transmission is  
\begin{equation}
\begin{aligned}
    &\mathbb{E}\left(I_{s_k,s_{k+1}}\right) \\
    &=\!\!\!\sum_{e \in \mathcal{E}}\!\prod_{d \in \mathcal{D}_{s_k,s_{k+1}}}\!\!\!\!\!\frac{p_{s_k}m_{s_k,e}^{-2}}{p_{d}m_{d,e}^{-2}\!+\!p_{s_k}m_{s_k,e}^{-2}}q_e^{s_k,s_{k+1}} \delta_e^{s_k,s_{k+1}}\!\!\left(\boldsymbol{\theta}_k\right).
\end{aligned}
\end{equation}
\end{theorem}
\begin{proof}
See Appendix A.
\end{proof}
\noindent From Theorem \ref{the:1}, we see that $\mathbb{E}\left(I_{s_k,s_{k+1}}\right)$ depends on the locations and transmit powers of model training and deceptive signal transmission devices, the eavesdropping probability, and the size of the training model. 
From Theorem \ref{the:1}, we see that, when $p_{s_k} = 0$, $\mathbb{E}\left(I_{s_k,s_{k+1}}\right) = 0$. This is because no model information is transmitted between model training devices $s_k$ and $s_{k+1}$. When $p_{d} = + \infty$, we also have $\mathbb{E}\left(I_{s_k,s_{k+1}}\right) = 0$. This is due to the fact that the strength of deceptive signals is large enough to confuse eavesdroppers.
% When $p_{s_k} = + \infty$, $\mathbb{E}\left(I_{s_k,s_{k+1}}\right)$ has maximal value at $\mathbb{E}\left(I_{s_k,s_{k+1}}\right) = \sum_{e \in \mathcal{E}}\prod_{d \in \mathcal{D}_{s_k,s_{k+1}}}q_e^{s_k,s_{k+1}}\delta_e^{s_k,s_{k+1}}\left(\boldsymbol{\theta}_k\right)$. This implies that that eavesdroppers can always distinguish and capture the model training information.
Using Theorem \ref{the:1}, we can obtain the optimal transmit powers $p_{s_k}^*$ and $p_d^*, \forall d \in \mathcal{D}_{s_k,s_{k+1}}$ under the following two network scenarios: 1) a network has one deceptive signal device (i.e., $\left|\mathcal{D}_{s_k,s_{k+1}}\right| = 1$) and 2) a network has one eavesdropper (i.e., $\left|\mathcal{E}\right| = 1$) with the assumption that the interference among the deceptive signals is ignored. These optimal powers are analyzed in the following corollary.
\begin{corollary} \label{col:1}
    Consider a network where a model training device $s_k$ that transmits the output of model $\boldsymbol{\theta}_k$ to model training device $s_{k+1}$ with 1) the time constraint $B_{\textrm{T}}$ and the energy constraint $B_{\textrm{E}}$, 2) one deceptive signal transmission device (i.e., $\left|\mathcal{D}_{s_k,s_{k+1}}\right|=1$), and 3) $\left|\mathcal{E}\right|$ eavesdroppers, the optimal transmit powers of model training and the deceptive signal transmission device that can minimize $\mathbb{E}\left(I_{s_k,s_{k+1}}\right)$ are
    \begin{equation} \label{eq:col1_final}
    \begin{aligned}
        p_{s_k}^* &= \frac{BN_0 + {m^{-2}_{s_k,d}o}\frac{B_{\textrm{E}}}{B_{\textrm{T}}}}{m^{-2}_{s_k,s_{k+1}}o \, / \left(2^{\frac{\Gamma\left(\boldsymbol{z}_k\right)}{B_{\textrm{T}}B}}-1\right) + {m^{-2}_{s_k,d}o}}, \\
        p_d^* &= \frac{m^{-2}_{s_k,s_{k+1}}o\frac{B_{\textrm{E}}}{B_{\textrm{T}}} - BN_0\left(2^{\frac{\Gamma\left(\boldsymbol{z}_k\right)}{B_{\textrm{T}}B}}-1\right)}{m^{-2}_{s_k,s_{k+1}}o + {m^{-2}_{s_k,d}o}{\left(2^{\frac{\Gamma\left(\boldsymbol{z}_k\right)}{B_{\textrm{T}}B}}-1\right)}},
    \end{aligned}
    \end{equation}
    % where $\xi_0=m^{-2}_{s_k,s_{k+1}}o$, $\xi_d = {m^{-2}_{s_k,d}o}{\left(2^{\frac{\Gamma\left(\boldsymbol{z}_k\right)}{B_{\textrm{T}}B}}-1\right)}$, $\chi_1=BN_0\left(2^{\frac{\Gamma\left(\boldsymbol{z}_k\right)}{B_{\textrm{T}}B}}-1\right)$, and $\chi_2 = \frac{B_{\textrm{E}}}{B_{\textrm{T}}}$.
\end{corollary}
\begin{proof}
See Appendix B.
\end{proof}
From Corollary \ref{col:1}, we see that, to guarantee $p_d^* > 0$, $B_{\textrm{T}}$ and $B_{\textrm{E}}$ must satisfy $m^{-2}_{s_k,s_{k+1}}o\frac{B_{\textrm{E}}}{B_{\textrm{T}}} - BN_0\left(2^{\frac{\Gamma\left(\boldsymbol{z}_k\right)}{B_{\textrm{T}}B}}-1\right) > 0$. For example, if $B_{\textrm{E}} = 0$, $m^{-2}_{s_k,s_{k+1}}o\frac{B_{\textrm{E}}}{B_{\textrm{T}}} - BN_0\left(2^{\frac{\Gamma\left(\boldsymbol{z}_k\right)}{B_{\textrm{T}}B}}-1\right) < 0$. Hence, we cannot find a valid $p_d^*$ to satisfy time and energy constraints (\ref{eq:col_1_mini_ini_c1}) and (\ref{eq:col_1_mini_ini_c2}). 

The optimal powers of model training and deceptive signal transmission devices under the network with one eavesdropper are given in the following corollary.
\begin{corollary} \label{col:2}
    Consider a scenario where a model training device $s_k$ that transmits the output of model $\boldsymbol{\theta}_k$ to model training device $s_{k+1}$ with 1) the time constraint $B_{\textrm{T}}$ and the energy constraint $B_{\textrm{E}}$, 2) the ignorance of the interference from deceptive signal transmission devices, 3) $\left|\mathcal{D}_{s_k,s_{k+1}}\right|$ deceptive signal transmission devices, and 4) one eavesdropper (i.e., $\left|\mathcal{E}\right| = 1$), the optimal transmit powers of model training and deceptive signal transmission devices that can minimize $\mathbb{E}\left(I_{s_k,s_{k+1}}\right)$ are
\begin{equation} \label{eq:col2_final}
\begin{aligned}
    p_{s_k}^* &= \frac{BN_0\left(2^{\frac{\Gamma\left(\boldsymbol{z}_k\right)}{B_{\textrm{T}}B}}-1\right)}{m^{-2}_{s_k,s_{k+1}}o},\\
    p_d^* &= \frac{m^{-2}_{s_k,s_{k+1}}o\frac{B_{\textrm{E}}}{B_{\textrm{T}}}-BN_0\left(2^{\frac{\Gamma\left(\boldsymbol{z}_k\right)}{B_{\textrm{T}}B}}-1\right)}{m^{-2}_{s_k,s_{k+1}}om_{d,e}^{-2}\sum_{d \in \mathcal{D}_{s_k, s_{k+1}}}m_{d,e}^2}, \forall d \in \mathcal{D}_{s_k,s_{k+1}},
\end{aligned}
\end{equation}
% where $y = \frac{\chi_1m_{s_k,e}^{-2}\sum_{d \in \mathcal{D}_{s_k, s_{k+1}}}m_{d,e}^2}{\chi_1m_{s_k,e}^{-2}\sum_{d \in \mathcal{D}_{s_k, s_{k+1}}}m_{d,e}^2+\xi_0\chi_2-\chi_1}.$
\end{corollary}
\begin{proof}
    See Appendix C.
\end{proof}
From Corollary \ref{col:2}, we see that, $p_{s_k}^*$ only relies on $B_{\textrm{T}}$ and will decrease if $B_{\textrm{T}}$ increases, and $p_d^*$ will increase if $B_{\textrm{E}}$ increases. This is because a longer transmission time allows the model training device to use lower power, and a larger energy constraint enables deceptive devices to allocate more power to generate interference, thus reducing the amount of information leaked to eavesdroppers while ensuring transmission efficiency.
For other scenarios, the closed-form solutions are not available.

