\subsection{Proof of Theorem \textnormal{\ref{the:1}}}

To prove Theorem \ref{the:1}, we must calculate the probability $\mathbb{P}\left(\epsilon_{s_k,s_k+1}\left(e\right)=s_k\right)$ that eavesdropper $e$ monitors the information from model training device 
$s_k$. Let $S_{d,e} = p_{d} o m_{d,e}^{-2}$ and $S_{s_k,e} = p_{s_k} o m_{s_k,e}^{-2}$. From (\ref{eq:arg_snr}), we see that $\epsilon_{s_k,s_k+1}\left(e\right)=s_k$ only when $\frac{S_{d,e}}{BN_0}<\frac{S_{s_k,e}}{BN_0}, \forall d \in \mathcal{D}_{s_k,s_{k+1}}$. Hence, $\mathbb{P}\left(\epsilon_{s_k,s_k+1}\left(e\right)=s_k\right)$ is
\begin{equation} \label{eq:p1}
    \begin{aligned}
    \mathbb{P}\left(\epsilon_{s_k,s_k+1}\left(e\right)=s_k\right) &= \!\!\!\!\prod_{d \in \mathcal{D}_{s_k,s_{k+1}}}\!\!\!\!\!\!\!\mathbb{P}\left(\frac{S_{d,e}}{BN_0}<\frac{S_{s_k,e}}{BN_0}\right).
\end{aligned}
\end{equation}
Since $\prod_{d \in \mathcal{D}_{s_k,s_{k+1}}}\!\!\!\!\!\!\!\mathbb{P}\left(\frac{S_{d,e}}{BN_0}\!<\!\frac{S_{s_k,e}}{BN_0}\right)\!\!=\!\!\prod_{d \in \mathcal{D}_{s_k,s_{k+1}}}\!\!\!\!\!\!\mathbb{P}\!\left(S_{d,e}\!\!<\!S_{s_k,e}\right)$, we compute $\mathbb{P}\left(S_{d,e}\!\!<\!\!S_{s_k,e}\right)$. Since $S_{d,e}$ and $S_{s_k,e}$ follow exponential distributions with mean $2\!\left(p_d m_{d,e}^{-2} \sigma^2\right)$ and $2\left(p_{s_k} m_{s_k,e}^{-2} \sigma^2\right)$, where $\sigma^2$ is the channel fading variance, the probability density functions (PDF) of $S_{d,e}$ and $S_{s_k,e}$ are:
\begin{equation} \label{eq:pdf}
\begin{aligned}
    f_{S_{d,e}}(s) &= \frac{s}{(C_{d,e} \sigma)^2} e^{-s^2 / (2 (C_d \sigma)^2)}, \quad s \geq 0,\\
    f_{S_{s_k,e}}(s) &= \frac{s}{(C_{s_k,e} \sigma)^2} e^{-s^2 / (2 (C_{s_k} \sigma)^2)}, \quad s \geq 0,
\end{aligned}
\end{equation}
where \( C_{i,e} = p_i m_{i,e}^{-2} \).
Based on $f_{S_{d,e}}(s)$ in (\ref{eq:pdf}), the cumulative distribution functions (CDF) of $S_{d, e}$ is
$F_{S_{d,e}}(s) = 1 - e^{-s^2 / (2 (C_{d,e} \sigma)^2)}$.
Then, the probability $\mathbb{P}\left(S_{d, e} < S_{s_k,e}\right)$ is
% \begin{equation} \label{eq:prob}
%     \mathbb{P}\left(S_{d, e} < S_{s_k,e}\right) = \int_0^\infty \mathbb{P}(S_{d,e} < s_{s_k,e}) f_{S_{s_k,e}}(s_{s_k,e}) ds_{s_k,e},
% \end{equation}
\begin{equation} \label{eq:inte_ini}
\begin{aligned}
    &\mathbb{P}(S_{d,e} < S_{s_k,e})\\ &= \int_0^\infty \mathbb{P}(S_{d,e} < s_{s_k,e}) f_{S_{s_k,e}}(s_{s_k,e}) ds_{s_k,e}\\
    &= \int_0^\infty F_{S_{d,e}}(s_{s_k,e})
     \frac{s_{s_k,e}}{(C_{s_k,e} \sigma)^2} e^{-s_{s_k,e}^2 / (2 (C_{s_k,e} \sigma)^2)} ds_{s_k,e} \\
    &=\!\!\! \int_0^\infty \!\!\!\!\left(\!1\!\! -\!\! e\!\!^{-s_{s_k,e}^2 / (2 (C_{d,e} \sigma)^2)}\!\right)\!\!\frac{s_{s_k,e}}{(C_{s_k,e} \sigma)^2}\! e\!^{-s_{s_k,e}^2 / (2 (C_{s_k,e} \sigma)^2)} \!ds_{s_k,e}\\
    &= \int_0^\infty \frac{s_{s_k,e}}{(C_{s_k,e} \sigma)^2} e^{-s_{s_k,e}^2 / (2 (C_{s_k,e} \sigma)^2)} ds_{s_k,e} \\
    &\quad-\!\! \int_0^\infty\!\!\! \frac{s_{s_k,e}}{(C_{s_k,e} \sigma)^2} e^{-s_{s_k,e}^2 \left(\frac{1}{2 (C_{s_k,e} \sigma)^2} + \frac{1}{2 (C_{d,e} \sigma)^2}\right)} ds_{s_k,e}.
\end{aligned}
\end{equation}
Since $\int_0^\infty x e^{-a x^2} dx = \frac{1}{2a}, \quad \forall a > 0$ \cite{zinn2021quantum}, (\ref{eq:inte_ini}) can be rewritten as
\begin{equation} \label{eq:final_P}
\begin{aligned}
    \mathbb{P}(S_{d,e}\! <\! S_{s_k,e}) \!=\!1-\frac{C_{d,e}^2}{C_{d,e}^2 + C_{s_k,e}^2}\!=\! \frac{p_{s_k}m_{s_k,e}^{-2}}{p_{d}m_{t_1,r}^{-2}+p_{s_k}m_{s_k,e}^{-2}}.
\end{aligned}
\end{equation}
Substituting (\ref{eq:final_P}) into (\ref{eq:p1}), we have
\begin{equation}
\begin{aligned}
    \mathbb{P}\left(\epsilon_{s_k,s_k+1}\left(e\right)=s_k\right) 
    &=\!\!\!\!\!\!\! \prod_{d \in \mathcal{D}_{s_k,s_{k+1}}}\!\!\frac{p_{s_k}m_{s_k,e}^{-2}}{p_{d}m_{d,e}^{-2}+p_{s_k}m_{s_k,e}^{-2}}.
\end{aligned}
\end{equation}
Hence, the expectation of the total amount of information leaked to all eavesdroppers is
\begin{equation}
\begin{aligned}
    &\mathbb{E}\left(I_{s_k,s_{k+1}}\right) = \sum_{e \in \mathcal{E}}\mathbb{P}\left(\epsilon_{s_k,s_k+1}\left(e\right)=s_k\right)q_e^{s_k,s_{k+1}} \delta_e^{s_k,s_{k+1}}\left(\boldsymbol{\theta}_k\right) \\
    &=\!\!\sum_{e \in \mathcal{E}}\!\prod_{d \in \mathcal{D}_{s_k,s_{k+1}}}\!\!\!\!\!\frac{p_{s_k}m_{s_k,e}^{-2}}{p_{d}m_{d,e}^{-2}\!+\!p_{s_k}m_{s_k,e}^{-2}}q_e^{s_k,s_{k+1}} \delta_e^{s_k,s_{k+1}}\!\!\left(\boldsymbol{\theta}_k\right).
\end{aligned}
\end{equation}
This completes the proof. \qed

\subsection{Proof of Corollary \ref{col:1}}
To find the optimal $p_{s_k}^*$ and $p_d^*$ to minimize $\mathbb{E}\left(I_{s_k,s_{k+1}}\right)$, we have the following minimization problem
\begin{equation} \label{eq:col_1_mini_ini}
    \min_{\substack{p_{s_k}, p_d}} \quad \sum_{e\in\mathcal{E}} \frac{p_{s_k}\, m_{s_k,e}^{-2}}{p_d\, m_{d,e}^{-2} + p_{s_k}\, m_{s_k,e}^{-2}}q_e^{s_k,s_{k+1}}\delta_e^{s_k,s_{k+1}}\left(\boldsymbol{\theta}_k\right),
\end{equation}
\vspace{-0.5cm}
\begin{align}
    \text{s.t.} \quad & T_{s_k,s_{k+1}}^{\textrm{S}}=\frac{\Gamma\left(\boldsymbol{z}_k\right)}{c_{s_k, s_{k+1}}} \leq B_{\textrm{T}}, \tag{39a} \label{eq:col_1_mini_ini_c1} \\
    & \left(p_{s_k}+p_d\right)T_{s_k,s_{k+1}} \leq B_{\textrm{E}}. \tag{39b} \label{eq:col_1_mini_ini_c2}
\end{align}
% where $K_e = q_e^{s_k,s_{k+1}}\delta_e^{s_k,s_{k+1}}\left(\boldsymbol{\theta}_k\right)$.
Given the data rate $c_{s_k, s_{k+1}}$ in (\ref{eq:data_rate}), (\ref{eq:col_1_mini_ini_c1}) can be written as
\begin{equation} \label{eq:col_1_t2}
    \frac{p_{s_k}m^{-2}_{s_k,s_{k+1}}o}{p_dm_{s_k,d}^{-2}o+BN_0}\geq 2^{\frac{\Gamma\left(\boldsymbol{z}_k\right)}{B_{\textrm{T}}B}}-1.
\end{equation}
Therefore, (\ref{eq:col_1_t2}) can be simplified as
$\xi_0p_{s_k} - \xi_dp_d \geq \chi_1$,
where $\xi_0=m^{-2}_{s_k,s_{k+1}}o$, $\xi_d = {m^{-2}_{s_k,d}o}{\left(2^{\frac{\Gamma\left(\boldsymbol{z}_k\right)}{B_{\textrm{T}}B}}-1\right)}$, and $\chi_1=BN_0\left(2^{\frac{\Gamma\left(\boldsymbol{z}_k\right)}{B_{\textrm{T}}B}}-1\right)$.
From Theorem \ref{the:1}, we see that $\mathbb{E}\left(I_{s_k,s_{k+1}}\right)$ is a monotonically increasing function of $p_{s_k}$ and a decreasing function of $p_d$. Hence, $p_{s_k}^*$ and $p_d^*$ must satisfy the following equations:
\begin{equation} \label{eq:col_1_cst}
    \xi_0p_{s_k}^* - \xi_dp_d^* = \chi_1, \quad p_{s_k}^*+p_d^* = \chi_2,
\end{equation}
where $\chi_2 = \frac{B_{\textrm{E}}}{B_{\textrm{T}}}$.
From (\ref{eq:col_1_cst}), $p_{s_k}^*$ and $p_d^*$ can be derived as
\begin{equation} \label{eq:col_1_sv1}
    p_{s_k}^* = \frac{\chi_1 + \xi_d\chi_2}{\xi_0 + \xi_d}, \quad p_d^* = \frac{\xi_0\chi_2 - \chi_1}{\xi_0 + \xi_d}.
\end{equation}
This completes the proof. \qed

\subsection{Proof of Corollary \ref{col:2}}
To find the optimal $p_{s_k}^*$ and $p_d^*, \forall d \in \mathcal{D}_{s_k,s_{k+1}}$,  we have the following minimization problem
\begin{equation} \label{eq:col_2_mini_ini}
    \min_{\substack{p_{s_k}, p_d}} \quad q_e^{s_k,s_{k+1}}\delta_e^{s_k,s_{k+1}}\left(\boldsymbol{\theta}_k\right) \!\!\!\!\!\!\! \prod_{d \in \mathcal{D}_{s_k, s_{k+1}}}\!\!\!\!\! \left(\frac{p_{s_k}\, m_{s_k,e}^{-2}}{p_d\, m_{d,e}^{-2} + p_{s_k}\, m_{s_k,e}^{-2}}\right),
\end{equation}
\vspace{-0.5cm}
\begin{align}
    \text{s.t.} \quad & T_{s_k,s_{k+1}}^{\textrm{S}}=\frac{\Gamma\left(\boldsymbol{z}_k\right)}{c_{s_k, s_{k+1}}} \leq B_{\textrm{T}}, \tag{43a} \label{eq:col_2_mini_ini_c1} \\
    & \left(p_{s_k}+\!\!\!\!\sum_{d \in \mathcal{D}_{s_k,s_{k+1}}}\!\!\!\!p_d\right)T_{s_k,s_{k+1}} \leq B_{\textrm{E}}, \tag{43b} \label{eq:col_2_mini_ini_c2}
\end{align}
With the assumption in Corollary \ref{col:1}, (\ref{eq:col_1_mini_ini_c1}) can be written as
\begin{equation} \label{eq:col_2_t1}
    \frac{p_{s_k}m^{-2}_{s_k,s_{k+1}}o}{BN_0}\geq 2^{\frac{\Gamma\left(\boldsymbol{z}_k\right)}{B_{\textrm{T}}B}}-1.
\end{equation}
Therefore, (\ref{eq:col_2_t1}) can be simplified as $\xi_0 p_{s_k} \geq \chi_1$.
As $\mathbb{E}\left(I_{s_k,s_{k+1}}\right)$ is a monotonically increasing function of $p_{s_k}$ and a decreasing function of $p_d$, $p_{s_k}^*$ and $p_d^*$ must satisfy
\begin{equation} \label{eq:col_2_cst}
    \xi_0p_{s_k}^* = \chi_1, \quad p_{s_k}^*+\!\!\!\!\sum_{d \in \mathcal{D}_{s_k, s_{k+1}}}\!\!\!\! p_d^* = \chi_2.
\end{equation}
From (\ref{eq:col_2_cst}), we have $p_{s_k}^* = \frac{\chi_1}{\xi_0}$, and
$\sum_{d \in \mathcal{D}_{s_k, s_{k+1}}}\!\!\!\! p_d^* = \chi_2-\frac{\chi_1}{\xi_0}.$
% To minimize $\mathbb{E}\left(I_{s_k,s_{k+1}}\right)$, we have
% \begin{equation} \label{eq:col_2_mini_2}
% \begin{aligned}
%     &\mathbb{E}\left(I_{s_k,s_{k+1}}\right)\\ &= q_e^{s_k,s_{k+1}}\delta_e^{s_k,s_{k+1}}\left(\boldsymbol{\theta}_k\right)\!\!\!\!\!\! \prod_{d \in \mathcal{D}_{s_k, s_{k+1}}}\!\!\!\!\!\!\!\!\left(\frac{\frac{\chi_1}{\xi_0}m_{s_k,e}^{-2}}{p_dm_{d,e}^{-2}+\frac{\chi_1}{\xi_0}m_{s_k,e}^{-2}}\right)\\
%     &=q_e^{s_k,s_{k+1}}\delta_e^{s_k,s_{k+1}}\left(\boldsymbol{\theta}_k\right)\!\!\!\!\!\! \prod_{d \in \mathcal{D}_{s_k, s_{k+1}}}\!\!\!\!y_d \\
%     &\overset{(a)}{\geq} q_e^{s_k,s_{k+1}}\delta_e^{s_k,s_{k+1}}\left(\boldsymbol{\theta}_k\right)\, y^{\left|\mathcal{D}_{s_k,s_{k+1}}\right|},
% \end{aligned}
% \end{equation}
% where $y_d = \frac{\frac{\chi_1}{\xi_0}m_{s_k,e}^{-2}}{p_dm_{d,e}^{-2}+\frac{\chi_1}{\xi_0}m_{s_k,e}^{-2}}, \forall d \in \mathcal{D}_{s_k,s_{k+1}}$; (a) stems from the AM-GM equality that the objective function is minimized when all the $y_d$ are equal (i.e., $y_d = y, \forall d \in \mathcal{D}_{s_k, s_{k+1}}$), given the constraint on the sum of $p_d$ in (\ref{eq:col_2_mini_c2_1}). Hence, the optimal $p_d^*$ can be solved as
% \begin{equation} \label{eq:col_2_pd}
%     p_d^* = \frac{\chi_1m_{s_k,e}^{-2}(1-y)}{\xi_0m_{d,e}^{-2}y}.
% \end{equation}
% where $y$ is solved by substituting (\ref{eq:col_2_pd}) into (\ref{eq:col_2_mini_c2_1}), which is given by
% \begin{equation} \label{eq:col_2_q}
%     y = \frac{\chi_1m_{s_k,e}^{-2}\sum_{d \in \mathcal{D}_{s_k, s_{k+1}}}m_{d,e}^2}{\chi_1m_{s_k,e}^{-2}\sum_{d \in \mathcal{D}_{s_k, s_{k+1}}}m_{d,e}^2+\xi_0\chi_2-\chi_1}.
% \end{equation}
% This completes the proof. \qed
Hence, the minimization problem (\ref{eq:col_2_mini_ini}) can be rewritten as
\begin{equation} \label{eq:col_2_sim}
    \min_{\{p_d\}} \quad q_e^{s_k,s_{k+1}}\delta_e^{s_k,s_{k+1}}\left(\boldsymbol{\theta}_k\right) \!\!\!\!\!\!\!\prod_{d \in \mathcal{D}_{s_k,s_{k+1}}}\!\!\! \frac{\frac{\chi_1}{\xi_0} m_{s_k,e}^{-2}}{p_d m_{d,e}^{-2} + \frac{\chi_1}{\xi_0} m_{s_k,e}^{-2}}.
\end{equation}
\vspace{-0.4cm}
\begin{align}
    \text{s.t.} \quad &
    \sum_{d \in \mathcal{D}_{s_k, s_{k+1}}} p_d = \chi_2 - \frac{\chi_1}{\xi_0}. \label{eq:lcol_2_sim_c1} \tag{46a}
\end{align}
Since $\frac{\frac{\chi_1}{\xi_0} m_{s_k,e}^{-2}}{p_d m_{d,e}^{-2} + \frac{\chi_1}{\xi_0} m_{s_k,e}^{-2}}, \forall d \in \mathcal{D}_{s_k,s_{k+1}}$ is a strictly decreasing function of $p_d$, $\mathbb{E}\left(I_{s_k,s_{k+1}}\right)$ is minimized when all $\frac{\frac{\chi_1}{\xi_0} m_{s_k,e}^{-2}}{p_d m_{d,e}^{-2} + \frac{\chi_1}{\xi_0} m_{s_k,e}^{-2}}, \forall d \in \mathcal{D}_{s_k,s_{k+1}}$ are equal \cite{boyd2004convex}. Let
\begin{equation}
    y_d = \frac{\frac{\chi_1}{\xi_0} m_{s_k,e}^{-2}}{p_d^* m_{d,e}^{-2} + \frac{\chi_1}{\xi_0} m_{s_k,e}^{-2}}= y, \quad \forall d \in \mathcal{D}_{s_k, s_{k+1}} .
\end{equation}
We have
\begin{equation} \label{eq:pd*}
    p_d^* = {\chi_1 m_{s_k,e}^{-2}(1 - y)}/{\xi_0 m_{d,e}^{-2} y}.
\end{equation}
Substituting (\ref{eq:pd*}) into constraint (\ref{eq:lcol_2_sim_c1}), we have
\begin{equation} \label{eq:y}
    y = \frac{\chi_1 m_{s_k,e}^{-2} \sum_{d \in \mathcal{D}_{s_k,s_{k+1}}} m_{d,e}^2}{\chi_1 m_{s_k,e}^{-2} \sum_{d \in \mathcal{D}_{s_k,s_{k+1}}} m_{d,e}^2 + \xi_0 \chi_2 - \chi_1}.
\end{equation}
Substituting (\ref{eq:y}) into (\ref{eq:pd*}), we have
\begin{equation}
    p_d^* = \frac{m^{-2}_{s_k,s_{k+1}}o\frac{B_{\textrm{E}}}{B_{\textrm{T}}}-BN_0\left(2^{\frac{\Gamma\left(\boldsymbol{z}_k\right)}{B_{\textrm{T}}B}}-1\right)}{m^{-2}_{s_k,s_{k+1}}om_{d,e}^{-2}\sum_{d \in \mathcal{D}_{s_k, s_{k+1}}}m_{d,e}^2}.
\end{equation}
This completes the proof. \qed

