\section{Derivatives}
\label{app_deriv}
For a computationally efficient implicit numerical integration, Abaqus requires the definition of several derivatives in the CREEP subroutine. These derivatives are named DECRA and DESWA representing derivatives of $\Delta\Bar{\epsilon}^{cr}$ and $\Delta\Bar{\epsilon}^{sw}$. The relevant derivatives for the present implementation are defined below,

\begin{equation}\label{eq:A1}
    \frac{\partial{\Delta\Bar{\epsilon}^{cr}}}{\partial{\Bar{\epsilon}^{sw}}} = A(T)\frac{\partial{c(\RD)}}{\partial{\Bar{\epsilon}^{sw}}}\sigma_{eqv}^{{N(T)-1}}q + A(T)c(\RD)(N-1)\sigma_{eqv}^{{N(T)-2}}\frac{\partial{\sigma_{eqv}}}{\partial{\Bar{\epsilon}^{sw}}}q
\end{equation}

\begin{equation}
    \frac{\partial{\Delta\Bar{\epsilon}^{cr}}}{\partial{p}} = A(T)\frac{\partial{c(\RD)}}{\partial{p}}\sigma_{eqv}^{{N(T)-1}}q + A(T)c(\RD)(N-1)\sigma_{eqv}^{{N(T)-2}}\frac{\partial{\sigma_{eqv}}}{\partial{p}}q
\end{equation}

\begin{equation}
    \frac{\partial{\Delta\Bar{\epsilon}^{cr}}}{\partial{q}} = A(T)c(\RD)\sigma_{eqv}^{{N(T)-1}} + A(T)c(\RD)(N-1)\sigma_{eqv}^{{N(T)-2}}\frac{\partial{\sigma_{eqv}}}{\partial{q}}q
\end{equation}

\begin{equation}
    \frac{\partial{\Delta\Bar{\epsilon}^{sw}}}{\partial{\Bar{\epsilon}^{sw}}} = -9A(T)\left[\frac{\partial{f(\RD)}}{\partial{\Bar{\epsilon}^{sw}}}\sigma_{eqv}^{{N(T)-1}}p
         + f(\RD)(N-1)\sigma_{eqv}^{{N(T)-2}}\frac{\partial{\sigma_{eqv}}}{\partial{\Bar{\epsilon}^{sw}}}p\right]
\end{equation}

\begin{equation}
    \frac{\partial{\Delta\Bar{\epsilon}^{sw}}}{\partial{p}} = -9A(T)\left[\frac{\partial{f(\RD)}}{\partial{p}}\sigma_{eqv}^{{N(T)-1}}p
         + f(\RD)(N-1)\sigma_{eqv}^{{N(T)-2}}\frac{\partial{\sigma_{eqv}}}{\partial{p}}p + f(\RD)\sigma_{eqv}^{{N(T)-1}}\right]
\end{equation}

\begin{equation}\label{eq:A6}
    \frac{\partial{\Delta\Bar{\epsilon}^{sw}}}{\partial{q}} = -9A(T)f(\RD)(N-1)\sigma_{eqv}^{{N(T)-2}}\frac{\partial{\sigma_{eqv}}}{\partial{q}}p
\end{equation}

\noindent All the quantities used in the Eqs. (\ref{eq:A1})-(\ref{eq:A6}) are defined in the constitutive model (Section \ref{contmodel}). The derivatives $\sigma_{eqv}$ appearing in Eqs. (\ref{eq:A1})-(\ref{eq:A6}) can be obtained using Eq. (\ref{eq:eqStressCr}). The derivatives of $c(\RD)$ and $f(\RD)$ with respect to $\RD$ are numerically computed from the calibration data using linear interpolation.

