\section{Proof of \texorpdfstring{\Cref{thm:MAIN1}}{Theorem~\ref{thm:MAIN1}}}

In this section we provide  an overview of the proof of \Cref{thm:MAIN1}. Each main step 
is formulated as a separate proposition, accompanied by a brief proof sketch. Complete proofs are presented in detail in Appendix~\ref{app:theorem1}.



The first step of the proof of \Cref{thm:MAIN1} consists of showing that constructibly differentiably algebraic (CDA) power series coincide with rationally dynamically algebraic (RDA) power series. Recall that a RDA power series $f(x)$ arises as the first component of a solution $(y_1(x),\ldots,y_k(x))$ of a system of differential equations
\begin{gather}
y_1'=\frac{P_1(y_1,\ldots,y_k)}{Q_1(y_1,\ldots,y_k)}, \, \ldots, \, y'_k=\frac{P_k(y_1,\ldots,y_k)}{Q_k(y_1,\ldots,y_k)},
\label{eq:RDS}
\end{gather}
where $P_1, Q_1,\ldots,P_k,Q_k \in \K[x,y_1,\ldots,y_k]$ are polynomial functions with $Q_1,\ldots,Q_k$ defined at $(0,y_1(0),\ldots,y_k(0))$.
% and $f(x) = y_1(x)$.
 A power series is CDA when $Q_1 = \ldots = Q_k = 1$.
The CDA power series are thus RDA power series by definition. The converse is given by the following proposition.

%%
%%% Proposition
%%


\begin{restatable}{proposition}{propRDAimpliesCDA}
\label{prop:RDA implies CDA}
The class of  RDA and CDA power series coincide.
\end{restatable}

\begin{proof}[Proof sketch]
Our aim is to  transform the system shown in~\eqref{eq:RDS} into an equivalent one in which all denominators are constant.  To this end 
we introduce  new variables 
$z_i$, for all $i \in \{1, \ldots, k\}$,  with the equations \[ z_i = \frac{1}{Q_i(y_1,\ldots,y_k)} \quad\text{and}\quad y'_i = P_i(y_1,\ldots,y_k) z_i\,.\]  Differentiating these equations leads to \[ z'_i = -z_i^2 \sum_{j=1}^k \frac{\partial Q_i}{\partial y_j} y'_j = -z_i^2 \sum_{j=1}^k \frac{\partial Q_i}{\partial y_j} P_j(y_1,\ldots,y_k) z_j\,.\]
But $\frac{\partial Q_i}{\partial y_j} $ is also a polynomial $\K[x,y_1,\ldots,y_k]$,  which concludes the proof.
\end{proof}


In combination with~\Cref{prop:RDA implies CDA}, the following result establishes
the implication \ref{enum:thm:MAIN1-RDA} $\Rightarrow$ \ref{enum:thm:MAIN1-ordinary} in \Cref{thm:MAIN1}.

 %%
%%% Proposition
%%

\begin{restatable}{proposition}{propCDAtoholonomic}
\label{prop:CDA implies multi-holonomic degree 0}
Let $f(x)$ be a CDA power series defined by the system of  differential equations 
\begin{equation}
\label{eq:prop:CDS implies multi}
y_1'= P_1(y_1,\ldots,y_k),\ldots, y'_k = P_k(y_1,\ldots,y_k)\,.
\end{equation}
Then 
 $f(x)$ is the ordinary generating function of a
differential tree automaton in which the rational weight of 
 every transition  has the form $\frac{a}{x}$ for some $a\in \K$.
\end{restatable}

\begin{proof}[Proof sketch]
We can assume that 
the polynomials $P_1,\ldots,P_k$ lie in  $\K[y_1,\ldots,y_k]$ instead of $\K[x][y_1,\ldots,y_k]$. This assumption is  without loss of generality as one can rewrite 
 all polynomials  $P_1,\ldots,P_k$ 
by  replacing every occurrence of $x$ in these polynomials by a new power series variable $z$, and
by adding the equation 
 $z' = 1$. 

Denote by $m$  the maximal total degree of the polynomials~$P_i$. Let the tuple 
 $(y_1(x),\ldots,y_k(x))$ of power series be a solution of the system and write $y_j(x) = \sum_{n=0}^\infty a_{n,j} x^n$ for all~$j \in \{1, \ldots, k\}$. Substituting  this solution in  the defining system of equations in \eqref{eq:prop:CDS implies multi} entails that  for all $n \geq 1$, $n \, a_{n,j}$  equals the $(n-1)$-th coefficient of the power series $P_j(y_1(x),\ldots,y_k(x))$. 

To represent the coefficients of the $P_j$s, we decompose each polynomial $P_j$ into the sum of its monomials as follows:
\[
    P_j(y_1,\ldots,y_k) = \sum_{\ell=0}^m \sum_{\bm{i} \in \{1, \ldots,k\}^\ell} \alpha_{\bm{i},j} y_{i_1} \ldots y_{i_\ell} ,
\]
with all $\alpha_{\bm{i},j}$s being in $\K$. 
Hence, the $(n-1)$-th coefficient of each monomial $\alpha_{\bm{i},j} y_{i_1}(x) \ldots y_{i_\ell}(x)$ is given by 
\[
\sum_{\bm{n} \in J_n(\ell)} \alpha_{\bm{i},j} a_{n_1,i_1}\ldots a_{n_\ell,i_\ell}\,,
\]
where $J_n(\ell)$ is the set of tuples $(j_1,\ldots,j_\ell) \in \N^{\ell}$ such that $j_1 + \ldots + j_\ell = n-1$.

Following the above observation, we build a differential tree automaton $\A = (k+1,\mu)$ over an alphabet $\Sigma$  such that the $n$-th coefficient of $\vf_\A(x)$ is the vector $\begin{bmatrix} a_{n,1} & \ldots & a_{n,k} & 1 \end{bmatrix}$. For this, when $\ell \geq 1$, for each monomial $\alpha_{\bm{i},j} a_{n_1,i_1}\ldots a_{n_\ell,i_\ell}$, we introduce a symbol $\sigma_{\bm{i},j}$ in the alphabet $\Sigma$ with the transition rule
\[
\sigma_{\bm{i},j}(q_{i_1},\ldots,q_{i_\ell}) \xlongrightarrow{\alpha_{\bm{i},j}} q_j
\]
The $k+1$ component in the vector $\begin{bmatrix} a_{n,1} & \ldots & a_{n,j} & 1 \end{bmatrix}$ is in fact used to handle the case $\ell = 0$ by introducing an additional unary symbol. 
\end{proof}

To establish the remaining implications in~\Cref{thm:MAIN1} we use~\Cref{prop:automata to recurrence}, which shows  that the labelled and ordinary generating function of an automaton induces multi-linear recurrence relations that solely differ by a factor of $\frac{1}{n}$.  


Given a differential tree automaton $\A = (d,\mu)$, 
 define  
$\vf_\A(x) = \sum_{n=0}^\infty \va_n x^n$ and $\widetilde{\vf}_\A(x) = \sum_{n=0}^\infty \vb_n x^n$, where
\[
\va_n = \sum_{\substack{t\in T_\Sigma\\ \size{t}=n}} \hmu(t) \quad \text{and} \quad \vb_n = \sum_{\substack{t\in T_\Sigma\\ \size{t}=n}} \lambda(t)\hmu(t)\,.
\]
Observe that $f_{\A,1}(x)$ is the ordinary generating function~$f_\A(x)$, and similarly $\widetilde{f}_{\A,1}(x)$ is the labelled generating function~$\widetilde{f}_{\A}(x)$.  More generally,
the power series $f_{\A,i}(x)$ and $\widetilde{f}_{\A,i}(x)$ can be seen respectively as the ordinary and labelled generating functions of $\A$ when $q_i$ is considered the final state.  



%%
%%% Proposition
%%

\begin{restatable}{proposition}{propautomatatorecurrence}
\label{prop:automata to recurrence}
Let $\A = (d,\mu)$ be a differential tree automaton over $\Sigma$ of  maximal arity $m$. Write
$\vf_\A(x) = \sum_{n=0}^\infty \va_n x^n$ and $\widetilde{\vf}_\A(x) = \sum_{n=0}^\infty \vb_n x^n$ (as above).
Then 
\[\vb_0 = \va_0 = \sum_{\sigma \in \Sigma_0} \mu(\sigma)\,,\] 
and for all $n \geq 1$
\begin{align*}
\va_n &= \sum_{\substack{\ell \in \{1, \ldots,m\}\\\bm{j} \in J_n(\ell)}} (\va_{j_1} \otimes \ldots \otimes \va_{j_\ell}) \cdot \sum_{\sigma \in \Sigma_\ell}\mu(\sigma)(n)\\
\vb_n &= \frac{1}{n}\sum_{\substack{\ell \in \{1, \ldots,m\}\\\bm{j} \in J_n(\ell)}} (\vb_{j_1} \otimes \ldots \otimes \vb_{j_\ell}) \cdot \sum_{\sigma  \in \Sigma_\ell} \mu(\sigma)(n) \,
\end{align*}
where  $J_n(\ell)$ is the set of tuples $(j_1,\ldots,j_\ell) \in \N^{\ell}$ such that $j_1 + \ldots + j_\ell = n-1$.

\end{restatable}

\begin{proof}[Proof sketch]
The key idea of the proof is to rewrite the sum~$\sum_{\substack{t\in T_\Sigma\\ \size{t}=n}} \hmu(t)$, for trees~$t\in T_\Sigma$ with $\size{t}\geq 1$, as 
a summation over possible root symbol and subtrees. 
Since $t$ has size larger than one, it is of the form $\sigma(t_1,\ldots,t_\ell)$ for some $\sigma \in \Sigma_\ell$. Hence
\[
\va_n = \sum_{\ell=1}^m \sum_{\substack{\sigma \in \Sigma_\ell\\\bm{j} \in J_n(\ell)}} \sum_{\substack{t_1\in T_\Sigma\\ \size{t}=j_1}} \ldots \sum_{\substack{t_\ell\in T_\Sigma\\ \size{t}=j_\ell}} \hmu(\sigma(t_1,\ldots,t_\ell))\,.
\]
Unfolding the definition of $\hmu(\sigma(t_1,\ldots,t_\ell))$ and using the bilinearity of the Kronecker product we derive the claimed  recurrence for~$\va_n$.

The claimed recurrence relation for $\vb_n$ follows 
by similar reasoning combined with the following  additional observation.
Since  the multinomial coefficient
$\binom{n-1}{j_1,\ldots,j_\ell}$  represents the number of partitions of $\{1,\ldots,n-1\}$ into subsets of respective sizes 
$j_1,\ldots,j_\ell$,
the number of labellings of the tree~$t$ equals the product of
$\binom{n-1}{j_1,\ldots,j_\ell}$ with the respective numbers of labellings of~$t_1,\ldots,t_\ell$.
It follows that
\[ \lambda(\sigma(t_1,\ldots,t_\ell))= \frac{1}{n} \lambda(t_1) \cdots \lambda(t_\ell) \,. \qedhere\]
\end{proof}


The sequences $(\va_n)_{n=0}^\infty$ and $(\vb_n)_{n=0}^\infty$ defined in~\Cref{prop:automata to recurrence} 
are multi-holonomic  with defining matrices $\mu_\ell = \sum_{\sigma \in \Sigma_\ell} \mu(\sigma)$ for all $\ell \in \{0, \ldots, m\}$. 

The implication \ref{enum:thm:MAIN1-ordinary} $\Rightarrow$ \ref{enum:thm:MAIN1-RDA}  in~\Cref{thm:MAIN1} follows
 directly from~\Cref{prop:automata to recurrence} and~\Cref{prop:multi-holonomic degree 1 to RDA}, given below. 

\begin{restatable}{proposition}{propHolonomicOneToRDA}
\label{prop:multi-holonomic degree 1 to RDA}
Let $(\va_n)_{n=0}^\infty$ be a multi-holonomic sequence of order $d$ and degree at most $1$ with common denominator $x$. The  power series of coordinates of~$\vf(x) = \sum_{n=0}^\infty \va_n\ x^n$ are all RDA.
\end{restatable}

\begin{proof}[Sketch proof]
Denote by $\SDerive{f}$  the differential operator defined by $\SDerive{f}(x) := x f'(x)$. 

We show that the vector $\vf(x)$ of power series is in fact a solution of a system of differential equations of the form 
\[
\begin{cases}
\SDerive{y_1} = x Q_1(y_1,\ldots,y_d) + \sum_{i = 1}^d \SDerive{y_i }\cdot xP_{1,i}(y_1,\ldots,y_d) \\
 \vdots\\
\SDerive{y_d}  = x Q_d(y_1,\ldots,y_d) + \sum_{i = 1}^d \SDerive{y_d}\cdot xP_{d,i}(y_1,\ldots,y_d) \\
\end{cases}
\]
where $Q_i,P_{i,j}$s are polynomials in $\K[y_1,\ldots,y_d]$. This can be seen as a linear system of equations in $\SDerive{f_1},\ldots,\SDerive{f_d}$ with coefficients in the field of rational functions $\K(x,f_1,\ldots,f_d)$. As such, we can compute the determinant $\det(M)$, where $M$ represents the coefficient matrix of the system. Crucially we show  that $\det(M)$  is  a non-zero polynomial in $\K[x,f_1,\ldots,f_d]$. Hence, we have \[M^{-1} = \frac{1}{\det(M)}\,\mathrm{adj}(M)\, .\]
Furthermore, we prove that  $\det(M)$ does not vanish at $(0,f_1(0),\ldots,f_d(0))$, which in turn implies that
\[
\begin{bmatrix}
\SDerive{f_1}\\
\vdots\\
\SDerive{f_d}\\
\end{bmatrix}
= 
M^{-1}
\begin{bmatrix}
xQ_1\\
\vdots\\
xQ_d\\
\end{bmatrix}
= x \begin{bmatrix}
    U_1\\
    \vdots\\
    U_d\\
    \end{bmatrix}
\]
where the rational functions $U_1,\ldots,U_d \in \K(x,f_1,\ldots,f_d)$ are defined at $(0,f_1(0),\ldots,f_d(0))$. This concludes the proof.
\end{proof}


We complete the proof of \Cref{thm:MAIN1} by showing the equivalence \ref{enum:thm:MAIN1-ordinary}  $\Leftrightarrow$ \ref{enum:thm:MAIN1-labelled} in the theorem.
Given any multi-holonomic sequence $(\va_n)_{n=0}^\infty$  of order $d$ and arity $m$, defined by matrices $\mu_1$, \ldots, $\mu_m$, \Cref{prop:automata to recurrence} implies  that the 
sequence arises as 
 the ordinary  generating functions~$\vf_\A(x)$  of some differential tree automaton~$\A$. 
More precisely, define $\A= (d,\mu)$ over the alphabet $\Sigma = \{ \sigma_0, \ldots, \sigma_m\}$ such that $\sigma_i$ has arity $i$, $\mu(\sigma_0) = \va_0$, and
\[
\mu(\sigma_\ell)(x) = \mu_\ell(x)\quad 
\]
for all $\ell \in \{1, \ldots, m\}$.
Replacing  transition matrix  $\mu(\sigma_\ell)(x)$
in~$\A$ with $\mu(\sigma_\ell)(x) = x \cdot \mu_\ell(x)$ gives another automaton~$\B$ whose  
labelled generating functions~$\widetilde{\vf}_\B(x)$  is  induced by~$(\va_n)_{n=0}^\infty$. 

Since the proof of the equivalence \Cref{enum:thm:MAIN1-RDA} $\Leftrightarrow$ \Cref{enum:thm:MAIN1-ordinary} in the theorem relies on~\Cref{prop:CDA implies multi-holonomic degree 0}, we can now establish \ref{enum:thm:MAIN1-ordinary}  $\Rightarrow$ \ref{enum:thm:MAIN1-labelled} by restricting our attention to  differential tree automata in which the rational weight of 
 every transition  has the form $\frac{a}{x}$ for some~$a\in \K$.  
Given such a differential tree automaton $\A$
we apply \Cref{prop:automata to recurrence} to show that the vector of power series $\vf_{\A}(x) = \sum_{n=0}^\infty \va_n x^n$ induces a multi-holonomic sequence $(\va_n)_{n=0}^\infty$ in which every entry of the defining matrices also has the form $\frac{a}{x}$ for some~$a\in \K$. We can thus apply the above observation to show the existence of a $\K$-weighted automaton $\B$ whose labelled generating function $\widetilde{\vf}_\B(x)$ equals $\vf_{\A}(x)$. 
The converse direction \ref{enum:thm:MAIN1-labelled} $\Rightarrow$ \ref{enum:thm:MAIN1-ordinary} is analogous (application of \Cref{prop:automata to recurrence} followed by above observation).  




