%%% Section
%%

\section{Proof of \texorpdfstring{\Cref{thm:MAIN2}}{Theorem~\ref{thm:MAIN2}}}

This theorem shows the equivalence of differentially algebraic power series, ordinary generating function of differential tree automata, and multi-holonomic sequences of arity~2. 

The most challenging development in this theorem is to establish  \ref{enum:thm:MAIN2-D-algebraic} $\Leftrightarrow$ \ref{enum:thm:MAIN2-recurrence}. 
Before discussing this equivalence, we outline the key    
 ingredients required to establish   \ref{enum:thm:MAIN2-ordinary} $\Leftrightarrow$ \ref{enum:thm:MAIN2-recurrence} in \Cref{thm:MAIN2}. 
 Detailed proofs can be found in Appendix~\ref{app:theorem2}.

By \Cref{prop:automata to recurrence}, the ordinary generating function of any differential tree automaton $\A$ is the first component of the vector of power series $\vf_\A(x) = \sum_{n=0}^\infty \va_n x^n$. The latter induces a multi-holonomic sequence $(\va_n)_{n=0}^\infty$. 
 By \Cref{thm:MAIN3}, this sequence is recognised by a multi-holonomic sequence of arity 2 which concludes the proof of \ref{enum:thm:MAIN2-ordinary} $\Rightarrow$ \ref{enum:thm:MAIN2-recurrence} in \Cref{thm:MAIN2}. 
We note in passing that the main milestone of the above argument is addressed in~\Cref{thm:MAIN3}. 

Conversely, consider the sequence $(\vb_n)_{n=0}^\infty$ of elements in~$\K^d$ satisfying for all $n \geq 1$ the recurrence 
\begin{equation}
\label{eq:th3:recurrence}
\vb_{n} = \vb_{n-1} \cdot P(n) + \sum_{k=0}^{n-1} (\vb_k \otimes \vb_{n-k-1})\cdot Q(n)
\end{equation}
with $P$ and $Q$ having entries defined on positive integers. We define the alphabet $\Sigma = \{ \sigma_0, \sigma_1, \sigma_2 \}$ with $\sigma_0$, $\sigma_1$ and $\sigma_2$ having, respectively, arity $0$, $1$ and $2$. Finally, we define the differential tree automaton $\A = (d,\mu)$ over $\Sigma$ such that $\mu(\sigma_0) = \vb_0$, and
\[
    \mu(\sigma_1)(x) = P(x)\quad \text{and}\quad \mu(\sigma_2)(x) = Q(x)\,.
\]
From \Cref{prop:automata to recurrence}, writing $\vf_\A(x)$ as $\sum_{n=0}^\infty \va_n x^n$, we directly obtain that the sequence $(\va_n)_{n=0}^\infty$ satisfies the recurrence relation for $(\vb_n)_{n=0}^\infty$ stated in \Cref{eq:th3:recurrence}. Moreover, the two sequences have the initial value, that is $\va_0 = \vb_0$. Thus $(\vb_n)_{n=0}^\infty = (\va_n)_{n=0}^\infty$, which concludes the proof of  the direction \ref{enum:thm:MAIN2-recurrence} $\Rightarrow$ \ref{enum:thm:MAIN2-ordinary} in \Cref{thm:MAIN2}. 

%%
%%% Subsection
%%



\subsection{From Multi-Holonomic Sequences to Differentially Algebraic Power Series}

This section focuses on proving~\ref{enum:thm:MAIN2-recurrence} $\Rightarrow$ \ref{enum:thm:MAIN2-D-algebraic} in \Cref{thm:MAIN2}. In other words, we show that  given a multi-holonomic sequence~$(\va_n)_{n=0}^\infty$, 
all induced 
coordinate power series~$\sum_{n=0}^\infty a_{n,i} x^n$, fpr $i \in \{1, \ldots, d\}$, are differentially algebraic. For this, we rely once again on the differential operator $\SDerive{f}$  defined by $\SDerive{f}(x) := x f'(x)$.
For all $i \in \N$ we write $\SDeriveN{f}{i+1}(x)$ for the $i+1$-th  iteration of this operator:
\[\SDeriveN{f}{i+1}(x) := \SDerive{(\SDeriveN{f}{i})}(x)\, .\]

%%
%%% Proposition
%%
Let $(\va_n)_{n=0}^\infty$ be a multi-holonomic sequence of arity~$m$ and degree~$r$,   defined by  matrices $\mu_1,\ldots,\mu_m$ that, without loss of generality, are assumed to share a common denominator $A(x) \in \K[x]$. Furthermore, as $(\va_n)_{n=0}^\infty$ has degree $r$, we may assume that
\[
A(x) = \sum_{i=0}^r c_i x^i
\]
for some $c_0,\ldots,c_r \in r$ and for all $\ell \in \{1, \ldots, m\}$, \[\mu_\ell(x) = \sum_{i=0}^r x^i \cdot \mu_{\ell,i}\]
for some $\mu_{\ell,i} \in \K^{d^\ell\times d}$. Recall that $J_n(\ell)$ is the set of tuples $(j_1,\ldots,j_\ell) \in \N^{\ell}$ such that $j_1 + \ldots + j_\ell = n-1$.

\begin{restatable}{proposition}{propsystemofequations}
\label{prop:system equations}
Let $(\va_n)_{n=0}^\infty$ be a multi-holonomic sequence, defined as above. The vector of power series $\vf(x) = \sum_{n=0}^\infty \va_n \,x^n$ satisfies the following system of differential equations:
\begin{align}
\sum_{i=0}^r c_i &\SDeriveN{\vf}{i} - c_0\va_0 \notag\\
=\ & x \sum_{\substack{\ell \in \{1, \ldots,m\}\\i \in \{0, \ldots,r\}\\\bm{j} \in J_{i+1}(\ell+1)}} \binom{i}{\bm{j}}  (\SDeriveN{\vf}{j_1} \otimes \ldots \otimes \SDeriveN{\vf}{j_\ell}) \cdot \mu_{\ell,i}\label{eq:system1}
\end{align}
\end{restatable}

\begin{proof}[Proof Sketch.]
The argument relies on the observation that for any power series $g(x) = \sum_{n=0}^\infty b_n x^n$, we have 
\[
\SDerive{g}(x) = \sum_{n=0}^\infty n b_n x^n\, \]
and more generally $\SDeriveN{g}{k}(x) = \sum_{n=0}^\infty n^k b_n x^n$. Thus, 
\[
\sum_{i=0}^r c_i \SDeriveN{f}{i}(x) = \sum_{n=0}^\infty A(n) \va_n x^n\, 
\]
Moreover, for $\bm{j} \in J_{i+1}(\ell+1)$,
\begin{align*}
(\SDeriveN{\vf}{j_1} \otimes &\ldots \otimes \SDeriveN{\vf}{j_\ell}) \cdot \mu_{k,i} \\
=\ & \sum_{\bm{n} \in \N^\ell} (\va_{n_1} \otimes \ldots \otimes \va_{n_\ell}) n_1^{j_1} \ldots n_\ell^{j_\ell} x^{n_1+\ldots+n_\ell}\cdot \mu_{k,i}
\end{align*}
By using the multinomial theorem, instantiated as follows,
\[
(n_1 + \ldots + n_\ell + 1)^i = \sum_{\substack{\bm{j} \in J_{i+1}(\ell+1)}} \binom{i}{\bm{j}} n_1^{j_1}\ldots n_\ell^{j_\ell}
\]
and by unfolding \Cref{eq:multiholonomic}, we conclude the proof.
\end{proof}

In \Cref{prop:system equations}, we showed that given a multi-holonomic sequence $(\va_n)_{n=0}^\infty$, the vector of power series $\vf(x) = \sum_{n=0}^\infty \va_n \,x^n$ is a solution of the system as in \Cref{eq:system1}. In the next proposition, we show that this vector is the unique solution of the system,  given the initial value $\va_0$.

%%
%%% Proposition
%%

\begin{restatable}{proposition}{propunicity}\label{pro: Unicity}
Let $(\va_n)_{n=0}^\infty$ be a multi-holonomic sequence and  $S$ be the system of differential equations derived from $(\va_n)_{n=0}^\infty$ as given in \Cref{eq:system1} of \Cref{prop:system equations}.

Given any solution $\overline{\vf}(x) = \sum_{n=0}^\infty \overline{\va}_n\,x^n$ of $S$, it is the unique power series solution with the initial value~$\overline{\va}_0$. 
Moreover, if $A(0) \neq 0$ then $\vf(x) = \sum_{n=0}^\infty \va_n \,x^n$ is the unique power series solution of~$S$.
\end{restatable}

\begin{proof}[Proof sketch]
The proof involves a fairly straightforward analysis of the $n$-th coefficients (for $n \geq 1$) of the two sides of \Cref{eq:system1} evaluated at the solution $\overline{\vf}(x)$. 
In particular, the $n$-th coefficient of the left-hand side can be written as 
\[
\sum_{i=0}^r c_i\, n^i\, \overline{\va}_n - c_0 \va_0 = A(n) \overline{\va}_n - c_0 \va_0
\]
As the right-hand side of~\Cref{eq:system1} is guarded by $x$, so for all  $n \geq 1$, the $n$-th coefficient of the right-hand side evaluated at $\overline{\vf}(x)$ is an expression in 
values $\overline{\va}_{n'}$ with $n' < n$.
Hence,  the term $\overline{\va}_n$ is uniquely defined by the values of its predecessors, which in turn implies that $\overline{\vf}(x)$ is uniquely defined by $\overline{\va}_0$.

Notice that if $c_0 \neq 0$ then the constant coefficient of the left-hand side is $c_0 \overline{\va}_{0} - c_0 \va_0$ whereas the constant coefficient of the right side is always $0$. Hence when $c_0 \neq 0$, the equality $\overline{\va}_{0} = \va_0$ holds, which in turn implies that $\vf(x) = \sum_{n=0}^\infty \va_n \,x^n$ is the unique power series solution of~$S$.
\end{proof}

We  use the uniqueness of the power series solution, given an initial value,  to prove that all induced coordinate power series of the solution are differentially algebraic. This is based on a differential version of the Artin approximation theorem given in \cite{denef1984power}.

\begin{theorem}\cite[Theorem 2.1]{denef1984power}\label{thm: approximation}
    Let $S$ be a system of differential polynomials in the differential variables $y_1, \ldots, y_k$ with coefficients in $\K[x]$. Let $(y_1(x), \ldots, y_k(x)) \in \K[\![x]\!]^k$ be a solution of $S$ and $m \in \N$.
    Then there exists another solution $(\Bar{y}_1(x), \ldots, \Bar{y}_k(x)) \in \K[\![x]\!]^k$ such that all $\Bar{y}_i(x)$'s are  differentially algebraic and  \[(y_1(x), \ldots, y_k(x)) \equiv (\Bar{y}_1(x), \ldots, \Bar{y}_k(x)) \pmod{x^m}\,.\]
\end{theorem}

This theorem states that any solution (not necessarily differentially algebraic) of a system of a differential equations can be approximated by a differentially algebraic solution, such that both solutions agree on the first $m$ coefficients. 
This differential version of the Artin approximation theorem is used in the following proposition to complete  
 the proof of the implication \ref{enum:thm:MAIN2-recurrence} $\Rightarrow$ \ref{enum:thm:MAIN2-D-algebraic} in \Cref{thm:MAIN2}. 

%%
%%% Theorem
%%

\begin{proposition}
\label{th:differentially algebraic}
Let $(\va_n)_{n=0}^\infty$ be a multi-holonomic sequence. All components of  $\vf(x) = \sum_{n=0}^\infty \va_n\,x^n$ are differentially algebraic power series.
\end{proposition}

\begin{proof}
From \Cref{prop:system equations}, $\vf(x) = \sum_{n=0}^\infty \va_n\,x^n$ is a solution of the system of differential equations given in \Cref{eq:system1}. From \Cref{thm: approximation}, we know that there exists another power series solution $\overline{\vf}(x)$  such that all the power series are differentially algebraic and they coincide in particular with the first coefficients of $\vf(x)$, i.e., $\overline{\va}_0 = \va_0$. From \Cref{pro: Unicity}, we deduce that $\overline{\vf}(x) = \vf(x)$ which allows us to conclude that all power series in $\vf(x)$ are differentially algebraic.
\end{proof}



%%
%%% Subsection
%%

\subsection{From Differentially Algebraic Power Series to Multi-Holonomic Sequences}

To complete the proof of \Cref{thm:MAIN2}, it remains to show that any differentially algebraic power series is the component of a multi-holonomic sequence of arity 2, that is, the implication \ref{enum:thm:MAIN2-D-algebraic} $\Rightarrow$ \ref{enum:thm:MAIN2-recurrence} in \Cref{thm:MAIN2}. Our proof builds on a construction of Denef and Lipschitz~\cite{denef1984power}, who showed that 
the sequence of coefficients of any differentially algebraic power series $f(x) = \sum_{n=0}^\infty a_n x^n$ satisfies a recurrence of the form:
\[P(n) \,  a_{n} = Q_n(a_0,\ldots,a_{n-1}) \, , \]
where $Q_n$ is a polynomial whose form depends on $n$. Our proof makes explicit this recurrence and shows that how it can be transformed into a generalised multi-holonomic sequence. The proof will then conclude by applying \Cref{thm:MAIN3}.

\medskip

Observe that $n$-th coefficient of  a power series $f(x) = \sum_{n=0}^\infty a_n x^n$ satisfies 
 $a_n = n!\,f^{(n)}(0)$.   
  Hence, to obtain a recurrence relation between the coefficients, we only need to obtain a recurrence relation between the derivatives of~$f$ evaluated at $0$. 
  One way to do so is to differentiate the differential polynomial $P$ on which the differentially algebraic power series $f(x)$, that is, the polynomial
  $P(y,y^{(1)},\ldots, y^{(d)})$ with coefficients in $\K[x]$ such that 
  $P(f(x),f'(x), \ldots, f^{(d)}(x)) = 0$.
In particular, notice that
\begin{equation}
\label{eq:denef}
P' = \frac{\partial P}{\partial y^{(d)}} y^{(d+1)} + R ',  ,
\end{equation}
with both $R$ and $\frac{\partial P}{\partial y^{(d)}}$ being polynomials in $\K[x][y,\ldots,y^{(d)}]$, thus of order strictly smaller than $d+1$. The partial derivative of $P$ by its highest-order variable, namely $\frac{\partial P}{\partial y^{(d)}}$, is called the \emph{separant of $P$}. Since $f(x)$ and its derivatives form a root of $P$ then they are also a root of $P'$. Hence, instantiating \Cref{eq:denef} with $f$ and its derivates evaluated at $0$  leads to the following equation.
\[
\frac{\partial P}{\partial y^{(d)}}(f(0),\ldots,f^{(d)}(0)) f^{(d+1)}(0) = - R(f(0),\ldots,f^{(d)}(0))
\]
We can see here how the recurrence takes shape as $f^{(d+1)}(0)$ is expressed using an equation that depends solely on $f^{(i)}(0)$ for $i \leq d$. However, the main hurdle comes from the fact that the separant can vanish at $0$.   


As a first step in addressing this issue, 
in the next proposition, we show that 
one can always assume that 
 the separant of $P$ is not identically zero at the solution. In other words, 
\[
\frac{\partial P(y,y^{(1)},\ldots,y^{(d)})}{y^{(d)}}(f(x),f'(x), \ldots,f^{(d)}(x)) \neq 0 \,.
\]
This properties holds if $P$ has minimal order and degree among differential polynomials that annihilate $f$.

%%
%%% Proposition
%%





\begin{restatable}{proposition}{propvanishingorder}
\label{prop:vanishing order}
Let $f(x) \in \K[\![x]\!]$ be a differentially algebraic power series. There exists a differential polynomial $P \in \K[x][y,\ldots,y^{(d)}]$ such that
\begin{align*}
   P(f(x),\dots,f^{(d)}(x))=0, \text{ and }\\
   \frac{\partial P}{\partial y^{(d)}} (f(x),\ldots,f^{(d)}(x)) \neq 0 \,.
\end{align*}
\end{restatable}

\begin{proof}
By definition of differentially algebraic power series, there exists a non-zero polynomial $P(y^{(0)},\ldots,y^{(d)})$ with coefficients in $\K[x]$ such that $P(f(x),\ldots,f^{(d)}(x)) = 0$. We consider such polynomial $P$ with the smallest $(d,\mathrm{deg}(y^{(d)}))$ (using the lexicographic ordering) where $d$ is the highest order of $y$ in $P$ and  $\deg(y^{(d)})$ is the degree of $y^{(d)}$ in $P$. 
As the polynomial $\frac{\partial P}{\partial y^{(d)}}$ is not identically zero and has either the same order and strictly smaller degree than $y^{(d)}$, or a strictly small order,  by minimality of $P$ in the defined lexicographic ordering, we deduce  that $\frac{\partial P}{\partial y^{(d)}}(f(x),\ldots,f^{(d)}(x)) \neq 0$. 
\end{proof}

We may thus assume that  the separant of $P$ not identically zero at the solution $f$.
The core idea of the Denef and Lipschitz~\cite{denef1984power} construction consists of iteratively differentiating the polynomial $P$
until the resulting differential polynomial meets certain condition (requiring that the coefficient of highest order term 
never vanishes at~$0$).
The number of successive differentiations  depends on the separant.


 Given $k \in \N$ and differential polynomials $A \in \K[x][y^{(\infty)}]$,  denote by $A \mod y^{(k)}$ the polynomials obtained from $A$ by removing all monomials of order at least~$k$ (all monomials that are multiple of $y^{(o)}$ for some $o\geq k$). 


%%
%%% Proposition
%%

\begin{restatable}{proposition}{lemRecursion}
\label{lem:RECUR1}
Let $f \in \K[\![x]\!]$ be a power series and $P \in \K[x][y,\ldots,y^{(d)}]$ a differential polynomial  such that
\[P(x,f,\dots,f^{(d)})=0 \quad \text{ and } \quad \frac{\partial P}{\partial y^{(d)}} (x,f,\ldots,f^{(d)}) \neq 0\,.\]
Then there exist $m,s,N\in \mathbb N$
and polynomial $A \in \K[x]$ such that for all~$n \geq N$ we have $A(n) \neq 0$ and
\begin{gather}
f^{(n+s+1)}(0)  = \frac{1}{A(n)} \, Q_n(0,f(0),\ldots,f^{(n+s)}(0))
\label{eq:KEY}
\end{gather}
where $Q_n = P^{(m+n)} \bmod y^{(n+s+1)}$.
\end{restatable}

\begin{proof}[Proof sketch]
Since the separant is not identically zero, after evaluating it at $f$ and its derivates, we get
\[
\frac{\partial P}{\partial y^{(d)}}\left(f,\ldots,f^{(d)}\right)=x^k \cdot \sum_{i=0}^\infty c_i x^i
\] 
for some $k$ with $c_0 \neq 0$.
In the sequel we refer to $k$ as the \emph{vanishing order} of the separant. 

By differentiating $P$ to order $2k+2$, we can show that
\[
    P^{(2k+2)} =  y^{(d+2k+2)}f_d + \cdots + y^{(d+k+2)}f_{d+k}+f_{d+k+1}
\]
where each $f_j$ has order at most $j$ and $f_d = \frac{\partial P}{\partial y^{(d)}}$. Continuing to differentiate, we obtain that for all $n \in \N$, $P^{(2k+2+n)}$ becomes 
\begin{equation}
\label{eq:proof-denef2}
y^{(d+2k+2+n)}S_0(n) + \cdots + y^{(d+k+2+n)}S_k(n)+ H
\end{equation}
where each $S_j(n)$ has order at most $d+j$ and $H$ has order at most $d+k+1+n$. Moreover, each \[S_j(n)(0,f(0),\ldots, f^{(d+j)}(0))\]
can be seen as a univariate polynomial in $n$.
In particular, as we  assumed that the separant has vanishing order $k$, there is at least one of these polynomials that are not identically zero. We take the smallest index $r \in \{0, \ldots, k\}$ such that \[- S_r(n)(0,f(0),\ldots, f^{(d+r)}(0))\] is not identically zero and we define $A(n)$ to be this polynomial. 



By taking $m = 2k+2$ and $s = d + 2k + 1 - r$, the restriction of \Cref{eq:proof-denef2} to monomials of order strictly lower than $s+n+1$ corresponds to the polynomials \[y^{(d+k+2+n-r-1)}S_{r+1}(n) + \ldots + y^{(d+k+2+n)}S_k(n)+ H\,.\] Therefore, defining,  for all~$n \geq N$, 
\begin{align}
\label{def-Qn}
    Q_n := P^{(m+n)} \mod y^{(s+n+1)}\,,
\end{align} we obtain the desired result.
\end{proof}





To complete the proof of the implication \ref{enum:thm:MAIN2-D-algebraic} $\Rightarrow$ \ref{enum:thm:MAIN2-recurrence} in \Cref{thm:MAIN2}, we show that the polynomial $Q_n$ defined in~\eqref{def-Qn} naturally induces a generalised multi-holonomic sequence. Indeed, using Pascal's identity, we have for every monomial $M = y^{(i_1)}\ldots y^{(i_\ell)}$ in $P$ and for all~$n \in \N$, 
\[ M^{(n)} = \sum_{\bm{j} \in J_{n+1}(\ell)} \binom{n}{\bm{j}} \, y^{(i_1+j_1)} \cdots y^{(i_\ell+j_\ell)} \,.  \]
Computing  $M^{(m+n)}$ modulo $y^{(s+n+1)}$ intuitively corresponds to adding guard conditions on the indices $j_1,\ldots,j_\ell$. As such, $M^{(m+n)} \mod y^{(s+n+1)}$ becomes 
\[
    \sum_{\bm{j} \in G_{n+1}(\bm{m})} \binom{n+m}{\bm{j}} \, y^{(i_1+j_1)} \cdots y^{(i_\ell+j_\ell)}
\]
with $\bm{m} = (m,i_1-1-s,\ldots,i_\ell-1-s)$. The final generalised multi-holonomic sequence is obtained by summing over all monomials and applying an additional shift by $N$ since \Cref{eq:KEY} holds only when $n \geq N$. The proof concludes by invoking \Cref{thm:MAIN3}.  

\subsection{Equivalence of differential tree automata and their generating function}

We can use
\Cref{thm:MAIN2}  to decide the zeroness and equivalence of the 
generating functions and formal tree series associated to a differential tree automaton.

%%
%%% Theorem
%%

\begin{theorem}
\label{th:equivalence}
The problems of zeroness and equivalence of formal tree series for $\Q$-differential tree automata are decidable. 
The  problems of zeroness and equivalence of ordinary and labelled generating functions for $\Q$-differential tree automata are decidable.
\end{theorem}

\begin{proof}
Let $\A$ be a differential tree automaton. From \Cref{prop:system equations,pro: Unicity}, we know that the vector of $d$ power series $\vf_\A(x) = \sum_{n=0}^\infty \va_n x^n$ is the unique solution of a system of differential equations $S$ with $\va_0$ as initial value. Recall that the ordinary generating function of $\A$ is the first coordinate of $\vf_\A(x)$. We augment the system $S$ with
\begin{itemize}
\item an equation $f_1 = 0$ to test if the first coordinate is $0$;
\item $d$ equations $f_1 = a_{0,1} + x g_1$, \ldots, $f_d = a_{0,d} + x g_d$ with $g_1,\ldots,g_d$ fresh variables to enforce the initial values.
\end{itemize} 
Thus, deciding zeroness of the ordinary generating function 
% of $\A$ 
is equivalent to determining solubility of a system of differential equations of $\Q[x]$, which is decidable~\cite[Theorem 3.1]{denef1984power}.

All other problems mentioned in this theorem can be reduced to the zeroness of ordinary generating functions: For zeroness of labelled generating functions, we rely on \Cref{prop:automata to recurrence}. The equivalence of generating functions can be reduced to the the zeroness of their difference thanks to their closure properties (see \Cref{prop:closure} in Appendix~\ref{sec:operations}). 
The same closure properties allow us to decide the zeroness of formal tree series $\sem{\A}$ by building an automaton $\A'$ such that $\sem{\A'}{t} = \sem{\A}{t}^2$ for all $t\in T_\Sigma$ and by testing the zeroness of the ordinary generating function of $\A'$.
\end{proof}

