\begin{theorem} \label{thm:ddadd}
    Let $(x_0, x_1)$ and $(y_0, y_1)$ be floating-point expansions in the \textsf{binary16}, \textsf{bfloat16}, \textsf{binary32}, \textsf{binary64}, or \textsf{binary128} format with $x_0 = \RNE(x_0 + x_1)$ and $y_0 = \RNE(y_0 + y_1)$. The \textsf{ddadd} algorithm, depicted in Figure~\ref{fig:networks} (left), computes a floating-point expansion $(z_0, z_1)$ that approximates the exact sum $x_0 + x_1 + y_0 + y_1$ with relative error bounded above by $(1 + 2\u) 2^{-(2p-2)} \approx 4\u^2$.
\end{theorem}

\begin{theorem} \label{thm:madd}
    Let $(x_0, x_1)$ and $(y_0, y_1)$ be floating-point expansions in the \textsf{binary16}, \textsf{bfloat16}, \textsf{binary32}, \textsf{binary64}, or \textsf{binary128} format with $x_0 = \RNE(x_0 + x_1)$ and $y_0 = \RNE(y_0 + y_1)$. The \textsf{madd} algorithm, depicted in Figure~\ref{fig:networks} (right), computes a floating-point expansion $(z_0, z_1)$ that approximates the exact sum $x_0 + x_1 + y_0 + y_1$ with relative error bounded above by $(1 + 2\u) 2^{-(2p-1)} \approx 2\u^2$.
\end{theorem}

We prove Theorems~\ref{thm:ddadd} and \ref{thm:madd} by using the SELTZO abstraction to establish $P(F)$ for a suitably chosen property $P$ given below. Some algebraic manipulation is necessary to adapt $P$ into a true relative error bound that considers all outputs.

\begin{proof}
    Consider the augmented FPANs depicted in Figure~\ref{fig:augmented}, which include an extra $\TwoSum$ gate to compute the error terms $(w_0, w_1)$. Using the SELTZO encodings stated in Propositions~\ref{prop:identity} and \ref{prop:relerr}, we use an SMT solver to prove
    \begin{equation}
        P \coloneqq (x_0 = \RNE(x_0 + x_1)) \wedge (y_0 = \RNE(y_0 + y_1)) \to (|w_0| < 2^{-k} |z_0|)
    \end{equation}
    where $k = 2p - 2$ for \textsf{ddadd} and $k = 2p - 1$ for \textsf{madd}. Note that $x_0 = \RNE(x_0 + x_1)$ is equivalent to the statement that $(x_0, x_1)$ is a fixed point of $\TwoSum$. Moreover, by Proposition~\ref{prop:outputs}, we have $z_0 = \RNE(z_0, z_1)$ and $w_0 = \RNE(w_0, w_1)$ because $(z_0, z_1)$ and $(w_0, w_1)$ are $\TwoSum$ outputs. It follows that $w_0 + w_1 = (1 + \delta_w) w_0$ and $z_0 + z_1 = (1 + \delta_z) z_0$ for some $|\delta_w|, |\delta_z| \le \u$. Hence, the relative error of these FPANs is bounded above by:
    \begin{multline}
        \frac{|(z_0 + z_1) - (x_0 + x_1 + y_0 + y_1)|}{|x_0 + x_1 + y_0 + y_1|}
        = \frac{|(1 + \delta_w) w_0|}{|(1 + \delta_z) z_0 + (1 + \delta_w) w_0|} \\
        \le \frac{(1 + \u) |w_0|}{(1 - \u)(|z_0| - |w_0|)}
        \le \frac{(1 + \u) 2^{-k}}{1 - (1 - \u)2^{-k}}
        \le (1 + 2\u) 2^{-k}
    \end{multline}
    This expression is asymptotically equivalent to $4\u^2 + O(\u^3)$ for \textsf{ddadd} and $2\u^2 + O(\u^3)$ for \textsf{madd}. \qed
\end{proof}

