\section*{Appendix} \label{sec:Appendix}

Let $x$ and $y$ be floating-point numbers, and let $(s, e) \coloneqq \TwoSum(x, y)$. Assume that $x$, $y$, $s$, and $e$ are all normalized or zero. The following lemmas constrain the possible values of $x$, $y$, $s$, and $e$ using the SE, SETZ, and SELTZO abstractions. Note that $\TwoSum$ is a commutative operation (i.e., $\TwoSum(x, y) = \TwoSum(y, x)$), so all of the following results also hold with the roles of $x$ and $y$ are reversed. We omit symmetric statements for brevity.

\subsection*{Lemma Family Z}

Lemmas in Family Z apply when one or both of the inputs $(x, y)$ are zero. These Lemmas support our SE, SETZ, and SELTZO results. \\

\noindent \textbf{Lemma Z1:}
\begin{align*}
    \TwoSum(\mathtt{+0.0}, \mathtt{+0.0}) &= (\mathtt{+0.0}, \mathtt{+0.0}) \\
    \TwoSum(\mathtt{+0.0}, \mathtt{-0.0}) &= (\mathtt{+0.0}, \mathtt{+0.0}) \\
    \TwoSum(\mathtt{-0.0}, \mathtt{-0.0}) &= (\mathtt{-0.0}, \mathtt{+0.0})
\end{align*}

\noindent \textbf{Lemma Z2:} If $x$ is nonzero, then $\TwoSum(x, \pm\mathtt{0.0}) = (x, \mathtt{+0.0})$.

\subsection*{Lemma Family SE-I}

Lemma SE-I gives a sufficient condition for the inputs $(x, y)$ to be returned unchanged by $\TwoSum$. This Lemma supports only our SE results and is superseded by a more precise Lemma in the SETZ and SELTZO abstractions. Note that, unlike the SETZ and SELTZO abstractions, the SE abstraction is not strong enough to state necessary and sufficient conditions for $(x, y) = \TwoSum(x, y)$. \\

\noindent \textbf{Lemma SE-I:} If $\lvert e_x - e_y \rvert < p + 1$ or $\lvert e_x - e_y \rvert = p + 1$ and $s_x = s_y$, then $(x, y) = \TwoSum(x, y)$.

\subsection*{Lemma Family SE-S}

Lemmas in Family SE-S apply to SE abstract inputs with the same sign. These Lemmas support only our SE results and are superseded by more precise Lemmas in the SETZ and SELTZO abstractions. In this Lemma Family, we implicitly assume that $x$ and $y$ are nonzero with $s_x = s_y$ throughout. \\

\noindent \textbf{Lemma SE-S1:} If $e_x = e_y + p$, then one of the following statements holds:
\begin{enumerate}
    \item $s_s = s_x$, $e_x \le e_s \le e_x + 1$, $s_e \ne s_y$, and $e_y - (p - 1) \le e_e \le e_x - p$.
    \item $s = x$ and $e = y$.
\end{enumerate}

\noindent \textbf{Lemma SE-S2:} If $e_x = e_y + (p - 1)$, then one of the following statements holds:
\begin{enumerate}
    \item $s_s = s_x$, $e_x \le e_s \le e_x + 1$, and $e = \mathtt{+0.0}$.
    \item $s_s = s_x$, $e_x \le e_s \le e_x + 1$, and $e_y - (p - 1) \le e_e \le e_x - p$.
\end{enumerate}

\noindent \textbf{Lemma SE-S3:} If $e_x = e_y + (p - 2)$, then one of the following statements holds:
\begin{enumerate}
    \item $s_s = s_x$, $e_x \le e_s \le e_x + 1$, and $e = \mathtt{+0.0}$.
    \item $s_s = s_x$, $e_x \le e_s \le e_x + 1$, $s_e \ne s_y$, and $e_y - (p - 1) \le e_e \le e_x - p$.
    \item $s_s = s_x$, $e_s = e_x$, $s_e = s_y$, and $e_y - (p - 1) \le e_e \le e_x - p$.
    \item $s_s = s_x$, $e_s = e_x + 1$, $s_e = s_y$, and $e_y - (p - 1) \le e_e \le e_x - (p - 1)$.
\end{enumerate}

\noindent \textbf{Lemma SE-S4:} If $e_x > e_y$ and $e_x < e_y + (p - 2)$, then one of the following statements holds:
\begin{enumerate}
    \item $s_s = s_x$, $e_x \le e_s \le e_x + 1$, and $e = \mathtt{+0.0}$.
    \item $s_s = s_x$, $e_s = e_x$, and $e_y - (p - 1) \le e_e \le e_x - p$.
    \item $s_s = s_x$, $e_s = e_x + 1$, and $e_y - (p - 1) \le e_e \le e_x - (p - 1)$.
\end{enumerate}

\noindent \textbf{Lemma SE-S5:} If $e_x = e_y$, then one of the following statements holds:
\begin{enumerate}
    \item $s_s = s_x$, $e_s = e_x + 1$, and $e = \mathtt{+0.0}$.
    \item $s_s = s_x$, $e_s = e_x + 1$, and $e_e = e_x - (p - 1)$.
\end{enumerate}

\subsection*{Lemma Family SE-D}

Lemmas in Family SE-D apply to SE abstract inputs with different signs. These Lemmas support only our SE results and are superseded by more precise Lemmas in the SETZ and SELTZO abstractions. In this Lemma Family, we implicitly assume that $x$ and $y$ are nonzero with $s_x \ne s_y$ throughout. \\

\noindent \textbf{Lemma SE-D1:} If $e_x = e_y + (p + 1)$, then one of the following statements holds:
\begin{enumerate}
    \item $s_s = s_x$, $e_s = e_x - 1$, $s_e \ne s_y$, and $e_y - (p - 1) \le e_e \le e_x - (p + 2)$.
    \item $s = x$ and $e = y$.
\end{enumerate}

\noindent \textbf{Lemma SE-D2:} If $e_x = e_y + p$, then one of the following statements holds:
\begin{enumerate}
    \item $s_s = s_x$, $e_s = e_x - 1$, and $e = \mathtt{+0.0}$.
    \item $s_s = s_x$, $e_s = e_x - 1$, $s_e = s_y$, and $e_y - (p - 1) \le e_e \le e_x - (p + 2)$.
    \item $s_s = s_x$, $e_s = e_x - 1$, $s_e \ne s_y$, and $e_y - (p - 1) \le e_e \le e_x - (p + 1)$.
    \item $s_s = s_x$, $e_s = e_x$, $s_e \ne s_y$, and $e_y - (p - 1) \le e_e \le e_x - p$.
    \item $s = x$ and $e = y$.
\end{enumerate}

\noindent \textbf{Lemma SE-D3:} If $e_x > e_y + 1$ and $e_x < e_y + p$, then one of the following statements holds:
\begin{enumerate}
    \item $s_s = s_x$, $e_x - 1 \le e_s \le e_x$, and $e = \mathtt{+0.0}$.
    \item $s_s = s_x$, $e_s = e_x - 1$, and $e_y - (p - 1) \le e_e \le e_x - (p + 1)$.
    \item $s_s = s_x$, $e_s = e_x$, and $e_y - (p - 1) \le e_e \le e_x - p$.
\end{enumerate}

\noindent \textbf{Lemma SE-D4:} If $e_x = e_y + 1$, then one of the following statements holds:
\begin{enumerate}
    \item $s_s = s_x$, $e_x - p \le e_s \le e_x$, and $e = \mathtt{+0.0}$.
    \item $s_s = s_x$, $e_s = e_x$, and $e_e = e_x - p$.
\end{enumerate}

\noindent \textbf{Lemma SE-D5:} If $e_x = e_y$, then one of the following statements holds:
\begin{enumerate}
    \item $s = \mathtt{+0.0}$ and $e = \mathtt{+0.0}$.
    \item $e_x - (p - 1) \le e_s \le e_x - 1$ and $e = \mathtt{+0.0}$.
\end{enumerate}

\subsection*{Lemma Family SETZ-I}

Lemma SETZ-I (for ``identical'') gives necessary and sufficient conditions for the inputs $(x, y)$ to be returned unchanged by $\TwoSum$. This Lemma supports both our SETZ and SELTZO results. \\

\noindent \textbf{Lemma SETZ-I:} Assume $x$ and $y$ are nonzero. $(s, e) = (x, y)$ if and only if any of the following conditions hold:
\begin{enumerate}
    \item $e_x > e_y + (p + 1)$.
    \item $e_x = e_y + (p + 1)$ and any of the following conditions hold: $e_y = f_y$, $s_x = s_y$, or $e_x > f_x$.
    \item $e_x = e_y + p$, $e_y = f_y$, $e_x < f_x + (p - 1)$, and $s_x = s_y$ or $e_x > f_x$.
\end{enumerate}

\subsection*{Lemma Family SETZ-F}

The remaining SETZ lemmas admit simpler statements if we make a change of variables from $(s_x, e_x, \ntz_x)$ to $(s_x, e_x, f_x)$ where $f_x \coloneqq e_x - (p - \ntz_x - 1)$. We call this value the \textit{trailing exponent} of $x$. The trailing exponent is the place value of the last nonzero mantissa bit of $x$; it acts like the dual of $e_x$, bounding the mantissa from below. \\

Lemmas in Family SETZ-F apply to addends with the same trailing exponent (i.e., $f_x = f_y$). These Lemmas support our SETZ results. We assume throughout this Lemma Family that $x$ and $y$ are nonzero. \\

\noindent \textbf{Lemma SETZ-FS0:} If $s_x = s_y$, $f_x = f_y$, and $e_x > e_y + 1$, then one of the following statements holds:
\begin{enumerate}
   \item $s_s = s_x$, $e_s = e_x$, $f_x + 1 \le f_s \le e_x - 1$, and $e = \mathtt{+0.0}$.
   \item $s_s = s_x$, $e_s = e_x + 1$, $f_x + 1 \le f_s \le e_y$, and $e = \mathtt{+0.0}$.
   \item $s_s = s_x$, $e_s = e_x + 1$, $f_s = e_x + 1$, and $e = \mathtt{+0.0}$.
\end{enumerate}

\noindent \textbf{Lemma SETZ-FS1:} If $s_x = s_y$, $f_x = f_y$, and $e_x = e_y + 1$, then one of the following statements holds:
\begin{enumerate}
   \item $s_s = s_x$, $e_s = e_x$, $f_x + 1 \le f_s \le e_x - 2$, and $e = \mathtt{+0.0}$.
   \item $s_s = s_x$, $e_s = e_x + 1$, $f_x + 1 \le f_s \le e_y$, and $e = \mathtt{+0.0}$.
   \item $s_s = s_x$, $e_s = e_x + 1$, $f_s = e_x + 1$, and $e = \mathtt{+0.0}$.
\end{enumerate}

\noindent \textbf{Lemma SETZ-FS2:} If $s_x = s_y$, $f_x = f_y$, $e_x = e_y$, and $e_x > f_x$, then one of the following statements holds:
\begin{enumerate}
   \item $s_s = s_x$, $e_s = e_x + 1$, $f_x + 1 \le f_s \le e_x$, and $e = \mathtt{+0.0}$.
\end{enumerate}

\noindent \textbf{Lemma SETZ-FS3:} If $s_x = s_y$, $f_x = f_y$, $e_x = e_y$, and $e_x = f_x$, then one of the following statements holds:
\begin{enumerate}
   \item $s_s = s_x$, $e_s = e_x + 1$, $f_s = e_x + 1$, and $e = \mathtt{+0.0}$.
\end{enumerate}

\noindent \textbf{Lemma SETZ-FD0:} If $s_x \ne s_y$, $f_x = f_y$, and $e_x > e_y + 1$, then one of the following statements holds:
\begin{enumerate}
   \item $s_s = s_x$, $e_s = e_x - 1$, $f_x + 1 \le f_s \le e_y$, and $e = \mathtt{+0.0}$.
   \item $s_s = s_x$, $e_s = e_x$, $f_x + 1 \le f_s \le e_x$, and $e = \mathtt{+0.0}$.
\end{enumerate}

\noindent \textbf{Lemma SETZ-FD1:} If $s_x \ne s_y$, $f_x = f_y$, and $e_x = e_y + 1$, then one of the following statements holds:
\begin{enumerate}
   \item For each $k$ where $f_x + 1 \le k \le e_x - 1$: $s_s = s_x$, $e_s = k$, $f_x + 1 \le f_s \le k$, and $e = \mathtt{+0.0}$.
   \item $s_s = s_x$, $e_s = e_x$, $f_x + 1 \le f_s \le e_x - 2$, and $e = \mathtt{+0.0}$.
   \item $s_s = s_x$, $e_s = e_x$, $f_s = e_x$, and $e = \mathtt{+0.0}$.
\end{enumerate}

\noindent \textbf{Lemma SETZ-FD2:} If $s_x \ne s_y$, $f_x = f_y$, and $e_x = e_y$, then one of the following statements holds:
\begin{enumerate}
   \item $s = \mathtt{+0.0}$ and $e = \mathtt{+0.0}$.
   \item For each $k$ where $f_x + 1 \le k \le e_x - 1$: $f_x + 1 \le f_s \le k$, $e_s = k$, and $e = \mathtt{+0.0}$.
\end{enumerate}

\subsection*{Lemma Family SETZ-E}

Lemmas in Family SETZ-E (for ``exact'') apply to addends with different trailing exponents whose floating-point sum is exact (i.e., $e = \pm\mathtt{0.0}$). These Lemmas support our SETZ results. We assume throughout this Lemma Family that $x$ and $y$ are nonzero. \\

\noindent \textbf{Lemma SETZ-EN0:} If $s_x = s_y$ or $e_x > f_x$, $f_x > e_y$, and $e_x < f_y + p$, then one of the following statements holds:
\begin{enumerate}
   \item $s_s = s_x$, $e_s = e_x$, $f_s = f_y$, and $e = \mathtt{+0.0}$.
\end{enumerate}

\noindent \textbf{Lemma SETZ-EN1:} If $s_x \ne s_y$, and one of the following statements holds:
\begin{enumerate}
    \item $e_x = f_x$, $f_x > e_y + 1$, $e_x < f_y + (p + 1)$
    \item $e_x = f_x + 1$, $f_x = e_y$, $e_y > f_y$
\end{enumerate}
then one of the following statements holds:
\begin{enumerate}
   \item $s_s = s_x$, $e_s = e_x - 1$, $f_s = f_y$, and $e = \mathtt{+0.0}$.
\end{enumerate}

\noindent \textbf{Lemma SETZ-ESP0:} If $s_x = s_y$, either $(e_x > e_y > f_x > f_y)$ or $(e_x > e_y + 1 > f_x > f_y)$, and $e_x < f_y + (p - 1)$, then one of the following statements holds:
\begin{enumerate}
   \item $s_s = s_x$, $e_x \le e_s \le e_x + 1$, $f_s = f_y$, and $e = \mathtt{+0.0}$.
\end{enumerate}

\noindent \textbf{Lemma SETZ-ESP1:} If $s_x = s_y$, $e_x = e_y + 1$, $e_y = f_x > f_y$, and $e_x < f_y + (p - 1)$, then one of the following statements holds:
\begin{enumerate}
   \item $s_s = s_x$, $e_s = e_x + 1$, $f_s = f_y$, and $e = \mathtt{+0.0}$.
\end{enumerate}

\noindent \textbf{Lemma SETZ-ESC:} If $s_x = s_y$, $e_x > e_y$, $f_x < f_y$, and $e_x < f_x + (p - 1)$, then one of the following statements holds:
\begin{enumerate}
   \item $s_s = s_x$, $e_x \le e_s \le e_x + 1$, $f_s = f_x$, and $e = \mathtt{+0.0}$.
\end{enumerate}

\noindent \textbf{Lemma SETZ-ESS:} If $s_x = s_y$, $e_x = e_y$, $f_x < f_y$, $e_x < f_x + (p - 1)$, and $e_y < f_y + (p - 1)$, then one of the following statements holds:
\begin{enumerate}
   \item $s_s = s_x$, $e_s = e_x + 1$, $f_s = f_x$, and $e = \mathtt{+0.0}$.
\end{enumerate}

\noindent \textbf{Lemma SETZ-EDP0:} If $s_x \ne s_y$, $e_x > e_y + 1 > f_x > f_y$, and $e_x < f_y + p$, then one of the following statements holds:
\begin{enumerate}
   \item $s_s = s_x$, $e_x - 1 \le e_s \le e_x$, $f_s = f_y$, and $e = \mathtt{+0.0}$.
\end{enumerate}

\noindent \textbf{Lemma SETZ-EDP1:} If $s_x \ne s_y$, $e_x = e_y + 1$, $e_y > f_x > f_y$, and $e_x < f_y + p$, then one of the following statements holds:
\begin{enumerate}
   \item $s_s = s_x$, $f_x \le e_s \le e_x$, $f_s = f_y$, and $e = \mathtt{+0.0}$.
\end{enumerate}

\noindent \textbf{Lemma SETZ-EDP2:} If $s_x \ne s_y$, $e_x = e_y + 1 = f_x$, and $f_x > f_y + 1$, then one of the following statements holds:
\begin{enumerate}
   \item $s_s = s_x$, $f_y \le e_s \le e_x - 2$, $f_s = f_y$, and $e = \mathtt{+0.0}$.
\end{enumerate}

\noindent \textbf{Lemma SETZ-EDP3:} If $s_x \ne s_y$, $e_x = e_y + 1 = f_x = f_y + 1$, then one of the following statements holds:
\begin{enumerate}
   \item $s_s = s_x$, $f_y \le e_s \le e_x - 1$, $f_s = f_y$, and $e = \mathtt{+0.0}$.
\end{enumerate}

\noindent \textbf{Lemma SETZ-EDC0:} If $s_x \ne s_y$, $e_x > e_y + 1$, and $f_x < f_y$, then one of the following statements holds:
\begin{enumerate}
   \item $s_s = s_x$, $e_x - 1 \le e_s \le e_x$, $f_s = f_x$, and $e = \mathtt{+0.0}$.
\end{enumerate}

\noindent \textbf{Lemma SETZ-EDC1:} If $s_x \ne s_y$, $e_x = e_y + 1$, and $f_x < f_y$, then one of the following statements holds:
\begin{enumerate}
   \item $s_s = s_x$, $f_y \le e_s \le e_x$, $f_s = f_x$, and $e = \mathtt{+0.0}$.
\end{enumerate}

\noindent \textbf{Lemma SETZ-EDC2:} If $s_x \ne s_y$, $e_x = e_y = f_y$, and $f_x < f_y$, then one of the following statements holds:
\begin{enumerate}
   \item $s_s = s_x$, $f_x \le e_s \le e_x - 1$, $f_s = f_x$, and $e = \mathtt{+0.0}$.
