\end{enumerate}

\noindent \textbf{Lemma SETZ-EDS1:} If $s_x \ne s_y$, $e_x = e_y$, $e_x > f_x + 1$, and $e_y = f_y + 1$, then one of the following statements holds:
\begin{enumerate}
   \item $f_x \le e_s \le e_x - 2$, $f_s = f_x$, and $e = \mathtt{+0.0}$.
