\end{enumerate}

\noindent \textbf{Lemma SETZ-1B0:} If $e_x < e_y + (p - 1)$, $e_x = f_y + p$, $f_x > e_y + 1$, and $e_x > f_x$ or $s_x = s_y$, then one of the following statements holds:
