   \item $s_s = s_x$, $e_s = e_x$, $f_s = e_y$, $s_e = s_y$, $f_y \le e_e \le e_x - p$, and $f_e = f_y$.
   \item $s_s = s_x$, $e_s = e_x$, $f_s = e_y + 1$, $s_e \ne s_y$, $f_y \le e_e \le e_x - p$, and $f_e = f_y$.
\end{enumerate}

\noindent \textbf{Lemma SETZ-1B1:} If $e_x = e_y + (p - 1)$, $e_x = f_y + p$, $f_x > e_y + 1$, and $e_x > f_x$ or $s_x = s_y$, then one of the following statements holds:
\begin{enumerate}
   \item $s_s = s_x$, $e_s = e_x$, $f_s = e_y + 1$, $s_e \ne s_y$, $f_y \le e_e \le e_x - p$, and $f_e = f_y$.
\end{enumerate}

\subsection*{Lemma Family SETZ-2}

These Lemmas support both our SETZ and SELTZO results. We assume throughout this Lemma Family that $x$ and $y$ are nonzero. \\

