   \item $s_s = s_x$, $e_s = e_x + 1$, $f_s = e_x + 1$, $s_e \ne s_y$, $f_y \le e_e \le e_x - (p + 1)$, and $f_e = f_y$.
   \item $s_s = s_x$, $e_s = e_x + 1$, $f_s = e_x + 1$, $s_e = s_y$, $f_y \le e_e \le e_x - p$, and $f_e = f_y$.
