   \item $s_s = s_x$, $e_s = e_x$, $e_x - (p - 2) \le f_s \le e_x - 1$, $f_y \le e_e \le e_x - p$, and $f_e = f_y$.
   \item $s_s = s_x$, $e_s = e_x + 1$, $e_x - (p - 2) \le f_s \le e_y$, $f_y \le e_e \le e_x - p$, and $f_e = f_y$.
