   \item $s_s = s_x$, $e_s = e_x$, $e_y + 1 \le f_s \le e_x - 1$, $s_e = s_y$, $f_y \le e_e \le e_x - p$, and $f_e = f_y$.
\end{enumerate}

\noindent \textbf{Lemma SETZ-3BC1:} If $s_x \ne s_y$, $e_x = f_y + p$, $f_x = e_y$, and $e_y = f_y + 1$, then one of the following statements holds:
\begin{enumerate}
   \item $s_s = s_x$, $e_s = e_x - 1$, $f_s = f_y$, and $e = \mathtt{+0.0}$.
   \item $s_s = s_x$, $e_s = e_x$, $e_y + 1 \le f_s \le e_x - 1$, $s_e = s_y$, $f_y \le e_e \le e_x - p$, and $f_e = f_y$.
\end{enumerate}

\noindent \textbf{Lemma SETZ-3CD0:} If $s_x \ne s_y$, $e_x = f_y + p$, $f_x = e_y + 1$, $e_x > f_x$, and $e_y > f_y + 1$, then one of the following statements holds:
\begin{enumerate}
   \item $s_s = s_x$, $e_s = e_x$, $e_x - (p - 2) \le f_s \le e_y - 1$, $f_y \le e_e \le e_x - p$, and $f_e = f_y$.
   \item $s_s = s_x$, $e_s = e_x$, $f_s = e_y$, $s_e = s_y$, $f_y \le e_e \le e_x - p$, and $f_e = f_y$.
   \item $s_s = s_x$, $e_s = e_x$, $e_y + 2 \le f_s \le e_x$, $s_e \ne s_y$, $f_y \le e_e \le e_x - p$, and $f_e = f_y$.
\end{enumerate}

\noindent \textbf{Lemma SETZ-3CD1:} If $s_x \ne s_y$, $e_x = f_y + p$, $f_x = e_y + 1$, and $e_y < f_y + 2$, then one of the following statements holds:
\begin{enumerate}
   \item $s_s = s_x$, $e_s = e_x$, $e_y + 2 \le f_s \le e_x$, $s_e \ne s_y$, $f_y \le e_e \le e_x - p$, and $f_e = f_y$.
\end{enumerate}

\subsection*{Lemma Family SETZ-4}

These Lemmas support both our SETZ and SELTZO results. We assume throughout this Lemma Family that $x$ and $y$ are nonzero. \\

\noindent \textbf{Lemma SETZ-4:} If $s_x \ne s_y$, $e_x > f_y + (p + 1)$, $f_x < e_y + (p + 1)$, and $e_x = f_x$, then one of the following statements holds:
\begin{enumerate}
    \item $s_s = s_x$, $e_s = e_x - 1$, $e_x - p \le f_s \le e_y - 1$, $f_y \le e_e \le e_x - (p + 2)$, and $f_e = f_y$.
    \item $s_s = s_x$, $e_s = e_x - 1$, $f_s = e_y$, $s_e = s_y$, $f_y \le e_e \le e_x - (p + 2)$, and $f_e = f_y$.
    \item $s_s = s_x$, $e_s = e_x - 1$, $f_y + 1$, $s_e \ne s_y$, $f_y \le e_e \le e_x - (p + 2)$, and $f_e = f_y$.
\end{enumerate}

\noindent \textbf{Lemma SETZ-4A0:} If $s_x \ne s_y$, $e_x = f_y + (p + 1)$, $f_x < e_y + p$, and $e_x = f_x$, then one of the following statements holds:
\begin{enumerate}
    \item $s_s = s_x$, $e_s = e_x - 1$, $e_x - (p - 1) \le f_s \le e_y - 1$, $f_y \le e_e \le e_x - (p + 1)$, and $f_e = f_y$.
    \item $s_s = s_x$, $e_s = e_x - 1$, $f_s = e_y$, $s_e = s_y$, $f_y \le e_e \le e_x - (p + 1)$, and $f_e = f_y$.
    \item $s_s = s_x$, $e_s = e_x - 1$, $f_s = e_y + 1$, $s_e \ne s_y$, $f_y \le e_e \le e_x - (p + 1)$, and $f_e = f_y$.
\end{enumerate}

\noindent \textbf{Lemma SETZ-4A1:} If $s_x \ne s_y$, $e_x = f_y + (p + 1)$, $f_x = e_y + p$, and $e_x = f_x$, then one of the following statements holds:
\begin{enumerate}
    \item $s_s = s_x$, $e_s = e_x - 1$, $e_x - (p - 1) \le f_s \le e_y + 1$, $s_e \ne s_y$, $f_y \le e_e \le e_x - (p + 1)$, and $f_e = f_y$.
\end{enumerate}

\noindent \textbf{Lemma SETZ-4B:} If $s_x \ne s_y$, $e_x > f_y + (p + 1)$, $f_x = e_y + (p + 1)$, and $e_x = f_x$, then one of the following statements holds:
\begin{enumerate}
    \item $s_s = s_x$, $e_s = e_x - 1$, $e_x - p \le f_s \le e_y + 1$, $s_e \ne s_y$, $f_y \le e_e \le e_x - (p + 2)$, and $f_e = f_y$.
\end{enumerate}

