\begin{remark}
    The choice of the number of subsequences $P$ and the number of subsequences of different regularity scores $r$ depend on the context and goals of the analysis. To reconstruct an $(M+1)$-dimensional state space, subsequences must satisfy $n_p > \max(M+1, M*\tau_p)$. A set of subsequences with the same regularity score can lead to better reconstruction accuracy as it captures the dominant patterns of the underlying data-generating space of the time series more coherently. Combining subsequences with different regularity scores can improve topological approximations as it captures a wider range of structures of the underlying data-generating space. Thus, there is a trade-off between a better topology approximation and improved reconstruction accuracy. If subsequences with the same regularity score capture most of the time series, combining sequences with different regularity scores may offer limited benefits. While the simulations and real data analysis in this work utilize subsequences with the same regularity score, the methodology and theoretical results apply to subsequences with the same or different regularity scores.
    \label{rmk:number-ps}
\end{remark}

\section{Stability and Convergence Results}
\label{sec:stability-convergence-results}
The reconstructed state space using the proposed SSE is an estimate of the ``true'' state space based on a uniformly-sampled time series (i.e., the TDE space). Persistence diagrams are used to quantify the stability of the estimate by measuring its closeness to the true state space.  The results are stated below, and the proofs are included in the supplementary materials Section~\ref{sec:supp_proofs}.



\subsection{Stability Theory in Persistence Homology}

The set of persistence diagrams from the true state space (TDE) and the reconstructed state space (SSE) can be endowed with a distance measure, such as the popular bottleneck distance. The bottleneck distance gives the minimal bijection between any two diagrams as a measure of the distance between the diagrams. Let $\mathbf{F}^1$ and $\mathbf{F}^2$ be two  finite compact subsets of $\mathbb{R}^{M+1}$, with $\text{Dgm}(\mathbf{F}^1)$ and $\text{Dgm}(\mathbf{F}^2)$ as their corresponding persistence diagrams. The bottleneck distance, $\text{d}_\text{B}$, between the two persistence diagrams is defined as 
\begin{equation}
    \text{d}_\text{B}\left(\text{Dgm}(\mathbf{F}^1), \text{Dgm}(\mathbf{F}^2)\right) = \inf_{\gamma} \sup_{\mu \in \text{Dgm}(\mathbf{F}^1)} || \mu - \gamma(\mu) ||_\infty,
    \label{eqn:bottleneck-dist}
\end{equation}
where the infimum is taken over all bijections $\gamma: \text{Dgm}(\mathbf{F}^1) \xrightarrow{} \text{Dgm}(\mathbf{F}^2)$. For the metric space $(\mathbb{R}^{M+1},  \lVert \cdot \rVert_2)$, where $\lVert \cdot \rVert_2$ denotes the $l^2$-norm, define the distance function as: $d(F, \mathbf{F}^1) = \inf_{F^1 \in \mathbf{F}^1} \lVert F - F^1 \rVert_2,$ $\forall F \in \mathbb{R}^{M+1}.$
% \begin{equation}
%     d(F, \mathbf{F}^1) = \inf_{F^1 \in \mathbf{F}^1} \lVert F - F^1 \rVert_2, \quad \forall F \in \mathbb{R}^{M+1}.
%     \label{eqn:dist-function}
%\end{equation}
Then the Hausdorff distance, $d_H$, is given by
%
\begin{equation}
    d_H(\mathbf{F}^1, \mathbf{F}^2) = \max \left\{ \sup_{F^1 \in \mathbf{F}^1 }d(F^1, \mathbf{F}^2), \sup_{F^2 \in \mathbf{F}^2 }d(F^2, \mathbf{F}^1)\right\}.
    \label{eqn:dist-hausdorff}
\end{equation}
The Hausdorff distance quantifies the level to which two metric spaces represent the same object. A modification of the Hausdorff distance that is blind to isometric transformations is the Gromov-Hausdorff distance. Let $\nu_1: \mathbf{F}^1 \hookrightarrow \mathbb{R}^{M+1}$ and $\nu_2: \mathbf{F}^2 \hookrightarrow \mathbb{R}^{M+1}$ be isometric (distance preserving) embeddings into the metric space $(\mathbb{R}^{M+1}, \lVert \cdot \rVert_2)$. Then the Gromov-Hausdorff distance between $\mathbf{F}^1$ and $\mathbf{F}^2$ is given by: $ d_{GH}(\mathbf{F}^1, \mathbf{F}^2) = \inf_{\nu_1, \nu_2}d_H(\nu_1(\mathbf{F}^1), \nu_2(\mathbf{F}^2))$.
%\begin{equation}
%    d_{GH}(\mathbf{F}^1, \mathbf{F}^2) = \inf_{\nu_1, \nu_2}d_H(\nu_1(\mathbf{F}^1), \nu_2(\mathbf{F}^2)).
%    \label{eqn:dist-gh}
%\end{equation}
A fundamental result on persistence diagrams is that they are stable summaries in many settings (i.e., a small change in a point cloud result in a small change in the corresponding persistence diagram) \citep{chazal2021introduction}. The stability relation of the persistence diagrams is stated as 
\begin{equation}
    \text{d}_\text{B}\left(\text{Dgm}(\mathbf{F}^1), \text{Dgm}(\mathbf{F}^2)\right) \le 2 \text{d}_{\text{GH}}(\mathbf{F}^1, \mathbf{F}^2) \le 2\text{d}_{\text{H}}(\mathbf{F}^1, \mathbf{F}^2).
    \label{eqn:stability-bn}
\end{equation}
In what follows, these stability results are established for the proposed SSE method and a denoising procedure to reduce the noise present in the observed time series.



\subsection{Stability of Denoising Procedure} \label{sec:denoise}

Time-series data is typically observed with noise. The level of noise in the reconstructed space influences the presence and the persistence of the topological features. A Fourier denoising procedure is proposed to filter out noise in the observed time series. 



Let $\mathbf{x} = \begin{bmatrix}x(t_1), & x(t_2), & \cdots &, x(t_n) \end{bmatrix}^\top$ be an observed time series vector. The first step in the denoising procedure is to transform this observed signal to the frequency domain. The discrete Fourier transform (DFT)  of $x(t_{k})$, denoted as $\Tilde{x}(t_{k})$ is given by
%
\begin{equation}
    \Tilde{x}(t_{k}) = \sum_{r = 1}^{n} x(t_{r})e^{-j2\pi w_rf_{k}} =  \sum_{r = 1}^{n} x(t_{r}){\phi}_{kr}, \quad 1 \le k \le n,
    \label{eqn:dft-formal}
\end{equation}
%
where $j$ is the imaginary unit ($j^2 = -1$), $\phi_{kr} = e^{-j2\pi w_r f_{k}}$, $0 \le w_r \le 1$ are sample points, $0 \le f_{k} \le n$ are frequencies, and  $\Tilde{x}(t_{k})$ is the $k$-th sample of the power spectrum at $f_{k}$. 

To filter out noise, the power spectral density is computed for each observation $\tilde{x}(t_k)$. Then a threshold is chosen, and any $\tilde{x}(t_k)$ with power spectral density less than the threshold is set to zero. In selecting the threshold, the goal is to choose a value that does not smooth out the peaks in the true signal. The derivation that follows assumes the selected threshold preserves the peaks in the true signal.
To simplify notations, the thresholded observations are also denoted as $\tilde{x}(t_k)$. The thresholded $\tilde{x}(t_k)$ are transformed back to the time domain to get the noise-reduced signal. which typically involves multiplying $\tilde{x}(t_k)$ by the inverse of a Fourier transform matrix.

Let $\Tilde{\mathbf{x}}$ be the DFT of the time series vector with corresponding Fourier basis $\boldsymbol{\phi}_k$,  where
\begin{equation}
\Tilde{\mathbf{x}} = \begin{bmatrix} \Tilde{x}(t_{1}), & \Tilde{x}(t_{2}), & \cdots, & \Tilde{x}(t_{n}) \end{bmatrix}^\top,  
\boldsymbol{\phi}_k = \begin{bmatrix}\phi_{k1}, & \phi_{k2}, & \cdots, & \phi_{kn} \end{bmatrix}^\top, k=1, \ldots, n.
\label{eqn:inv-dft-coef}
\end{equation}
The forward transform in Equation~\eqref{eqn:dft-formal} can be vectorized: %$
%\mathbf{\Tilde{x}} = \boldsymbol{\Phi} \mathbf{x}$, where $
%\boldsymbol{\Phi} = \begin{bmatrix} \boldsymbol{\phi}_1  &  \boldsymbol{\phi}_2 & \cdots & \boldsymbol{\phi}_{n}  \end{bmatrix}^\top.$
\begin{equation}
    \mathbf{\Tilde{x}} = \boldsymbol{\Phi} \mathbf{x}, \quad
    \boldsymbol{\Phi} = \begin{bmatrix} \boldsymbol{\phi}_1  &  \boldsymbol{\phi}_2 & \cdots & \boldsymbol{\phi}_{n}  \end{bmatrix}^\top.
\end{equation}
The backward transform can then be determined by inverting the matrix $\boldsymbol{\Phi}$. However, due to the non-uniformity in the spacing of the time series $\mathbf{x}$, the columns of $\boldsymbol{\Phi}$ are not orthogonal, and it is not directly invertible, so the pseudo-inverse is used instead. The backward transform then has the form: $\mathbf{x} = \frac{1}{n} (\boldsymbol{\Phi}^H\boldsymbol{\Phi})^\dagger \boldsymbol{\Phi}^H \Tilde{\mathbf{x}}$,
%
%\begin{equation}
%    \mathbf{x} = \frac{1}{n} (\boldsymbol{\Phi}^H\boldsymbol{\Phi})^\dagger \boldsymbol{\Phi}^H \Tilde{\mathbf{x}},
%    \label{eqn:back-trans}
%\end{equation}
%
where $\mathbf{A}^H$ and $\mathbf{A}^\dagger$ denote the complex conjugate transpose and the Moore-Penrose inverse of the matrix $\mathbf{A}$, respectively. 
The matrix $(\boldsymbol{\Phi}^H\boldsymbol{\Phi})^\dagger\boldsymbol{\Phi}^H$ projects the frequency vector $\mathbf{\Tilde{x}}$ onto the column space of $\boldsymbol{\Phi}$.  
%
Let $\Pi_{\boldsymbol{\Phi}}(\mathbf{x})$ denote this projection operation. 
The modulus of off-diagonal elements of $\boldsymbol{\Phi}^H\boldsymbol{\Phi}$ is bounded as: $\left|\sum_{k = 1}^n e^{j 2\pi (w_{l_1} - w_{l_2})f_k}\right|
    \le \sum_{k = 1}^n \left| e^{j 2\pi (w_{l_1} - w_{l_2})f_k}\right| = n$,
%\begin{equation}
%    \left|\sum_{k = 1}^n e^{j 2\pi (w_{l_1} - w_{l_2})f_k}\right|
%    \le \sum_{k = 1}^n \left| e^{j 2\pi (w_{l_1} - w_{l_2})f_k}\right| = n,
%    \label{eqn:modulus-bound}
%\end{equation}
where the equality follows from the definition of the complex modulus $|{z}| = \sqrt{{z}\bar{z}}$, with $\bar{z}$ as the conjugate of the complex value $z$. The matrix $\boldsymbol{\Phi}\boldsymbol{\Phi}^H$ has the structure
\begin{equation}
    (\boldsymbol{\Phi}\boldsymbol{\Phi}^H)_{l_1, l_2} = \sum_{k = 1}^n e^{ (-1)^\delta j2\pi (f_{l_2} - f_{l_1})w_k}, \quad \delta = \mathbbm{1}(l_1 \le l_2),
    \label{eqn:toeplitz-form}
\end{equation}
for indicator function $\mathbbm{1}(l_1 \le l_2)$ , and $(\boldsymbol{\Phi}\boldsymbol{\Phi})^H_{l_1,l_2}$ denotes the value in the $l_1$-th row and $l_2$-th column of $\boldsymbol{\Phi} \boldsymbol{\Phi}^H$.
Then $\boldsymbol{\Phi}\boldsymbol{\Phi}^H$ is Toeplitz when the frequency components are uniformly-spaced such that $f_k = k$, and $\boldsymbol{\Phi}\boldsymbol{\Phi}^H$ is fully specified by its first row elements \citep{huoliu1998iterative}. 
 %

Using these results, the following proposition asserts that the DFT preserves topological features and is stable with respect to the bottleneck distance. In particular, the bottleneck distance between the persistence diagrams of the embeddings of the noise-free and smoothed (i.e., noise-reduced) time series is bounded above by the embeddings of the observed noisy and noise-free time series.
%
\begin{proposition}
Given $\mathbf{x}^* \in \mathbb{R}^n$ as a possibly irregularly-spaced scalar time series with additive noise of the form $\mathbf{x}^* = \mathbf{x} + \mathbf{\varepsilon}$, where $\mathbf{x}$ is a noise-free scalar time series, and $\varepsilon$ is a zero-mean noise term, then let $\mathbf{x}^\prime$ be the time series vector after applying the proposed Fourier denoising to $\mathbf{x}^*$, and $\mathbf{F}$, $\mathbf{F}^*$, and  $\mathbf{F}^\prime$ be the embedding matrices associated with $\mathbf{x}$, $\mathbf{x}^*$, and $\mathbf{x}^\prime$, respectively. Also, let $\text{Dgm}(\mathbf{F})$ and $\text{Dgm}({\mathbf{F}^\prime})$ denote the persistence diagrams associated with the Vietoris-Rips complex constructed from $\mathbf{F}$ and $\mathbf{F}^\prime$, respectively. Then the bottleneck distance between these two persistence diagrams is bounded as
\begin{equation}
    \text{d}_\text{B}(\text{Dgm}({\mathbf{F}}), \text{Dgm}({\mathbf{F}^\prime})) \le \frac{4n - 2}{\gamma}\left(\sup\limits_{i, p}||F^*(\mathbf{s}(t_{p, i})) - F(\mathbf{s}(t_{p, i}))||_2\right),
\label{eqn:stable-denoising}
\end{equation}
where $0 < \gamma \le 1, \quad 1 \le i \le n_p - M\tau_p, \quad 1 \le p \le P.$
\label{prop:stable-denoising}
\end{proposition}
%
%
\begin{remark}
 When the samples are uniformly-spaced in both the time and frequency domain, the matrix $\boldsymbol{\Phi}$ is Hermitian with orthogonal columns, hence the factor $({2n - 1})/{\gamma}$ $(\text{not } ({4n - 2})/{\gamma}$, as the scaling by $2$ is still required$)$ is not required for the bound to hold. The factor $({2n - 1})/{\gamma}$ makes the bound conservative. However, if the denoising is well constructed, this has minimal impact on the scale of the bound. Numerical experiments in the supplementary materials Section~\ref{sec:denoising-simulation} suggest this is the case for the settings considered.
\end{remark}

\subsection{Stability of the Subsequence Embedding Method}
In this section, an error bound and stability results for the SSE approximation of the TDE are established. To simplify the notation, the embedding matrices are represented as sets where the elements of the set are the row vectors of the corresponding TDE or SSE. Also, for an embedding from a single uniformly-spaced time series, the step-size is assumed to be $\tau$. When constructing from a set of $P$ subsequences, a step-size of $\tau_p$ is assumed for the $p$-th subsequence, where $1 \le p \le P$. 


Because the SSE can have fewer elements than the TDE, the following lemma addresses how to expand the SSE without affecting its topology by repeating already existing points in the SSE, so distances can be computed between the TDE and the expanded SSE.
\begin{lemma}[Topology-preserving transform]
    Let $\mathbf{F}^1$ be an embedding matrix from a uniformly-spaced time sequence of length $n$ with the form: %$\mathbf{F}^1= \left\{F^1(\mathbf{s}(t_{1})), F^1(\mathbf{s}(t_{2})), \cdots, F^1(\mathbf{s}(t_{n - M\tau}))  \right\} \subset \mathbb{R}^{M+1}.$
    \begin{equation}
        \mathbf{F}^1= \left\{F^1(\mathbf{s}(t_{1})), F^1(\mathbf{s}(t_{2})), \cdots, F^1(\mathbf{s}(t_{n - M\tau}))  \right\} \subset \mathbb{R}^{M+1}.
    \end{equation}
    Also, let $\mathbf{F}^2$ be an embedding matrix from a set of $P$ subsequences with the form:
    \begin{equation}
        \mathbf{F}^2 = \left\{F^2(\mathbf{s}(t_{1, 1})), \cdots, F^2(\mathbf{s}(t_{1, n_1-M\tau_1})), \cdots, F^2(\mathbf{s}(t_{P, 1}), \cdots, F^2(\mathbf{s}(t_{P, n_P - M\tau_P}))  \right\} \subset \mathbb{R}^{M+1},
    \end{equation}
    where $\sum_{p = 1}^P (n_p - M\tau_p) \le n - M\tau$. Consider the set extension $\widehat{\mathbf{F}}^2 = \left\{ \mathbf{F}^2, {\mathbf{F}}^2_k \right\}$, where ${\mathbf{F}}^2_k$ is a subset of $k$ elements from $\mathbf{F}^2$. Then the persistence diagrams associated with $\mathbf{F}^2$ and $\widehat{\mathbf{F}}^2$ are identical, that is,  $\text{Dgm}(\mathbf{F}^2) \equiv \text{Dgm}(\widehat{\mathbf{F}}^2)$, and the three embedded spaces are related through the bottleneck distance as follows: $\text{d}_\text{B}(\text{Dgm}(\mathbf{F}^1), \text{Dgm}(\mathbf{F}^2)) = \text{d}_\text{B}(\text{Dgm}(\mathbf{F}^1), \text{Dgm}(\widehat{\mathbf{F}}^2)).$
    %\begin{equation}
    %    \text{d}_\text{B}(\text{Dgm}(\mathbf{F}^1), \text{Dgm}(\mathbf{F}^2)) = \text{d}_\text{B}(\text{Dgm}(\mathbf{F}^1), \text{Dgm}(\widehat{\mathbf{F}}^2)).
    %\end{equation}
    \label{lem:equivalence}
\end{lemma}
%


Lemma \ref{lem:equivalence} asserts that a particular set of points can be added to an embedding matrix without changing the SSE's persistence diagram. This is used to establish a bound on the SSE as an approximation to the TDE in the following proposition. In Lemma \ref{lem:equivalence}, when $k = (n - M\tau) - \sum_{p = 1}^P (n_p - M\tau_p)$, the row dimension of $\widehat{\mathbf{F}}^2$ is the same as that of $\mathbf{F}^1$. In such instances, when the interest is in a row-wise comparison of $\widehat{\mathbf{F}}^2$ and $\mathbf{F}^1$ the subsequence indexing in the time variable for any $\widehat{F}^2(\mathbf{s}(t_{p, i})) \in \widehat{\mathbf{F}}^2$ is ignored and a row is simply written as $\widehat{F}^2(\mathbf{s}(t_{i}))$, where $1 \le i \le n - M \tau$. 
%
\begin{proposition}
    Let $\mathbf{x}^1 $ be a uniformly-spaced time series vector of length $n$ with TDE matrix $\mathbf{F}^1$. Let $\mathbf{x}^2 \subset \mathbf{x}^1$ be a time series vector where some of the elements are missing or unobserved. Denote the SSE matrix constructed from $\mathbf{x}^2$ as $\mathbf{F}^2$. Define the extension $\widehat{\mathbf{F}}^2 = \left\{ \mathbf{F}^2, {\mathbf{F}}^2_k \right\}$, where ${\mathbf{F}}^2_k$ is a subset of $k = (n - M\tau) - \sum_{p = 1}^P (n_p - M\tau_p)$ elements from $\mathbf{F}^2$. Then the bottleneck distance between $\mathbf{F}^1$ and $\mathbf{F}^2$ is bounded as: $\text{d}_{\text{B}}( \text{Dgm}(\mathbf{F}^1), \text{Dgm}(\mathbf{F}^2) ) \le 2\sup\limits_{1 \le i \le n - M\tau}\lVert F^1(\mathbf{s}(t_i)) - \widehat{F}^2(\mathbf{s}(t_i))\rVert_2.$
    %\begin{equation}
     %   \text{d}_{\text{B}}( \text{Dgm}(\mathbf{F}^1), \text{Dgm}(\mathbf{F}^2) ) \le 2\sup\limits_{1 \le i \le n - M\tau}\lVert F^1(\mathbf{s}(t_i)) - \widehat{F}^2(\mathbf{s}(t_i))\rVert_2.
    %\end{equation}
    \label{prop:stability-embed}
\end{proposition}
\noindent
The choice of the $k$ subsets of embedding vectors $\mathbf{F}^2_k$ in Proposition \ref{prop:stability-embed} is arbitrary as any subset satisfies the bound. However, since they are chosen to match the subset $\{ \mathbf{F}^\prime (\mathbf{s}_{t_l}): \sum_{p = 1}^P (n_p - M\tau_p) + 1 \le l \le  n- M\tau \}$ of $\mathbf{F}^1$, the bound can be improved. The minimum bound can be attained by choosing a subset in $\mathbf{F}^2$ that has the smallest Euclidean distance to the subset $\{ \mathbf{F}^\prime (\mathbf{s}_{t_l}): \sum_{p = 1}^P (n_p - M\tau_p) +1 \le l \le  n- M\tau \}$. This is summarized as a corollary below. 
\begin{corollary}
    Let $\mathbf{x}^1 $ be a uniformly spaced time series vector of length $n$ with TDE matrix $\mathbf{F}^1$.  Let $\mathbf{x}^2 \subset \mathbf{x}^1$ be a time series vector where some of the elements are unobserved, and $\mathbf{F}^2$ its SSE matrix. Define the extension $\widehat{\mathbf{F}}^2 = \left\{ \mathbf{F}^2, {\mathbf{F}}^2_k \right\}$, where ${\mathbf{F}}^2_k$ is a random subset of $k = (n - M\tau) - \sum_{p = 1}^P (n_p - M\tau_p)$ elements from $\mathbf{F}^2$. For some $F^1 \in \mathbf{F}^1$, define the set ${\mathbf{F}}^2_{k, \text{min}}$ as follows:
   \begin{equation}
    {\mathbf{F}}^2_{k, \text{min}} = \left\{ F^2_\text{min} \in \mathbf{F}^2: \lVert F^2_\text{min} - F^1 \rVert_2 \le \lVert F^2- F^1 \rVert_2, \forall F^2 \in \mathbf{F}^2, \text{ s.t. } {F}^2_\text{min} \ne {F}^2\right\}.
  \end{equation}
    That is, ${\mathbf{F}}^2_{k, \text{min}}$ is a subset of $k$ embedding vectors in $\mathbf{F}^2$ with minimum distance to some points in $\mathbf{F}^1$. Let $\widehat{\mathbf{F}}^2_{\text{min}} = \left\{ \mathbf{F}^2, {\mathbf{F}}^2_{k, \text{min}} \right\}$, then it follows that
    \begin{equation}
        \sup\limits_{1 \le i \le n}\lVert F^1(\mathbf{s}(t_i)) - \widehat{F}^2_\text{min}(\mathbf{s}(t_i))\rVert_2 \le \sup\limits_{1 \le i \le n}\lVert F^1(\mathbf{s}(t_i)) - \widehat{F}^2(\mathbf{s}(t_i))\rVert_2,
    \end{equation}
    where $F^1(\mathbf{s}(t_i)) \in \mathbf{F}^1$, $\widehat{F}^2(\mathbf{s}(t_i)) \in \widehat{\mathbf{F}}^2$, and $\widehat{F}^2_\text{min}(\mathbf{s}(t_i)) \in \widehat{\mathbf{F}}^2_\text{min}$.
    \label{corr:stability-embed-corr}
\end{corollary}

\noindent
An immediate consequence of Proposition \ref{prop:stability-embed} and Corollary \ref{corr:stability-embed-corr} is that the SSE matrix approximates the TDE for varying level of regularity. In particular, for a time series $\mathbf{x} = \{ x(t): t \in \mathcal{T}\}$, and $\mathcal{T} = \{ t_1, \cdots, t_n \} \subset \mathbb{N}$, the sequence of embedding matrices for each $r$ where $1 \le r \le t_n - t_1$ is finite. Hence for a fixed $n$, the limiting persistence diagram as $r \xrightarrow[]{} 1$ is close to the TDE's persistence diagram. If $r = 1$, the SSE is exactly the same as the TDE, and the persistence diagrams would be identical. This reinforces the fact that the proposed reconstruction preserves the topological structures more accurately as the level of irregularity in the observed time series decreases. A more formal treatment of these observations is presented next.

\subsection{Convergence Results}
Throughout this section, it is assumed that the number of missing values increases at a slower rate than the sample size of the time series. Specifically, the missing values grows at a rate of $o(\log m)$, for sample size $m$. This assumption and others are formalized as follows.

Let $\mathbf{x}_1, \mathbf{x}_2, \cdots,$ be irregularly-spaced time series vectors where  $|\mathbf{x}_i| < |\mathbf{x}_j|$, $i < j$. Denote by $\mathbf{F}_m$, the SSE associated with $\mathbf{x} \in \{ \mathbf{x}_1, \mathbf{x}_2, \cdots, \}$, i.e., %$\mathbf{F}_m = \left\{F(\mathbf{s}(t_{1})), F(\mathbf{s}(t_{2})), \cdots, F(\mathbf{s}(t_{m}))  \right\}$.
\begin{equation}
\mathbf{F}_m = \left\{F(\mathbf{s}(t_{1})), F(\mathbf{s}(t_{2})), \cdots, F(\mathbf{s}(t_{m}))  \right\}.
\end{equation}
Note the correspondence between the subscript $m$ and the number of points in $\mathbf{F}_m$. $\mathbf{F}_m$ depends on which time series is selected; however, indexing over this selection is not needed for the following results. 
Recall that $\mathbf{F}_m$ is a compact subset of $(\mathbb{R}^{M+1}, \lVert \cdot \rVert_2)$. Let the space $(\mathbb{R}^{M+1}, \lVert \cdot \rVert_2)$ be endowed with the unknown probability measure $\vartheta$ such that the set of $m$ time points are randomly sampled according to $\vartheta$. Let $\vartheta$ be supported on an embedding $\mathbf{F}_\vartheta$, and let $\varphi$ be the associated density function. 
Consider the following set of assumptions.
%
\begin{itemize}
    \item[\textbf{A1.}] The sample size increases such that $\mathbf{x}_i \subset \mathbf{x}_j$ whenever $i < j$.
    \item[\textbf{A2.}] Let $\varepsilon_m(r)$ be a function of $m$ and the regularity score $r$ such that $\varepsilon_m(1) \xrightarrow{} 0$ as $m \xrightarrow{} \infty$. 
    \item[\textbf{A3.}] For any point $F_\vartheta \in \mathbf{F}_\vartheta$, $\vartheta(B(F_\vartheta, \delta)) \ge \min(\kappa\delta^{M+1}, 1)$, where $B(F_\vartheta, \delta)$ is a closed ball of radius $\delta > 0$ around $F_\vartheta$, with constant $\kappa>0$.
    \item[\textbf{A4.}] It is possible to create joint distributions based on the marginals of $\mathbf{F}_m$ that satisfy
    $$
    \sup_{\mathbf{F}_m} \left| \frac{\varphi\left(F(\mathbf{s}(t_{1})), \cdots, F(\mathbf{s}(t_{m})) \right) - \varphi\left(F(\mathbf{s}(t_{1}))\right)\times \cdots\times \varphi\left(F(\mathbf{s}(t_{m}))\right) }{\varphi\left(F(\mathbf{s}(t_{1}))\right) \times  \cdots \times \varphi\left(F(\mathbf{s}(t_{m}))\right)} \right| \le \eta_m,
    $$
    where $\eta_m$ is such that $\sum_{m = 1}^\infty \frac{\eta_m}{m^\beta\log(m)} < \infty$ for any $\beta > 1$. 
\end{itemize}
%
Assumption \textbf{A4} is to address the possible lack of independence of the vectors in $\mathbf{F}_m$. Under this assumption, the dependence can be controlled and the vectors in $\mathbf{F}_m$ are regarded as the so-called $\eta_m$-almost independent samples, which allows for $\mathbf{F}_m$ to converge in Hausdorff distance to $\mathbf{F}_\vartheta$ \citep{aaron2017detection,picado2020denoising}.
The SSE matrix $\mathbf{F}_m$ can be regarded as an estimator of $\mathbf{F}_\vartheta$ and convergence results can be established in the context of assumptions \textbf{A1}-\textbf{A4}. These results are analogous to convergence results established on support estimation of $d$-dimensional sets \citep{cuevas2004boundary}, its generalization to metric spaces, and on the space of persistence diagrams \citep{mileyko2011probability,chazal2014convergence}. The following result gives the rate of convergence in estimating $\mathbf{F}_\vartheta$. 
%
\begin{theorem}
    Let $\mathbf{x}_1, \mathbf{x}_2, \cdots,$ be a sequence of irregularly-spaced time series vectors satisfying assumption \textbf{A1}, and  $\mathbf{F}_m = \left\{F(\mathbf{s}(t_{1})), F(\mathbf{s}(t_{2})), \cdots, F(\mathbf{s}(t_{m}))  \right\} \subset \mathbb{R}^{M+1}$ be the SSE associated with some $\mathbf{x} \in \{ \mathbf{x}_1, \mathbf{x}_2, \cdots,\}$, satisfying assumption \textbf{A2}. If the probability measure $\vartheta$ satisfies assumption \textbf{A3} and \textbf{A4}, then with probability one,
    \begin{equation}
        \lim_{m \xrightarrow{}\infty} \sup \left(\varepsilon_m(r)\right)^{-\frac{1}{M+1}} \text{d}_{H}(\mathbf{F}_m, \mathbf{F}_\vartheta) \le K,
    \end{equation}
    where $K$ is a constant  depending on $\kappa$ and the embedding dimension $M+1$.
    \label{prop:hd-conv}
\end{theorem}


From the stability relation in Equation \eqref{eqn:stability-bn}, the Hausdorff metric can be replaced with the Gromov-Hausdorff metric and the results still holds. This also gives a similar convergence results on the space of persistence diagrams with respect to the bottleneck distance and is summarized as:
%
\begin{corollary}
     Let $\mathbf{x}_1, \mathbf{x}_2, \cdots,$ be a sequence of irregularly-spaced time series vectors satisfying assumption \textbf{A1}, and let $\mathbf{F}_m = \left\{F(\mathbf{s}(t_{1})), F(\mathbf{s}(t_{2})), \cdots, F(\mathbf{s}(t_{m}))  \right\} \subset \mathbb{R}^{M+1}$ be the SSE associated with some $\mathbf{x} \in \{ \mathbf{x}_1, \mathbf{x}_2, \cdots,\}$, satisfying assumption \textbf{A2}. If the probability measure $\vartheta$ satisfies assumption \textbf{A3} and \textbf{A4}, then with probability one,
    \begin{equation}
        \lim_{m \xrightarrow{}\infty} \sup \left(\varepsilon_m(r)\right)^{-\frac{1}{M+1}} \text{d}_{B}(\text{Dgm}(\mathbf{F}_m), \text{Dgm}(\mathbf{F}_\vartheta)) \le K,
    \end{equation}
    where $K$ is a a constant  depending on $\kappa$ and the embedding dimension $M+1$.
    \label{eqn:bn-conv}
\end{corollary}



