\section{Stability and Convergence Results} \label{sec:supp_proofs}

\subsection{Proof of Proposition 4.1}

\begin{proof}
It suffices to bound the Hausdorff distance between $\mathbf{F}$ and $\mathbf{F}^\prime$, then using  the stability theory in persistence homology \citep{chazal2021introduction}, the bound on their persistence diagrams with respect to the Bottleneck distance can be established. The proof proceeds as follows.

There exists a subset $\mathbf{x}_i^* \subset \mathbf{x}^*$ that exactly equals $F^*(\mathbf{s}(t_{p, i}))$ (the $i$-th row of the $p$-th subsequence of the embedding matrix $\mathbf{F}^*$).  This fact stems from the construction of $\mathbf{F}^*$, whose rows are uniformly-spaced samples of $\mathbf{x}^*$. The same guarantee holds for the pairs $(\mathbf{F}, \mathbf{x})$, and $(\mathbf{F}^\prime, \mathbf{x}^\prime)$.
The distance between the projection $\Pi_{\mathbf{\boldsymbol{\Phi}}}(\mathbf{x}_i^*)$ and $F(\mathbf{s}(t_{p, i}))$ is given by
\begin{equation}
    \lVert \Pi_{\mathbf{\boldsymbol{\Phi}}}(\mathbf{x}_i^*) -  F(\mathbf{s}(t_{p, i})) \rVert_2 = \lVert \Pi_{\mathbf{\boldsymbol{\Phi}}} \left( \mathbf{x}_i^* - F(\mathbf{s}(t_{p, i})) \right) \rVert_2,
    \label{eqn:init-dist}
\end{equation}
where $\lVert \cdot \rVert_2$ denotes the $l^2$-norm. Equation~\eqref{eqn:init-dist} is under the assumption that the choice of frequency threshold does not smooth out the peaks in the true signal $\mathbf{x}$.
Observe that each $F^\prime(\mathbf{s}(t_{p, i}))$ is isometric to $\Pi_{\boldsymbol{\Phi}}(\mathbf{x}^*_{i})$,  where $\mathbf{x}^*_{i}$ is a subset of length $M+1$ of the original noisy scalar time series.
Then the Gromov-Hausdorff distance between $\mathbf{F}^\prime$ and $\mathbf{F}$ can be expressed as
\begin{equation}
    \text{d}_{\text{GH}}\left( \mathbf{F}^\prime, \mathbf{F} \right)  =  \text{d}_{\text{GH}}\left( \widehat{\Pi}_{\boldsymbol{\Phi}}(\mathbf{x}^*), \mathbf{F} \right), \label{eq:gh_expression}
\end{equation}
where $\widehat{\Pi}_{\boldsymbol{\Phi}}(\mathbf{x}^*)$ denotes embedding of the vector ${\Pi}_{\boldsymbol{\Phi}}(\mathbf{x}^*)$. Using the same isometric property, the Hausdorff distance between $\mathbf{F}^\prime$ and $\mathbf{F}$ can be expressed in terms of Equation~$\eqref{eqn:init-dist}$. This follows from the fact that
\begin{align}
\lVert \Pi_{\mathbf{\boldsymbol{\Phi}}} \left( \mathbf{x}_i^* - F(\mathbf{s}(t_{p, i})) \right) \rVert_2 
    \begin{aligned}[t]
    & = \lVert \Pi_{\mathbf{\boldsymbol{\Phi}}} \left( F^*(\mathbf{s}(t_{p, i}))  -F(\mathbf{s}(t_{p, i})) \right) \rVert_2 \\
    & \le 
    \lVert F^*(\mathbf{s}(t_{p, i}))  -F(\mathbf{s}(t_{p, i})) \rVert_2  \lVert (\boldsymbol{\Phi}^H\boldsymbol{\Phi})^\dagger \boldsymbol{\Phi}^H \rVert_2.
    %& \le \lVert F^*(\mathbf{s}(t_{p, i}))  -F(\mathbf{s}(t_{p, i})) \rVert_2.
    \end{aligned}
    \label{eqn:denoising-bound}
\end{align}
%
The matrix $\boldsymbol{\Phi}^H\boldsymbol{\Phi}$ has the form:
%
\begin{equation}
    \boldsymbol{\Phi}^H\boldsymbol{\Phi} = 
    \begin{bmatrix}
        n & \sum_{k = 1}^n e^{j 2\pi (w_2 - w_1)f_k} & \cdots & \sum_{k = 1}^n e^{j 2\pi (w_n - w_1)f_k} \vspace{0.5cm} \\ 
        \sum_{k = 1}^n e^{-j 2\pi (w_2 - w_1)f_k} & n & \cdots & \sum_{k = 1}^n e^{j 2\pi (w_n - w_2)f_k} \vspace{0.5cm} \\
        \vdots & \vdots & \cdots & \vdots \vspace{0.5cm} \\
        \sum_{k = 1}^n e^{-j 2\pi (w_n - w_1)f_k} &  \sum_{k = 1}^n e^{-j 2\pi (w_n - w_2)f_k} & \cdots & n
    \end{bmatrix}.
\end{equation}
%
The modulus of off-diagonal elements of $\boldsymbol{\Phi}^H\boldsymbol{\Phi}$ is bounded as
\begin{equation}
    \left|\sum_{k = 1}^n e^{j 2\pi (w_{l_1} - w_{l_2})f_k}\right|
    \le \sum_{k = 1}^n \left| e^{j 2\pi (w_{l_1} - w_{l_2})f_k}\right| = n.
    \label{eqn:modulus-bound}
\end{equation}
Observe that $\lVert (\boldsymbol{\Phi}^H\boldsymbol{\Phi})^\dagger \boldsymbol{\Phi}^H \rVert_2 \le  \lVert (\boldsymbol{\Phi}^H\boldsymbol{\Phi})^\dagger \rVert_2  \lVert\boldsymbol{\Phi}^H \rVert_2$. First we bound $\lVert\boldsymbol{\Phi}^H \rVert_2$, by directly using the definition:
\begin{equation}
    \lVert\boldsymbol{\Phi}^H \rVert_2 = \sqrt{\lambda_{\text{max}}(\boldsymbol{\Phi}\boldsymbol{\Phi}^H)},
\end{equation}
where $\lambda_{\text{max}}(\boldsymbol{\Phi}\boldsymbol{\Phi}^H)$ is the maximum eigenvalue of $\boldsymbol{\Phi}\boldsymbol{\Phi}^H$.  Since $\boldsymbol{\Phi}\boldsymbol{\Phi}^H$ is Toeplitz, a bound on the maximum eigenvalue can be established as follows \citep{hertz1992simple}.
Let $\boldsymbol{\psi} = \left[ \psi_1, \psi_2, \cdots, \psi_n \right]^\top$ be a vector such that $\psi_1 = 1$ and 
\begin{equation}
    \psi_k = 2* \cos\left( \frac{\pi}{ \lfloor (n-1)/(k-1) \rfloor + 2 }  \right), \quad k = 2, \cdots, n.
\end{equation}
Also, let $\boldsymbol{\zeta} = \left[|(\boldsymbol{\Phi} \boldsymbol{\Phi}^H)_{1,1}|, | (\boldsymbol{\Phi} \boldsymbol{\Phi}^H)_{1,2}|, \cdots, |(\boldsymbol{\Phi} \boldsymbol{\Phi}^H)_{1,n}|\right]^\top$, that is, the modulus of the terms in first row of $\boldsymbol{\Phi} \boldsymbol{\Phi}^H$.
Let $\lambda_k$ be the $k$-th eigenvalue of $\boldsymbol{\Phi} \boldsymbol{\Phi}^H$. Then it follows that \citep{hertz1992simple}:
\begin{equation}
    \max_{1 \le k \le n}(\lambda_k) \le \boldsymbol{\zeta}^T \boldsymbol{\psi}.
\end{equation}
Further observe that $\max_{1 \le k \le n} (\psi_k) = 2$, hence, together with the bound on the values of $\boldsymbol{\zeta}$ from Equation~\eqref{eqn:modulus-bound} it follows that
\begin{align}
    \boldsymbol{\zeta}^T \boldsymbol{\psi}
    \begin{aligned}[t]
        & = n + \sum_{k = 2}^n |(\boldsymbol{\Phi} \boldsymbol{\Phi}^H)_{1,k}| \psi_k 
        & \le \left(n + n \sum_{k = 2}^n 2\right) = 2n^2 - n.
    \end{aligned}
    \label{eqn:bound-eig-val}
\end{align}
Hence the norm $\lVert {{\boldsymbol{\Phi}}}^H \rVert_2 \le 2n^2 - n$. It now remains to bound the quantity $\lVert (\boldsymbol{\Phi}^H\boldsymbol{\Phi})^\dagger \rVert_2$. By computing the singular value decomposition of $\lVert (\boldsymbol{\Phi}^H\boldsymbol{\Phi})^\dagger \rVert_2$, it follows directly that 
\begin{equation}
    \lVert (\boldsymbol{\Phi}^H\boldsymbol{\Phi})^\dagger \rVert_2 \le \frac{1}{\sigma^2_{\text{min}}(\boldsymbol{\Phi})},
    \label{eqn:svd-bound}
\end{equation}
where $\sigma^2_{\text{min}}(\boldsymbol{\Phi}) > 0$ is the smallest non-zero singular value of $\boldsymbol{\Phi}$. Using the fact that 
\begin{equation}
    \sum_{k = 1}^n  \lambda_k(\boldsymbol{\Phi}^H\boldsymbol{\Phi}) = \text{Tr}(\boldsymbol{\Phi}^H\boldsymbol{\Phi}) = n^2,
\end{equation}
where $\text{Tr}(\boldsymbol{\Phi}^H\boldsymbol{\Phi})$ is the matrix trace, it follows that the smallest non-zero eigenvalue is bounded as $0 < \lambda_{\text{min}}(\boldsymbol{\Phi}^H\boldsymbol{\Phi}) \le n$ which implies that $\sigma^2_{\text{min}}(\boldsymbol{\Phi}^H\boldsymbol{\Phi}) \le n$. For any such that $\sigma^2_{\text{min}}(\boldsymbol{\Phi}^H\boldsymbol{\Phi})$, we can always find a $0< \gamma \le 1$ such that $\sigma^2_{\text{min}}(\boldsymbol{\Phi}^H\boldsymbol{\Phi}) > {\gamma n}$. Hence the bound in Equation~\eqref{eqn:svd-bound} can be extended to 
\begin{equation}
    \lVert (\boldsymbol{\Phi}^H\boldsymbol{\Phi})^\dagger \rVert_2 \le \frac{1}{\sigma^2_{\text{min}}(\boldsymbol{\Phi})} \le \frac{1}{\gamma n}.
    \label{eqn:svd-bound-2}
\end{equation}
Now using the bound in Equations~\eqref{eqn:bound-eig-val} and ~\eqref{eqn:svd-bound-2}, the bound in Equation~\eqref{eqn:denoising-bound} has the form
\begin{equation}
    \lVert \Pi_{\mathbf{\boldsymbol{\Phi}}} \left( \mathbf{x}_i^* - F(\mathbf{s}(t_{p, i})) \right) \rVert_2 \le 
    \frac{2n - 1}{\gamma}\lVert F^*(\mathbf{s}(t_{p, i}))  -F(\mathbf{s}(t_{p, i})) \rVert_2
    \label{eqn:denoising-bound-2}
\end{equation}
The bound on the Hausdorff distance between $\mathbf{F}^\prime$ and $\mathbf{F}$ is then expressed as
\begin{align}
\text{d}_\text{H}(\widehat{\Pi}_{\boldsymbol{\Phi}}(\mathbf{x}^*), \mathbf{F})
    \begin{aligned}[t]
    & \le \sup\limits_{i, p}\lVert \Pi_{\mathbf{\boldsymbol{\Phi}}} \left( \mathbf{x}_i^* - F(\mathbf{s}(t_{p, i})) \right) \rVert_2 \\
    & \le \frac{2n - 1}{\gamma} \sup\limits_{i, p}\lVert F^*(\mathbf{s}(t_{p, i})) - F(\mathbf{s}(t_{p, i})) \rVert_2, 1 \le i \le n_p - M\tau_p, 1 \le p \le P.
    \end{aligned}
    \label{eqn:hausdorff-bound}
\end{align}
From the equality in Equation~\eqref{eq:gh_expression}, it holds that
\begin{equation}
    \text{d}_\text{B}(\text{Dgm}({\mathbf{F}}), \text{Dgm}({\mathbf{F}^\prime})) \le 2\text{d}_{\textbf{GH}}\left( \mathbf{F}, \mathbf{F}^\prime \right)  =  2\text{d}_{\textbf{GH}}\left( \widehat{\Pi}_{\boldsymbol{\Phi}}(\mathbf{x}^*), \mathbf{F} \right). 
\end{equation}
The Gromov-Hausdorff distance is further bounded above by the Hausdorff distance. From Equations~\eqref{eqn:hausdorff-bound}, the bound on the bottleneck distance between $\text{Dgm}({\mathbf{F}})$ and $\text{Dgm}({\mathbf{F}^\prime})$ is established as
\begin{equation}
    \text{d}_\text{B}(\text{Dgm}({\mathbf{F}}), \text{Dgm}({\mathbf{F}^\prime})) \le \frac{4n - 2}{\gamma} \left(\sup\limits_{i, p}||F^*(\mathbf{s}(t_{p, i})) - F(\mathbf{s}(t_{p, i}))||_2\right),
\end{equation}
where $1 \le i \le n_p - M\tau_p, \quad 1 \le p \le P$.
If the observed time series is `noise-free' such that $\mathbf{x}^* = \mathbf{x}$, then $\sup\limits_{i, p}||F(\mathbf{s}(t_{p, i})) - F^*(\mathbf{s}(t_{p, i}))||_2=0, \forall i, p$, and $\text{d}_\text{B}(\text{Dgm}({\mathbf{F}}), \text{Dgm}({\mathbf{F}^\prime})) = 0$.
\end{proof}



\subsection{Proof of Lemma 4.2}

\begin{proof}
    By construction, $\mathbf{F}^2 \subset \widehat{\mathbf{F}}^2$, thus for any $F^2(s(t_{p, i_1})) \in \mathbf{F}^2$, $\exists \widehat{F}^2(s(t_{p, i_2})) \in \widehat{\mathbf{F}}^2$ such that $F^2(s(t_{p, i_1})) = \widehat{F}^2(s(t_{p, i_2}))$. Further observe that $|\mathbf{F}^2|_u = |\hat{\mathbf{F}}^2|_u$, where $|.|_u$ is a measure of the cardinality of unique observations. Hence it follows that $\text{Dgm}(\mathbf{F}^2) \equiv \text{Dgm}(\widehat{\mathbf{F}}^2)$, and the conclusion is a direct consequence of this equivalence.
