\subsection{Proof of Theorem 4.5}

\begin{proof}
By construction of the subsequence and assumption \textbf{A2}, the Hausdorff distance between $\mathbf{F}_m$ and $\mathbf{F}_\vartheta$ has the form
\begin{equation}
    \text{d}_\text{H}(\mathbf{F}_m, \mathbf{F}_\vartheta) = \sup_{F_\vartheta \in \mathbf{F}_\vartheta} \min_{1 \le i \le m} \lVert F(s(t_i)) - F_\vartheta \rVert_2.
    \label{eqn:subset-hausdorff}
\end{equation}
Let $\mathbf{F}_0 \subset \mathbf{F}_\vartheta $ be a set of ball centers such that
\begin{equation}
    \mathbf{F}_\vartheta \subset \bigcup_{F_0 \in \mathbf{F}_0} B(F_0, \delta),
    \label{eqn:covering}
\end{equation}
i.e., the minimal covering of $\mathbf{F}_\vartheta$ consisting of balls of radius $\delta$ around $F_0 \in \mathbf{F}_0$.
For any $F_\vartheta \in \mathbf{F}_\vartheta$ and $F_0 \in \mathbf{F}_0$, the following inequality holds:
\begin{align}
    \min_{1 \le i \le m} \lVert F(s(t_i))-F_\vartheta  \rVert_2
    \begin{aligned}[t]
     & \le \lVert F(s(t_j)) - F_\vartheta \rVert_2\\
     & = \lVert F(s(t_j)) - F_0  + F_0  - F_\vartheta \rVert_2\\
     & \le \lVert F(s(t_j)) - F_0 \rVert_2 + \lVert F_0 - F_\vartheta \rVert_2,\quad j = 1, \cdots, m.
    \end{aligned}
    \label{eqn:min-bound}
\end{align}
Observe that $\lVert F_0 - F_\vartheta \rVert_2$ is bounded by the radius $\delta$, hence using Equation \eqref{eqn:covering}, it follows that 
\begin{equation}
    \min_{1 \le i \le m} \lVert F(s(t_i)) - F_\vartheta \rVert_2 \le \delta + \max_{F_0 \in \mathbf{F}_0} \min_{1 \le i \le m} \lVert F(s(t_i)) - F_0 \rVert_2 \le \varepsilon,
\end{equation}
for some $\epsilon > 0$. Further, taking the supremum over all $F_\vartheta$, the relation still holds:
\begin{equation}
    \sup_{F_\vartheta \in \mathbf{F}_\vartheta}\min_{1 \le i \le m} \lVert F(s(t_i)) - F_\vartheta \rVert_2 \le \delta + \max_{F_0 \in \mathbf{F}_0} \min_{1 \le i \le m} \lVert F(s(t_i)) - F_0 \rVert_2 \le \varepsilon,
\end{equation}
Then the probability that $\sup_{F_\vartheta \in \mathbf{F}_\vartheta}\min_{1 \le i \le m} \lVert F(s(t_i)) - F_\vartheta \rVert_2$ exceeds $\varepsilon$ is bounded as
\begin{align}
    \text{Pr}\left(\sup_{F_\vartheta \in \mathbf{F}_\vartheta}\min_{1 \le i \le m} \lVert F(s(t_i)) - F_\vartheta \rVert_2 > \varepsilon\right)
    \begin{aligned}[t]
        & \le \text{Pr}\left(\delta + \max_{F_0 \in \mathbf{F}_0} \min_{1 \le i \le m} \lVert F(s(t_i)) - F_0 \rVert_2 > \varepsilon\right)\\
        & = \text{Pr}\left(\max_{F_0 \in \mathbf{F}_0} \min_{1 \le i \le m} \lVert F(s(t_i)) - F_0 \rVert_2 > \varepsilon - \delta \right)
    \end{aligned}
\end{align}
From~Equation \eqref{eqn:subset-hausdorff}, $\sup_{F_\vartheta \in \mathbf{F}_\vartheta} \min_{1 \le i \le m} \lVert F(s(t_i)) - F_\vartheta \rVert_2 = \text{d}_\text{H}(\mathbf{F}_m, \mathbf{F}_\vartheta)$, hence a bound on the probability of $\text{d}_\text{H}(\mathbf{F}_m, \mathbf{F}_\vartheta)$ exceeding $\varepsilon$ can be obtained as 
\begin{equation}
    \text{Pr}\left(\text{d}_\text{H}(\mathbf{F}_m, \mathbf{F}_\vartheta) > \varepsilon\right) \le \text{Pr}\left(\max_{F_0 \in \mathbf{F}_0} \min_{1 \le i \le m} \lVert F(s(t_i)) - F_0  \rVert_2 > \varepsilon - \delta\right).
    \label{eqn:prob-bound-hd}
\end{equation}
Observe that $\mathbf{F}_\vartheta$ endowed with the Hausdorff metric is complete and separable \citep{attouch1991topology}. Then for $\varepsilon$ small enough, the following bound holds \citep{cuevas2004boundary}:
\begin{equation}
    \text{Pr}\left(\max_{F_0 \in \mathbf{F}_0} \min_{1 \le i \le m} \lVert F(s(t_i)) - F_0 \rVert_2 > \varepsilon - \delta\right) \le C \left(1- \kappa\omega(\varepsilon - \delta)^{M+1}\right)^m.
    \label{eqn:prob-bound}
\end{equation}
The constant $C$ is the number of points in the covering of $\mathbf{F}_\vartheta$, i.e., $|\mathbf{F}_0|$, and $\omega$ is the Lebesgue measure of the unit ball in $\mathbb{R}^{M+1}$.
Note  that since $0 \le \kappa \omega(\varepsilon - \delta)^{M+1} \le 1$, it follows that $\left(1 - \kappa \omega(\varepsilon - \delta)^{M+1}\right)^m \le e^{-m\kappa \omega(\varepsilon - \delta)^{M+1}}$.  This allows for Equations \eqref{eqn:prob-bound-hd} and \eqref{eqn:prob-bound} to be rewritten as 
\begin{equation}
     \text{Pr}\left(\text{d}_\text{H}(\mathbf{F}_m, \mathbf{F}_\vartheta) > \varepsilon\right) \le \text{Pr}\left(\max_{F_0 \in \mathbf{F}_0} \min_{1 \le i \le m} \lVert F(s(t_i)) - F_0 \rVert_2 > \varepsilon - \delta\right) \le C e^{-m\kappa \omega(\varepsilon - \delta)^{M+1}}.
    \label{eqn:prob-bound-2}
\end{equation}
Choose some $K > \left( \frac{2}{\kappa \omega} \right)^\frac{1}{M+1}$ and let $\varepsilon_m(r) = \left(r - \frac{m-l}{m}\right)$, where $l$ is the number of missing observations in the initial time series and $m \gg l$, then for $m$ large enough, it follows that 
\begin{equation}
     \text{Pr}\left(  \left( \varepsilon_m(r) \right)^{-\frac{1}{M+1}} \text{d}_\text{H}(\mathbf{F}_m, \mathbf{F}_\vartheta) > K \right) \le C e^{-m\kappa \omega\left( (\varepsilon_m(r)\frac{2}{\kappa\omega})^{\frac{1}{M+1}} - \delta\right)^{M+1}}.
    \label{eqn:prob-bound-3}
\end{equation}
The above bound can be obtained by simply substituting $\left(\frac{2\varepsilon_m(r)}{\kappa\omega}\right)^\frac{1}{M+1}$ for $\varepsilon$ in Equation \eqref{eqn:prob-bound-2}.
Now consider the sum 
\begin{equation}
    \sum_{m}  e^{-m\kappa \omega\left( (\varepsilon_m(r)\frac{2}{\kappa\omega})^{\frac{1}{M+1}} - \delta\right)^{M+1}},
\end{equation}
and observe that it is convergent if $\varepsilon_m(r) \ge \left( \frac{\delta}{K} \right)^{M+1}$. This condition can always be satisfied given the restriction $K > \left( \frac{2}{\kappa \omega} \right)^\frac{1}{M+1}$ and for an appropriate choice of $\kappa$ and $\delta$. Then by the Borel-Cantelli lemma \citep{emile1909probabilites,cantelli1917sulla,chung1952application}, since 
\begin{equation}
    \sum_m \text{Pr}\left(  \left( \varepsilon_m(r) \right)^{-\frac{1}{M+1}} \text{d}_\text{H}(\mathbf{F}_m, \mathbf{F}_\vartheta) > K \right) < \infty,
\end{equation}
it follows that
\begin{equation}
    \lim_{m \xrightarrow{} \infty} \sup  \left( \varepsilon_m(r) \right)^{-\frac{1}{M+1}} \text{d}_\text{H}(\mathbf{F}_m, \mathbf{F}_\vartheta) \le K.
    \label{eqn:final-proof}
\end{equation}
\end{proof}


