    \includegraphics[width=1\textwidth,clip=true]{graphs/exo-planet-signals.png}
    \caption{Exoplanet time-series data.  Simulated RV data of an exoplanet (red circles), a 0.05\% spot (blue squares), and the planet and spot combined (green triangles).}
    \label{fig:exo-planet-signals}
\end{figure}
