\section{Proof of \texorpdfstring{\cref{item:prop:hitting-time-2}}{Item 2} of \texorpdfstring{\cref{prop:hitting-time}}{Proposition 3.10}} \label{app:missing proofs-no-stop}
\begin{proof}
    For any $a\geq2$, $1\leq i<a$, it holds that
    \begin{align}\label{eq:no-stop-rec}
        \Pr{\tau_{-a} = \infty}
        &=\Pr{\tau_{-i} = \infty \wedge \tau_{-a} = \infty} + \sum_{j=1}^{\infty} \Pr{\tau_{-i} = j \wedge \tau_{-a} = \infty}\nonumber\\
        &=\Pr{\tau_{-i} = \infty} + \sum_{j=1}^{\infty} \Pr{\tau_{-i} = j} \Pr{\tau_{-a} = \infty \mid \tau_{-i} = j} \nonumber\\
        &=\Pr{\tau_{-i} = \infty} + \sum_{j=1}^{\infty} \Pr{\tau_{-i} = j} \Pr{\tau_{-(a-i)} = \infty}  \nonumber\\
        &=\Pr{\tau_{-i} = \infty} + \Pr{\tau_{-(a-i)} = \infty}\sum_{j=1}^{\infty} \Pr{\tau_{-i} = j} \nonumber\\
        &=\Pr{\tau_{-i} = \infty} + \Pr{\tau_{-(a-i)} = \infty}\tp{1- \Pr{\tau_{-i} = \infty}}.
    \end{align}
    We first prove the equality of \cref{item:prop:hitting-time-2} of \cref{prop:hitting-time}, i.e.,
    \begin{align}\label{eq:no-stop-prob}
        \Pr{\tau_{-a} =\infty} = 1-\tp{1- \Pr{\tau_{-1} =\infty}}^a
    \end{align}
    by induction.

    For the base case $a=1$, \cref{eq:no-stop-prob} holds trivially.

    For any $a\geq2$, suppose \cref{eq:no-stop-prob} holds for $a-1$.
    Applying \cref{eq:no-stop-rec} with $i=1$, we have
    \begin{align*}
        \Pr{\tau_{-a} = \infty}
        &=\Pr{\tau_{-1} = \infty} + \Pr{\tau_{-(a-1)} = \infty}\tp{1- \Pr{\tau_{-1} = \infty}}\\
        &=\Pr{\tau_{-1} = \infty} + \tp{1-\tp{1- \Pr{\tau_{-1} =\infty}}^{a-1}}\tp{1- \Pr{\tau_{-1} = \infty}}\\
        &=1-\tp{1- \Pr{\tau_{-1} =\infty}}^a,
    \end{align*}
    which implies \cref{eq:no-stop-prob} holds for $a$.
    Therefore, by the induction principle, \cref{eq:no-stop-prob} holds for any $a\in\Z^+$.
    We next prove the inequality of \cref{item:prop:hitting-time-2} of \cref{prop:hitting-time}.
    Indeed, for any $a\in\Z^+$,
    \begin{align*}
        1-\tp{1- \Pr{\tau_{-1} =\infty}}^a \leq 1-\tp{1- a\Pr{\tau_{-1} =\infty}}=a\Pr{\tau_{-1} =\infty},
    \end{align*}
    where the inequality follows from Bernoulli's inequality.
\end{proof}


