# - QUBO Model for MWIS
def get_MWIS_QUBO(graph: nx.Graph, penalty_rate=1):
    weight_set = np.array(
        [graph.nodes(data=True)[i]['weight'] for i in range(graph.number_of_nodes())])
    problem_QUBO={}
    for i in range(graph.number_of_nodes()):
        problem_QUBO[(i,)]=weight_set[i]
        for _,j in graph.edges(i):
            problem_QUBO[(i,)]-=(weight_set[i]+weight_set[i])*penalty_rate/2
            if i < j:
                problem_QUBO[(i, j)]=(weight_set[i]+weight_set[i])*penalty_rate/2
    return problem_QUBO
...
# - Problem Operator
def problem_operator(p_QUBO:dict, qubits, p, gamma):
    key_iter=sorted(p_QUBO.keys(), key=lambda x: (len(x), x))
    for nodes in key_iter:
        for i in range(len(nodes)-1):
            yield cirq.CNOT(qubits[nodes[i]], qubits[nodes[i+1]])
        yield cirq.rz(gamma[p]*p_QUBO[nodes])(qubits[nodes[-1]])
        for i in range(len(nodes)-1):
            yield cirq.CNOT(qubits[nodes[i]], qubits[nodes[i+1]])
...
# - Mixing Operator   
def mixing_operator(mwis_graph, qubits, p, beta):
    for node in mwis_graph.nodes:
        yield cirq.rx(2*beta[p])(qubits[node])
